pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // awkward gap (items >= 10 can fit but barely)
        }
    } else {
        score -= 40.0; // perfect closure is highly desirable
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else if post_residual > 0 && (next_item_size as u64) > (post_residual as u64) {
            score += 8.0; // next item won't fit here; dead space likely
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fill < 0.55 {
            score += 45.0; // discourage opening new bin when open bins are loose
        } else {
            score -= 5.0; // mildly encourage fresh bin when existing ones are crowded
        }
    }

    // Late-stream consolidation: as stream progresses, favor reusing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (bins can still be filled).
    // Late in the stream: strongly penalize residual (dead space is costly).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    score += 0.6 * w_late * pr * (pr / cap);
    score -= 0.4 * w_early * pr * (1.0 - pr / cap);

    // Penalize residual far from "useful" sizes: quadratic deviation from mean residual
    // creates a smooth basin around average slack, avoiding dead-space extremes.
    let dev = pr - mean_residual;
    score += 0.15 * (dev * dev) / cap;

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tight = 1.0 - ((pr - nxt) / cap);
            score -= 1.5 * tight * nxt / cap;
        } else {
            // Post-residual cannot host next item: smooth dead-space penalty.
            let waste = (nxt - pr) / cap;
            score += 0.8 * waste * waste;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 3.0 + 0.5 * (item_size as f64 / cap);
    } else if fitting_bins_count > 1 {
        // Mild competition pressure: prefer bins with less post-residual among many options.
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Reward closing bins tightly (near-zero residual) with smooth saturation.
    let tightness = 1.0 - (pr / cap);
    score -= 0.5 * tightness * tightness * (1.0 - w_early);

    // Mild penalty for proliferating bins late in the stream.
    score += 0.05 * w_late * (open_bins_count as f64).sqrt();

    // New-bin candidate: make empty bins attractive only when item is large or
    // current residual would leave big unusable gap.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        let gap_benefit = if next_item_size > 0 { ((pr as u32) >= next_item_size) as f64 } else { 0.0 };
        score = 2.0 + 4.0 * (1.0 - large_item) - 1.0 * gap_benefit - 2.0 * w_late * large_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Items 1..=100; gaps below ~10 (min item size) are pure waste,
        // gaps below 20 are hard to fill too.
        if dead < 10.0 {
            score += 500.0; // absolute dead space
        } else if dead < 20.0 {
            score += 150.0;
        } else if dead < 35.0 {
            score += 40.0;
        }
        // Smooth penalty proportional to unusability: gap that can't fit next item
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 30.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio;

    // Open bins pressure: discourage spreading into too many bins,
    // but allow new bin when current bins are crowded (mean residual low).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += 0.5 * pressure;

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are poor fits
    if bin_residual == bin_capacity {
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // opening a new bin wastes the mean residual of all open bins
        score += 60.0 + 0.3 * avg_open_residual;
        // but if this is a huge item with few fitting bins, opening is fine
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Mean residual coupling: prefer bins close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    let gap = post_residual;
    if gap > 0 {
        // Unusable small gap (nothing but tiny items could fit): strong penalty.
        if gap < 10 {
            score += 60.0;
        } else if gap <= 15 {
            score += 25.0;
        } else if gap < 30 {
            score += 8.0;
        }
        // Perfect fit bonus.
        if gap == 0 {
            score -= 100.0;
        }
    } else {
        score -= 100.0;
    }

    // Reward residual sizes that are likely reusable by future items
    // (aligned with common item sizes in the 10..80 range).
    if gap >= 10 && gap <= 80 {
        score -= 10.0;
        // Extra reward for "round" residuals that match typical item sizes.
        if gap % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last chance: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — favor using it (its space is scarce).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.4;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits but not quite (wasted setup).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score += 12.0;
    }

    // New-bin candidate handling: empty bin starts with high residual;
    // make it attractive only when the item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins happily; small items should use existing space.
        score -= load * 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if item_size <= 20 && fitting_bins_count > 1 {
            score += 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals that lie in "useful" residue classes.
    // Small post-residuals are good; multiples of common item-size classes are reusable.
    let pr = post_residual;
    if pr > 0 {
        // class of pr modulo 10: residues near 0 (10,20,...) are highly reusable
        let m = (pr % 10) as f64;
        score -= (10.0 - m) * 0.35; // residues divisible by 10 get biggest bonus
        if pr % 20 == 0 {
            score -= 4.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        // dead-space penalty for tiny unusable slivers
        if pr < 10 {
            score += 12.0;
        }
    } else {
        score -= 10.0; // perfect fit
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= 6.0;
        } else {
            score += 3.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Empty new-bin candidate: neutral baseline, only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.2 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    // Tightness reward: prefer bins that become nearly full
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 5.0;

    // Slight preference to balance residual against mean as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).abs() * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item (1..100 stream) become permanent waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Non-linear penalty for mid-range dead space (fits nothing useful later).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Perfect-fill lookahead: if the next item exactly consumes post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item can also land here (chained packing).
        score -= (post_residual - next_item_size) as f64 * 0.15;
    }

    // Last-chance bin before opening a new one: strong preference to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // the emptier a bin is relative to the mean, the less we want to
    // fragment it further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 8.0; // penalize dumping into unusually empty bins
    }

    // New-bin candidate: allow opening a fresh bin only when current item
    // is large and would leave a clean, usable residual, or when the only
    // alternative is a very poor fit.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55; // default: prefer existing bins
        let poor_fit = (post_residual as f64) < 15.0 && post_residual > 0;
        if poor_fit || item_size >= 70 {
            score = base - 18.0; // open new bin for clean placement
        } else {
            score = base + 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.4 * slack; // penalize leftover after next item
        } else {
            // next item won't fit here; penalize small unusable post_residual
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0 * (10.0 - dead);
            }
        }
    } else {
        // last item: just minimize waste
        score += 5.0 * tightness;
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidate fuller bins)
    score += 3.0 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if post_residual would be tiny waste anyway
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Late in stream: discourage opening bins, prefer filling existing ones
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Slight penalty for many open bins already (fragmentation control)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

