    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // marginal gap
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that the lookahead item could exactly fill
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_diff = post_residual - next_item_size;
        if gap_diff == 0 {
            score -= 20.0;
        } else if gap_diff < 10 {
            score -= 6.0;
        }
    }
    // Penalize if post_residual is just below the next item (dead space for lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across too many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + progress) * 0.5;

    // Prefer bins below mean residual (fill emptier bins less aggressively)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.5;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
