    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect-fit bonus when the leftover could host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leftover can still host next item: mildly good
        score -= 10.0;
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, tolerate opening new bins less.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0;

    // New-bin candidate handling: empty bin gets a moderate default score so
    // it is chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + pressure * 4.0;
        // if no open bin fits at all, new bin must win
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight nudge toward bins tighter than average (best-fit flavor).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

