}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty: quadratic in how small the leftover is.
        let dead = post_residual as f64;
        score += (bin_capacity as f64 - dead) * 0.0; // no-op keep clarity
        score += (dead / bin_capacity as f64).powi(2) * 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual will fit the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward tight two-item packing.
            if slack_after_next == 0 {
                score -= 700.0;
            } else {
                score -= 200.0 - (slack_after_next as f64 / bin_capacity as f64) * 150.0;
            }
        } else {
            // Next item won't fit here after placing current item: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    } else {
        // Last item: any placement that empties residual is great.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0 + (item_size as f64 / bin_residual.max(1) as f64) * 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it only
    // when the fit here would create large dead space and open bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight bias against new bins early, stronger late (consolidate at end).
        score += 30.0 + progress * 60.0;
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.5;
    } else {
        // Prefer bins tighter than the mean residual (best-fit flavor).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild preference for reusing many open bins rather than spreading.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
