}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // denominators (10, 20, 25, 50) are more likely to be filled later,
    // so reward them (subtract), odd/prime-ish residues are dead space (add).
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 8.0;
        if pr % 50 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.0; }
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else if pr < 10 {
        score += 12.0; // tiny unusable sliver
    } else {
        score += 4.0;
    }

    // Integer-division threshold: does the NEXT item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chains nicely
            // harmonic pairing: next item leaves another "nice" residue
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            if pr2 == 0 { score -= 6.0; }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Capacity fraction coupling: residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    if frac < 0.1 { score += 5.0 * (0.1 - frac) * 10.0; } // penalize small fractions
    else if frac > 0.6 { score += 3.0; } // too empty, wasteful use of an open bin

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // mean residual of open bins is small (nothing useful to pack into).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_frac = mean_residual / cap;
        score -= 20.0 * (1.0 - mean_frac); // open bins are nearly full -> new bin good
        score -= 10.0 * progress;
        if item_size > 50 { score -= 5.0; }
        if fitting_bins_count > 0 { score += 10.0; } // discourage skipping usable bins
    }

    // Mild penalty for proliferating bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable gap (smaller than any possible item): heavy penalty.
            score += 500.0;
        } else if post_residual <= 20 {
            // Very hard to fill later: strong penalty.
            score += 120.0;
        } else if post_residual <= 35 {
            // Moderately awkward gap.
            score += 30.0;
        } else {
            // Large gaps remain usable; mild super-linear penalty.
            score += 0.05 * (post_residual as f64);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 60.0 + 8.0 * open_bins_count as f64;
        // Early in the stream, opening bins is fine; later, strongly discourage.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 100.0 * progress;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && !new_bin {
        score -= 150.0;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly fills the
    // post-residual, this is a perfect chain placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next == post {
            score -= 500.0;
        } else if next <= post {
            // Next item fits inside this bin's leftover: mild reward,
            // scaled by how snugly it nests.
            let nesting = 1.0 - (post - next) / post.max(1.0);
            score -= 60.0 * nesting;
        } else {
            // Next item cannot use the leftover: penalize large dead space
            // that is smaller than the upcoming item (likely wasted).
            if post < next {
                score += 0.5 * (next - post);
            }
        }
    }

    // Compare against mean residual: bins with less residual than average
    // are "tighter" — filling them is efficient.
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if (post_residual as f64) < mean {
        score -= 0.6 * (mean - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual (i.e., no existing bin fits well).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.8 {
            score -= 120.0; // big item: fresh bin is fine
        } else {
            score += 40.0 + 60.0 * (1.0 - fill_ratio); // penalize wasting a fresh bin
        }
    }

    // Late in the stream, prefer closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize dead space quadratically, scaled by capacity.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 30.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Early in stream: be more exploratory (penalize tight packing less),
    // late in stream: pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mean residual coupling: if mean residual is high, prefer filling large gaps.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // New empty bin candidate: only attractive when item is huge relative to
    // residual options or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.8 {
            score -= 20.0; // big item: fresh bin is fine
        } else {
            score += 25.0; // discourage opening new bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // 0..1 residual fraction after placement
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64; // tightness of fit

    // Base: penalize wasted residual, quadratically (dead space is doubly bad)
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth non-linear coupling of residual waste with stream progress:
    // early on, keep bins flexible (favor larger residual); late, pack tightly.
    let progress_waste = post * (0.5 + 1.5 * progress * progress);
    score += progress_waste - post * 0.5; // recenter so it's a smooth modulation

    // Reward tight fits with a smooth saturating term
    score -= fit_ratio * fit_ratio * 30.0;

    // Interaction: residual vs. mean residual — prefer bins below-average residual
    // (i.e., filling fuller bins first), smoothly scaled.
    let dev = (mean_residual - post) / cap;
    score -= dev * dev * 20.0;
    score -= dev * 10.0;

    // Lookahead coupling: if next item fits the post residual, reward this placement
    // with a smooth bell-shaped bonus peaking at perfect next-fit.
    if next_item_size > 0 {
        let gap = (post as u32).min(next_item_size).max((post as i64 - next_item_size as i64).max(0) as u32) as f64;
        let next_fit = next_item_size as f64;
        if next_fit <= post {
            let tightness = 1.0 - (post - next_fit) / cap;
            score -= 15.0 * tightness * tightness;
        }
        let _ = gap;
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it (smooth in 1/n)
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score -= 25.0 / fitting_bins_count as f64;
    }

    // Mild penalty on bin proliferation, smoothly damped by progress
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact capacity fractions are "good" dead space
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward residuals that land on harmonic fractions of capacity (0, 1/4, 1/3, 1/2, 2/3, 3/4)
    let harmonics: [f64; 6] = [0.0, 0.25, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.75];
    let mut h_bonus = 0.0;
    for h in harmonics.iter() {
        let d = (frac - h).abs();
        if d < 0.06 {
            h_bonus += (0.06 - d) * 60.0;
        }
    }
    score -= h_bonus;

    // Modulo classes: residuals divisible by 10 pair well with item sizes divisible by 10
    let pr_mod = post_residual % 10;
    let item_mod = item_size % 10;
    if pr_mod == 0 && item_mod == 0 {
        score -= 8.0;
    } else if pr_mod == 0 {
        score -= 3.0;
    }

    // Penalize tiny unusable residuals (dead space) unless they are exact zero
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is gold
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post residual can't host next item: penalize proportionally to wasted potential
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Prefer filling already-open bins when many are open; new bin is a fallback
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64).sqrt() * 4.0;
        // But if no open bin fits well (many fitting bins means poor competition), allow new bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // Deviation from mean residual: bins far below mean are scarce, use them wisely
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 40.0; // perfect/near-perfect closure is excellent
    } else {
        // Penalize gaps too small to hold the next item if it would otherwise
        // need a fresh bin: dead space that the lookahead cannot use.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score += 25.0;
        }
        // Reward moderately useful residual space (can host typical items).
        score -= 0.3 * (post_residual as f64).min(60.0);
        // But heavily penalize large wasted residual when bin was nearly full.
        if post_residual > 50 && post_residual < bin_capacity as f64 as u32 {
            score += 8.0;
        }
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when many items remain to serve it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 20.0 * progress;
        // If the next item is huge, a fresh bin preserves flexibility.
        if next_item_size >= 70 {
            score -= 12.0;
        }
        // If open bins are fragmented, opening fresh can be wise.
        if mean_residual < 15.0 {
            score -= 18.0;
        }
    }

    // Align with global mean residual: prefer bins that keep the fleet balanced.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (diff / (bin_capacity as f64)).exp();
        // Bonus if next item fits exactly into the post-residual space.
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // Penalize leaving dead space that next item cannot use.
        if next_item_size > post_residual {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: avoid outliers far below mean.
    score += 0.6 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
    }

    // Late in stream, tighten packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0 -> 1)
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Tightness of the fit: how well the item fills the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tight_fit = (fill_ratio - 1.0).abs() < 1e-9 || post_residual == 0;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 + 4.0 * (6.0 - post_residual as f64);
    } else {
        // Penalize dead space that is too small to be useful for typical items
        if post_residual < 10 {
            score += 25.0; // unusable sliver
        }
        // Nonlinear reward for high fill ratio
        score -= 20.0 * fill_ratio * fill_ratio;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * next_fill;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0 + 40.0 * progress;
    } else {
        // More competing bins -> slight normalization toward balanced choice
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual far from mean residual (keeps diversity of sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Early stream: encourage filling existing bins aggressively (fewer bins opened)
    score -= 30.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    // Late stream: prefer tight packing, penalize leaving large residuals
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage using large-residual bins poorly
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: make it moderately attractive only when the item is large
    // or no good fit exists elsewhere
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 35.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 10.0;
        }
    }

    // Small stabilizing term on exact fit tightness
    if tight_fit {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: post_residual shaped by progress
    let post_norm = post / cap;
    let shape = post_norm * post_norm * (1.0 - post_norm);
    score -= 40.0 * shape * (0.5 + progress);

    // Tight-fit reward, damped as stream progresses
    let tight = 1.0 - post_norm;
    score -= 25.0 * tight * tight * (1.0 - progress);

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (nxt - post) / cap * (1.0 + progress);
        } else {
            score -= 6.0 * (1.0 - (nxt - post) / cap) * progress;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Encourage filling existing bins as open count grows
    score += 0.5 * open_bins_count as f64 * post_norm;

    // Mild deviation from mean residual
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // residue classes (dead space) are penalized.
    let pr = post_residual;
    let residue = pr % 10;
    score += (10 - residue) as f64 * 0.8; // reward residuals landing on multiples of 10

    // Integer-division thresholds: residuals usable by common item sizes.
    if pr >= 80 { score -= 12.0; }
    else if pr >= 50 { score -= 6.0; }
    else if pr >= 30 { score += 2.0; }
    else if pr > 0 { score += (31 - pr) as f64 * 0.5; } // tiny dead space penalized

    // Capacity fraction coupling: how tightly the item fills the bin.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 15.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64 / cap) * 10.0;
            // harmonic match: next item leaves a multiple-of-10 residual too
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            score += 4.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // or are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let fragmentation = ((mean_residual - post_residual as f64).abs()) * 0.3;
        let late = (step_index as f64 / total_items.max(1) as f64).powi(2) * 10.0;
        score = 55.0 + pressure - fragmentation - late;
    }

    // Mild penalty for proliferating bins early.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small gaps that can still fit the known next item are valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: dead space penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, consolidation is fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (better fits).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when the item is large and
    // no open bin offers a decent fit; otherwise keep it moderately expensive.
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.3 * open_bins_count as f64;
        let poor_fit_elsewhere = if fitting_bins_count <= 1 { 0.0 } else { 15.0 };
        score += base + poor_fit_elsewhere;
        if item_size >= 50 {
            score -= 10.0; // large items justify fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a slight superlinear penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how well the next item fills the leftover space
            let next_fit = (next_item_size as f64) / (post_residual as f64);
            score -= 25.0 * next_fit;
            // Perfect chain (post_residual == next_item_size) is ideal
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // This bin becomes dead space for the next item; penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.6;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill
    let rel = (bin_residual as f64) - mean_residual;
    score -= rel * 0.15;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, avoid opening new bins; consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: neutral base, only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful for future items
    // (items are 1..=100, but small leftovers below ~10 are near-worthless).
    if post_residual < 10 {
        score += 40.0; // perfect-fit bonus via penalty on unusable remainder
    } else {
        // Residuals that can't fit the lookahead item are less useful.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
        // Residual that can exactly host the lookahead item is valuable.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against global mean residual: placing into a bin whose residual
    // deviates favorably (smaller than mean) is good.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // Discourage spreading across too many open bins early in the stream;
    // as stream progresses, consolidation pressure eases.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * 0.1;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or there are no open bins.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        // Base cost of opening a new bin, scaled by how much capacity is wasted.
        let mut new_bin_score = 55.0 + 0.2 * (waste as f64);
        // If no other bin can fit (fitting_bins_count == 0 among open bins),
        // the new bin is essentially forced — reduce its cost.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        new_bin_score += 20.0 * progress;
        // If lookahead item is large and this new bin would be nearly full,
        // opening a fresh bin is less costly.
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight packing (penalize large post_residual quadratically).
    // Late: post_residual less costly, so relax the penalty.
    let tightness = 1.0 - progress;
    score += tightness * (pr * pr) / cap;

    // Reward near-perfect fits via a smooth Gaussian-like term.
    let fit_ratio = pr / cap;
    score -= 12.0 * (-(fit_ratio * fit_ratio) / 0.02).exp();

    // Penalize dead space that cannot fit the average next need (smooth gate).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let unusable = (nxt - pr).max(0.0) / cap;
        score += 8.0 * (1.0 - progress) * (unusable * unusable) * cap / 100.0;
        // Smooth lookahead fit bonus: if next item fits after placement.
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= 4.0 * fits_next * (1.0 - fit_ratio);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    let last_chance = (fitting_bins_count == 1) as i32 as f64;
    score -= 15.0 * last_chance * (1.0 - progress * 0.5);

    // Mild penalty when bin residual deviates strongly from mean residual
    // (encourages balanced residual distribution, smooth in difference).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Slight preference for fewer open bins early (consolidation), decaying smoothly.
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (multiples of 25, or small dead space) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is always great
    } else if pr % 25 == 0 {
        score -= 12.0; // quarter-capacity harmonic classes are reusable
    } else if pr % 10 == 0 {
        score -= 6.0;  // decimal-decade residuals are moderately reusable
    } else {
        // penalize awkward residuals, worse the further from a decade boundary
        let off = pr % 10;
        let off = off.min(10 - off);
        score += off as f64 * 1.5;
    }

    // Dead-space penalty: tiny residuals that no item (min size 1, typically 10+)
    // can ever use again are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Coupling with the lookahead item: if the next item fits the post residual
    // exactly or harmonically, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 25 == 0 || nxt_post == 0 {
                score -= 18.0;
            } else if next_item_size <= pr / 2 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by how much it misses
            score += ((next_item_size - pr) as f64).min(20.0) * 0.5;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: an empty bin should only win when all open
    // bins give poor fits. Make the empty-bin baseline sit above good fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // late in the stream, opening fresh bins is less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins already: discourage spreading
        score += open_bins_count as f64 * 0.5;
    }

    // Slight tie-break toward bins below mean residual (consolidating fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. Anything <= 20 is likely unusable for typical items.
    if post_residual > 0 && post_residual <= 20 {
        score += 30.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to use it and avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 1.5 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in the post-residual, reward leaving that gap
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }
    // If post-residual is smaller than next item but next item would have fit in
    // the pre-residual, penalize blocking a slot for the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && bin_residual >= next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly penalized so it is only
    // chosen when existing bins are truly bad fits (high dead-space).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Slight preference for bins tighter than the mean (better fits)
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Primary term: minimize post_residual (tight fit preferred) ---
    score = post_residual as f64;

    // --- 2-step lookahead: reward when post_residual matches next item ---
    if next_item_size > 0 {
        let lookahead = next_item_size as f64;
        if post_residual as f64 >= lookahead {
            // Next item could fit here afterward: strong reward scaled by closeness
            let gap = post_residual as f64 - lookahead;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize dead space left behind
            let dead = post_residual as f64;
            score += 0.8 * dead;
        }
        // Exact match bonus: next item perfectly consumes post_residual
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // --- Relative-to-mean coupling: prefer bins tighter than average residual ---
    score += 0.5 * (post_residual as f64 - mean_residual);

    // --- Last-chance bin: avoid opening a new bin when this is the only fit ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- New-bin candidate handling: penalize opening a new bin unless ---
    // --- current bin leaves large unusable dead space ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // But if the current item nearly fills a bin and next item is large,
        // opening fresh may be right; relax penalty when lookahead is big
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Existing bin: small bonus to prefer using open bins
        score -= 2.0;
    }

    // --- Slight preference for bins with large residual when item is small ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect packing strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (items >= 1,
    // but small residuals waste capacity). Use a non-linear "uselessness" curve.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // residuals below ~15 are hard to fill; penalize superlinearly
        if dead < 15.0 {
            score += (15.0 - dead) * (15.0 - dead) * 0.35;
        }
    } else {
        // Perfect fill: huge reward
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent; if next item nearly fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize leftover more
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    if !is_new_bin {
        score -= 0.05 * mean_residual;
        score -= 0.3 * open_bins_count as f64;
    }

    // New-bin decision: opening a new bin is justified when the item fits
    // poorly everywhere (large post_residual in best existing bin is captured
    // by their scores), or late in the stream when consolidation matters less.
    if is_new_bin {
        // Base cost of a fresh bin.
        score += 20.0;
        // Early in the stream, new bins are cheaper (more future items to fill them).
        score -= 18.0 * (1.0 - progress);
        // If many open bins exist and mean residual is large, discourage new bins.
        score += 0.04 * mean_residual * open_bins_count as f64;
        // If the next item is small, a fresh bin can absorb it later: slight discount.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 5.0;
        }
    }

    // Time-horizon modulation: as the stream ends, favor squeezing items into
    // existing bins (minimize total bins), penalize new-bin usage more.
    if is_new_bin {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post residual with stream progress:
    // late in the stream, prefer very tight fits even more strongly.
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks mid-range residual
    score += 30.0 * poly * (1.0 + progress);

    // Penalize large dead space super-linearly as stream progresses
    score += 20.0 * x * x * progress;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by how much it misses
        score += 5.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-mean residual (consolidate fullness)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Slight preference for fewer open bins when many are open
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by large divisors are "usable"
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for &d in &[50u32, 25, 20, 10, 5] {
        if pr >= d && pr % d == 0 {
            harmonic_bonus += (d as f64) * 0.4;
            break;
        }
    }
    // Small dead-space penalties: residuals in awkward ranges
    if pr > 0 && pr < 10 {
        score += 25.0; // nearly unusable sliver
    } else if pr < 20 && pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: does post_residual fit next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                harmonic_bonus += 30.0; // perfect fit for next item
            } else if slack <= 5 {
                harmonic_bonus += 15.0;
            } else {
                harmonic_bonus += (slack as f64).recip() * 20.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            harmonic_bonus -= ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        harmonic_bonus += 20.0;
    }

    // Fraction-of-capacity thresholds on residual
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    if frac > 0.9 {
        harmonic_bonus += 5.0; // nearly-empty bin, prefer filling it
    }

    // Integer-division tier on post_residual (buckets of 17)
    let tier = pr / 17;
    harmonic_bonus += tier as f64 * 1.5;

    // Prefer bins below mean residual when stream is late (consolidation)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (bin_residual as f64) < mean_residual {
        harmonic_bonus += 4.0 * progress;
    } else {
        harmonic_bonus -= 2.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = 100.0 - mean_residual;
        let pressure = (open_bins_count as f64) * 0.5 + avg_tightness * 0.3;
        score += 30.0 - pressure.min(28.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    score -= harmonic_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Strict dead-space avoidance: residuals that are too small for any plausible
    // future item (items >= 1, but practically >= ~10) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 18.0; // near-dead space
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // Penalize if next item no longer fits after this placement but would fit now.
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size && bin_residual >= item_size + next_item_size {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> favor filling existing ones,
    // making a new empty bin less attractive.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate: empty bin has residual == capacity. Penalize it unless
    // the current bin would leave a bad fit.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Progress-aware: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Reward tight fills: the more space consumed now, the better.
    score -= (cap - post) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0 + 10.0 * (1.0 - progress);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead chaining: if the next item fits into the leftover space,
    // this placement is doubly valuable; otherwise penalize dead space
    // proportional to how much the next item overshoots the residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (1.0 - post / cap);
        } else {
            score += (nxt - post).min(40.0) * 0.45;
        }
    }

    // New-bin candidate logic: prefer opening a fresh bin only when no
    // existing bin offers a decent fit, or when the item is huge and the
    // fresh bin would stay nearly full afterwards.
    if is_new_bin {
        if fitting_bins_count > 1 {
            score += 22.0 + 8.0 * (1.0 - progress);
        }
        if post_residual <= 10 {
            score -= 14.0; // huge item: fresh bin is the natural home
        }
        // Slight preference for new bins when existing bins are fragmented.
        score -= (mean_residual - post).max(0.0) * 0.15;
    }

    // Global pressure: when many bins are open, consolidate; when few are
    // open, spreading is cheaper.
    score += open_bins_count as f64 * 0.4;
    score += (mean_residual - post) * 0.1;

    // Early stream: slightly favor consolidation to build dense bins;
    // late stream: favor any fit that avoids a new bin.
    score += 4.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), with mild quadratic shaping
    let mut score = x * (1.0 + 0.8 * x);

    // Smooth non-linear interaction: as stream progresses, penalize large residuals more
    let progress_coupling = progress * x * x * cap * 0.3;
    score += progress_coupling;

    // Reward using an existing bin vs opening a new one, more strongly late in the stream
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 12.0 + 15.0 * progress;
    } else {
        score -= 3.0 + 6.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward; if next item
    // would fit but post_residual is awkwardly small, slight penalty
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 4.0 * fit_quality * (1.0 - progress);
        } else {
            score += 2.0 * (1.0 - progress);
        }
    }

    // Smooth coupling with mean residual: avoid bins that deviate strongly from fleet mean
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev;

    // Mild preference for keeping few open bins early on
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in a "usable"
    // residue class (multiples of small item sizes) are more valuable to keep.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        // Residual divisible by common small sizes is reusable -> reward.
        for d in [5u32, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += (d as f64) * 0.6;
            }
        }
        // Exact-fit post residual (0) handled below; here pr>0.
        score -= harmonic_bonus;
        // Very small dead space (< 10, minimum item size) is worthless -> penalize.
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64;
        }
    } else {
        // Perfect fill: heavily reward.
        score -= 60.0;
    }

    // Capacity-fraction coupling: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac * fill_frac;

    // Integer-division threshold on post_residual vs next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Next item also fits here: strong reward, scaled by tightness.
            score -= 20.0 + 10.0 * (next_item_size as f64 / (pr as f64 + 1.0));
        } else if pr > 0 {
            // Next item won't fit: residual likely wasted; penalize proportionally.
            score += 8.0 * (1.0 - pr as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit, ignore future concerns.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when nothing fits well; make the
    // empty bin unattractive unless the current bin's post-residual is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        if pr >= 30 {
            score -= 10.0; // a fresh bin with big residual headroom is okay
        }
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Spread pressure: when many bins are open, prefer reusing fuller ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    let gap = post_residual;
    if gap > 0 {
        // Unusable small gap (nothing but tiny items could fit): strong penalty.
        if gap < 10 {
            score += 60.0;
        } else if gap <= 15 {
            score += 25.0;
        } else if gap < 30 {
            score += 8.0;
        }
        // Perfect fit bonus.
        if gap == 0 {
            score -= 100.0;
        }
    } else {
        score -= 100.0;
    }

    // Reward residual sizes that are likely reusable by future items
    // (aligned with common item sizes in the 10..80 range).
    if gap >= 10 && gap <= 80 {
        score -= 10.0;
        // Extra reward for "round" residuals that match typical item sizes.
        if gap % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last chance: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — favor using it (its space is scarce).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.4;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits but not quite (wasted setup).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score += 12.0;
    }

    // New-bin candidate handling: empty bin starts with high residual;
    // make it attractive only when the item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins happily; small items should use existing space.
        score -= load * 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if item_size <= 20 && fitting_bins_count > 1 {
            score += 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match
        } else {
            score += diff * 0.4; // penalty grows with mismatch
            // penalize if next item cannot fit in post_residual
            if (next_item_size as u32) > post_residual {
                score += 25.0;
            }
        }
    }

    // Penalize very small dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals across bins are tight
    // or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap < 0.0 {
            score -= 15.0; // no open bin fits well -> prefer fresh bin
        } else {
            score += 10.0 + mean_fit_gap * 0.2; // discourage opening when fits exist
        }
        if open_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 15.0;
        }
    } else {
        // Favor bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Penalize dead space: residuals that no plausible item (1..100) can fill well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Last-chance bonus: only one open bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - fit_gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize proportional waste.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so new bins are used only when residuals are fragmented.
        score += 25.0 - 20.0 * crowding - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 18.0; // no good alternative, allow new bin more readily
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (tighter bins).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Dynamic time horizon: early in the stream, be more conservative with open bins
    // (keep flexibility); late in the stream, fill aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = poly * cap;

    // Penalize small dead space more aggressively as stream progresses (wasted capacity)
    let dead_penalty = (norm_pr * (1.0 - norm_pr)) * (1.0 + 2.0 * progress);
    score += dead_penalty * 20.0;

    // Reward tight fits (small post_residual) with lookahead compatibility
    if next_item_size > 0 {
        let fits_next = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
        score -= fits_next * (next_item_size as f64 / cap) * 30.0 * (0.5 + progress);
        // penalize residual that can fit neither current future item
        let too_small = if pr < next_item_size as f64 && pr > 0.0 { 1.0 } else { 0.0 };
        score += too_small * pr * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + progress);
    }

    // Slight preference for consolidating into bins when many bins are open
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * mean_residual * 0.05;

    // Prefer bins with less residual overall (tighter packing)
    score += (bin_residual as f64 - pr as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: which "slot band" does the leftover fall into?
    // Bands: 0 (perfect fit), 1..=10 (tight), 11..=25 (usable), 26..=50 (loose), >50 (half-empty)
    let post = post_residual as f64;
    let band = if post_residual == 0 { 0.0 }
        else if post_residual <= 10 { 1.0 }
        else if post_residual <= 25 { 2.0 }
        else if post_residual <= 50 { 3.0 }
        else { 4.0 };

    // Modulo-arithmetic coupling: leftover divisible by 10 pairs well with
    // item sizes drawn from a coarse grid (common in practice).
    let post_mod = (post_residual % 10) as f64;
    let next_mod = (next_item_size % 10) as f64;
    let mod_align = (10.0 - (post_mod - next_mod).abs()).min((post_mod - next_mod).abs());

    let mut score = post * post * 0.01; // quadratic dead-space penalty

    // Reward landing in tighter bands (lower band index = better fit class).
    score += band * band * 6.0;

    // Lookahead: does next item fit into post_residual? Strong reward if yes.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.15; // prefer just-fitting lookahead
        } else {
            score += 12.0; // next item won't chain here
        }
        // Harmonic divisibility: post_residual divisible by next_item_size class
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    }

    // Modulo alignment bonus between leftover and next item's coarse class.
    score -= mod_align * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are collectively full (mean residual low) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // New bin is penalized when existing bins are roomy; rewarded late when bins are tight.
        score = cap * 0.5 + mean_fill * 20.0 - progress * 15.0;
        if open_bins_count == 0 { score = -100.0; }
    }

    // Mild penalty for proliferating bins when a decent fit exists.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // even the smallest plausible item are pure waste.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0; // heavy dead-space penalty
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is always excellent
    }

    // Reward tight fits (small but still usable residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: favor bins whose post_residual still fits the next item,
    // penalize bins that would strand the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open,
        // so a fresh bin only wins when existing fits are terrible.
        score += 40.0 + pressure * 3.0;
        // But if it would leave a large, highly usable residual, soften slightly.
        if post_residual >= 50 {
            score -= 10.0;
        }
    } else {
        score -= pressure.min(10.0);
    }

    // Mild bonus for bins already below average fill (balance residuals
    // so future medium items still fit somewhere).
    if (post_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow into this bin: penalize proportionally
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Penalize leaving residual far below mean residual (wasted large bin on small gap)
    let gap_vs_mean = mean_residual - post_residual as f64;
    if gap_vs_mean > 0.0 {
        score += 0.3 * gap_vs_mean;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        if fitting_bins_count == 1 {
            penalty -= 55.0; // no good alternative: new bin is fine
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 20.0 * progress;
        score += penalty;
    }

    // Mild preference for tighter fits overall
    score += 0.1 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    score -= 0.6 * (1.0 - (post_residual as f64) / cap);

    // Penalize leaving dead space that no small item can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize proportionally to the leftover waste.
            score += 0.3 * (post_residual as f64);
        }
    } else {
        // Last item: waste is permanent, minimize post residual aggressively.
        score += 0.5 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a fresh bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by how bad existing fits are.
        score = post_residual as f64 + 30.0
            - 0.2 * (mean_residual - post_residual as f64).max(0.0);
        // Early in the stream, be more willing to open new bins (flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins already fit the item, discourage opening another.
        if fitting_bins_count > 2 {
            score += 20.0 * (fitting_bins_count as f64 - 2.0);
        }
    } else {
        // Prefer fuller bins among open bins: penalize bins with large residual.
        score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);
        // Slight preference to close out nearly-full bins.
        if bin_residual <= item_size + 5 {
            score -= 6.0;
        }
        // When many bins are open, consolidate into emptier ones to reduce bin count pressure.
        if open_bins_count > 8 {
            score -= 0.05 * (open_bins_count as f64 - 8.0);
        }
    }

    // Time-horizon coupling: late in the stream, waste is less recoverable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling: post_residual normalized, shaped by progress
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    let coupling = x * x * (1.0 - p) + x * (1.0 - x) * p;
    score += 12.0 * coupling;

    // Penalize dead space more as the stream advances (fewer chances to fill)
    let dead = (x - 0.2).max(0.0);
    score += 25.0 * dead * dead * (0.5 + p);

    // Reward tight fits (small post residual)
    score -= 18.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + p);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr as f64 {
            score -= 10.0 * (ni / cap);
        } else {
            score += 6.0 * (1.0 - p);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 1.5 * open_bins_count as f64 * (1.0 - p) * x;

    // New-bin candidate: only attractive when it beats poor fits late in stream
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - p) + 8.0;
    }

    // Mean residual deviation: prefer bins whose residual differs from mean (diversity of gaps)
    score += 3.0 * ((pr as f64 - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual), with quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Residuals that are small or multiples of 10 remain more "usable" for
    // typical item sizes, so reward them; odd/prime-ish residues are dead space.
    let pr = post_residual;
    let class_bonus: f64 = match pr % 10 {
        0 => 6.0,
        1..=9 => {
            if pr <= 10 { 4.0 } else if pr <= 20 { 1.0 } else { -2.0 }
        }
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: a bin whose residual after placement is
    // divisible by 5 can host a wider set of future items -> reward.
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this is a perfect two-item chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 - slack * 0.15;
        } else {
            // Next item won't fit here; penalize more if this bin is the
            // only fitting one (last-chance bin should still be used).
            if fitting_bins_count <= 1 {
                score += 5.0;
            }
            // If next item is large, prefer to keep large residual bins free.
            if next_item_size >= 50 && pr >= next_item_size / 2 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin offers a decent fit. Penalize it increasingly
    // with the number of open bins and mean residual availability.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.1 + progress * 5.0;
        // Exception: huge items relative to capacity deserve fresh bins.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 25.0;
        }
    }

    // Mild preference for filling bins below mean residual (balance avoidance
    // of many half-empty bins): bins with residual below mean are "dying",
    // use them first.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.2;
    }

    // Progress-aware dead-space penalty: late in the stream, wasted space
    // matters more since fewer chances remain to recover it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; penalize small-but-nonzero gaps super-linearly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.8; // dead-space quadratic penalty
    }

    // Reward tight fits: the closer item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Lookahead (k=2): if the next item fits into the post residual, reward;
    // if it almost fits (gap small), penalize this placement choice.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 6.0; // chain placement possible
        } else if pr > 0.0 && ni - pr <= 8.0 {
            score += (ni - pr) * 1.5; // near-miss dead space risk
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.35;

    // New-bin candidate handling: an empty bin should only win when existing
    // bins have poor residuals. Penalize the empty-bin candidate, scaled by
    // how much usable residual already exists across open bins.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        score += 18.0 + mean_r * 0.25;
        // Early in the stream, opening bins is cheaper (fewer bins exist).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for bins below mean residual (balance avoidance of
    // many half-empty bins): favor placing into below-average bins.
    let res = bin_residual as f64;
    if mean_residual > 0.0 && res > mean_residual {
        score += (res - mean_residual) * 0.05;
    } else {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that no typical item can use.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0; // unusable sliver
    } else if post_residual > 0 && post_residual < item_size.min(20) {
        score += 6.0; // hard-to-fill gap
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (10.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here; slight penalty for wasteful sequencing
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (bin_residual - item_size) as f64 * 0.2;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and
    // mean residual is large; reward it late in the stream or when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + open_bins_count as f64 * 1.5 - fragmentation * 0.3 - progress * 6.0;
    } else {
        // Mild preference for bins whose residual deviates from the mean (diversify sizes)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.05;
    }

    // Dynamic time horizon: early in the stream, keep bins flexible (larger residuals ok);
    // late in the stream, prioritize filling bins as fully as possible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) dead-space penalty.
    let mut score = r + 40.0 * rn * rn;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap (favor tight fits less aggressively);
    // late in the stream, dead space becomes costly.
    let progress_coupling = r * (0.5 + 1.5 * progress * progress);
    score += 0.8 * progress_coupling;

    // Interaction with mean residual: penalize bins far from the fleet mean
    // (keeps residual distribution balanced), smoothly weighted.
    let dev = (r - mean_residual) / cap;
    score += 25.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    // (avoids opening a new bin), scaled smoothly by residual tightness.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - rn);
    }

    // Lookahead: reward bins whose post-residual can still fit the next item
    // (smooth quadratic in slack), penalize otherwise.
    if next_item_size > 0 {
        let slack = r - next_item_size as f64;
        if slack >= 0.0 {
            score -= 12.0 * (slack / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (-slack / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for many open bins (encourage consolidation), smooth in progress.
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Perfect fit reward, smoothly amplified late in stream.
    if post_residual == 0 {
        score -= 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues modulo 10 and 20.
    let residue10 = post_residual % 10;
    let residue20 = post_residual % 20;

    // Penalize "dead" leftover space that is unlikely to be refilled:
    // small nonzero residues (1..9) are hard to fill with items >= 1.
    if post_residual > 0 {
        if residue10 == 0 {
            score -= 6.0; // perfectly aligned leftover
        } else if residue20 < 10 {
            score += 3.0 + residue20 as f64 * 0.4; // awkward odd class
        } else {
            score += 1.0; // half-aligned class
        }
    }

    // Exact-fill bonus: closing a bin perfectly is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0; // small leftover, item sizes 1..100 can still fit
    }

    // Lookahead coupling: if the next item fits the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward good chains, penalize leaving tiny unusable slacks
            if slack <= 10 {
                score -= 12.0 - slack * 0.5;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: leftover becomes dead space; penalize
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: prefer tightest fill anywhere.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which wastes this bin's residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + bin_residual as f64 * 0.1;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - frac * 60.0;
        // discourage opening new bins when existing bins fit well
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 15.0 {
            score += 20.0;
        }
        // early in stream, opening bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Mild preference to spread load: bins with residual far above mean are good targets.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Harmonic threshold: integer division classes of post_residual by 25.
    score += match post_residual / 25 {
        0 => -4.0, // residual < 25: nearly full bin, great
        1 => 0.0,
        2 => 2.0,
        _ => 4.0,  // large residual left: wasteful placement
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual but usable).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating a gap that is smaller than the smallest plausible item
    // while not being zero (true dead space).
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // next item cannot use this gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (consolidating space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect or near-perfect chain: post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 12.0; // exact 2-step chain completion
        }
        // Penalize residual that is too small for any future item but nonzero (dead space)
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
        // Reward leaving room for next item to fit exactly after
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 4.0; // next item won't fit here -> likely dead space
        }
    } else {
        // Last item: minimize waste
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference for tighter bins overall
    score += 0.15 * (bin_residual as f64 - post_residual as f64) - 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual gets a strong bonus.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate handling: neutral-ish baseline, discouraged unless
    // the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Opening fresh is attractive for large items early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 50 && progress < 0.6 {
            score -= 10.0;
        }
    }

    // Global state coupling: many open bins -> prefer consolidating into
    // bins with below-average residual (fill the emptiest bins first).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Time horizon: late in the stream, be conservative, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Mild preference for filling bins with larger residual proportionally.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: reward tight fits quadratically (small post_residual strongly preferred).
    let mut score = norm_pr * norm_pr * 100.0 + norm_pr * 40.0;

    // Smooth stream-progress coupling: later in the stream, dead space hurts more.
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += norm_pr * norm_pr * (1.0 + progress_coupling) * 60.0;

    // Usability term: residual that can still fit typical future items is valuable.
    // Compare post_residual to mean residual of open bins (smooth, non-linear).
    let mean_norm = mean_residual / cap;
    let usability = (norm_pr - mean_norm).abs();
    score += usability * usability * 50.0;

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_bonus = (-gap / cap).exp();
        score -= fit_bonus * 35.0;
        // Penalize leaving a residual that barely misses the next item (dead space).
        let miss = ((pr - nxt) / cap).max(0.0);
        score += miss * miss * 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smooth in fitting_bins_count).
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= last_chance * 25.0 * (1.0 + norm_item);

    // New-bin candidate handling: an empty bin has norm_pr == 1.0; penalize it
    // smoothly unless the item is large relative to capacity.
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (60.0 - 40.0 * norm_item * norm_item);

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    // (min item size is 10 in classic streams; small residuals are waste).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space penalty
    }
    // Exact-fit class: post_residual 0 is perfect
    if pr == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // the classic item granularity, making future fills easier.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Integer-division thresholds on post_residual (capacity fractions)
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 8.0; // bin still roomy, keep it attractive
    } else if frac < 0.1 {
        score += 6.0; // nearly full, low utility left
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: slight penalty proportional to waste risk
            score += (next_item_size - pr).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should win only when no open bin fits well. Penalize the fresh bin
    // mildly so good fits in existing bins win, but not so much that a
    // terrible placement (large dead space) is chosen instead.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from the mean (consolidation effect)
    score -= 0.3 * (mean_residual - post_residual as f64).abs();

    // Tie-breaker: mildly prefer already-open bins when many are open
    if bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: gaps that no item (min size 1..100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // marginal gap
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that the lookahead item could exactly fill
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_diff = post_residual - next_item_size;
        if gap_diff == 0 {
            score -= 20.0;
        } else if gap_diff < 10 {
            score -= 6.0;
        }
    }
    // Penalize if post_residual is just below the next item (dead space for lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across too many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 + progress) * 0.5;

    // Prefer bins below mean residual (fill emptier bins less aggressively)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.5;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still hold next item: reward proportional closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 - slack.min(20.0)) * 0.8;
    } else if next_item_size > 0 {
        // Next item won't fit in leftover: penalize wasted space relative to next item.
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(30.0) * 0.6;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer bins with residual below mean (tight bins get filled first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Penalize leaving very small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / 100.0).max(0.0)
        } else {
            0.3
        };
        score += 55.0 + 15.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness reward: fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * fill * fill;

    // Penalize large dead space that can't host typical items
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // tiny unusable sliver is fine
    } else if post_residual >= 10 && post_residual < 40 {
        score += 10.0; // moderately wasteful zone
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 80.0 / (1.0 + slack_after_next as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 25.0; // next item won't fit here, mild penalty
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * (post_residual as f64) * 0.15;

    // Time horizon: late in the stream, be more conservative (favor tight fits)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += t * 30.0 * (post_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins below mean residual (tighter than average)
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it unattractive unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 120.0 - 80.0 * fragmentation - 40.0 * t;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear
    // convex penalty so very small residuals are strongly favored.
    let pr = post_residual as f64;
    let mut score = pr + 12.0 * (pr / cap).powi(2);

    // Smooth coupling with stream progress: later in the stream, dead space
    // matters more (fewer chances to fill it), so weight grows non-linearly.
    score *= 1.0 + 0.9 * progress * (1.0 + progress);

    // Reward filling a bin almost completely, smoothly via interaction term.
    let fill = 1.0 - pr / cap;
    score -= 6.0 * fill * fill * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily (smooth in fitting count).
    let fit_factor = 1.0 / fitting_bins_count as f64;
    score -= 15.0 * fit_factor * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean (keeps a portfolio
    // of diverse residuals so future items find good homes).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward this placement (smooth quadratic affinity).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / cap).powi(3).max(0.0);
    }

    // Mild penalty for opening a brand-new bin when many bins are open,
    // scaled by progress (late new bins are costlier).
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 3.0 + 6.0 * progress + 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes (2,4,5,10) are more reusable, odd/large primes less so.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr == 0 {
        reusability += 30.0; // perfect fit is ideal
    } else {
        if pr % 10 == 0 { reusability += 8.0; }
        if pr % 5 == 0 { reusability += 4.0; }
        if pr % 4 == 0 { reusability += 3.0; }
        if pr % 2 == 0 { reusability += 2.0; }
        if pr < 10 { reusability -= 12.0; } // dead space below min item size
        // integer-division threshold bands on the leftover
        let band = pr / 10; // 0..10 harmonic band
        reusability += band as f64 * 1.5;
    }
    score -= reusability;

    // Lookahead coupling: does the next item fit into the post-residual class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact or near-exact match with next item is very valuable
            if pr == next_item_size { score -= 25.0; }
            else if pr - next_item_size <= 5 { score -= 15.0; }
            else { score -= 6.0; }
            // harmonic compatibility: same residue class
            if pr % 10 == next_item_size % 10 { score -= 4.0; }
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15;
        }
    } else {
        // last item: just minimize waste
        score += (pr as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer existing bins with decent fits
        score += 35.0;
        // but if open bins are crowded / residuals are low, opening is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open
        } else if crowding < 0.25 || open_bins_count > 40 {
            score -= 30.0 * (1.0 - crowding) + 10.0 * progress;
        }
        // big items prefer fresh bins to avoid fragmentation
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // slight preference for tighter existing bins (best-fit bias)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // mean-residual coupling: avoid dumping items into bins whose residual
    // deviates wildly from the fleet mean (keeps future options balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize residual gaps that are
    // too small to be usable by typical future items (unusable small gaps).
    if post_residual > 0 {
        // A gap smaller than the minimum item size is pure dead space.
        if post_residual < 10 {
            score += 60.0;
        } else {
            // Quadratic penalty ramping as the gap shrinks toward unusability.
            let gap = post_residual as f64;
            score += (10.0_f64 - gap * 0.1).max(0.0).powi(2) * 2.0;
        }
    }

    // Reward a perfect or near-perfect fill strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open,
    // encouraging consolidation; scale with stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Penalize deviating from the mean residual (favor bins near the pack frontier).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use this gap: penalize leaving a small gap.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins exist (then a fresh bin is a reasonable start).
    if bin_residual == bin_capacity {
        let base = 25.0 + open_bins_count as f64 * 2.0;
        score += base;
        if item_size >= 50 && open_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item chain fill
        } else if next_item_size <= post_residual {
            // next item fits: reward closeness of the resulting double-fill
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize dead space left behind
            score += 0.5 * post_residual as f64;
            // extra penalty if post_residual is too small for typical items
            if post_residual < 10 {
                score += 25.0;
            }
        }
    } else {
        // last item: minimize leftover
        score += 0.3 * post_residual as f64;
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin early in the stream when other bins fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new-bin candidate: only attractive if post_residual is huge or item is big
        score += 20.0;
        if item_size >= 70 {
            score -= 15.0;
        }
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // General waste penalty: small residuals are hard to reuse
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild stream-progression pressure: later in stream, favor tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize large dead space nonlinearly.
    let cap = bin_capacity as f64;
    let dead = post_residual as f64 / cap;
    score += dead * dead * 60.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when next item fits snugly too.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - chain_waste / cap).max(0.0);
    } else if next_item_size > 0 {
        // Penalize stranding the next item's size range.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins fit the item, prefer bins with less residual (best-fit pressure).
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Time horizon: early in stream, encourage opening bins that leave flexible space;
    // late in stream, prioritize consolidation (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless it's early and mean residual is low.
        let new_bin_penalty = 18.0 + 30.0 * progress + 0.05 * open_bins_count as f64;
        score += new_bin_penalty;
        if progress < 0.25 && mean_residual < 20.0 {
            score -= 10.0; // early stream, existing bins crowded -> new bin is fine
        }
    } else {
        // Open bins get a consolidation bonus late in the stream.
        score -= 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balance residual distribution).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr_n = pr / cap;

    // Smooth base: prefer small post-residual, with quadratic coupling to progress
    let mut score = pr_n * (1.0 + 0.6 * progress) + 0.35 * pr_n * pr_n * (1.0 + progress);

    // Penalty for large dead space that nothing else can use (smooth cubic term)
    score += 0.25 * pr_n * pr_n * pr_n;

    // Last-chance bin: reward using it smoothly
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.8 * progress;
    }

    // New-bin candidate: penalize smoothly unless current residual is tiny
    if bin_residual == bin_capacity {
        let tight = ((bin_residual as f64) - pr) / cap; // = item fraction
        score += 1.2 - 0.9 * (1.0 - pr_n) * (1.0 - pr_n) * (1.0 + tight);
    }

    // Lookahead: reward leaving room for next item smoothly
    if next_item_size > 0 {
        let nxt = (next_item_size as f64) / cap;
        let fit = ((pr_n - nxt).max(0.0)) / (1.0 + pr_n);
        score -= 0.9 * fit * (1.0 + 0.5 * progress);
        // penalize if post-residual barely misses next item (dead space)
        let miss = ((nxt - pr_n).max(0.0)) * ((nxt - pr_n).max(0.0));
        score += 1.1 * miss;
    }

    // Slight preference for filling bins with low mean residual (compactness)
    score += 0.15 * ((pr_n - mean_residual / cap) * (pr_n - mean_residual / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by its "harmonic bucket"
    // (integer division into quarters of capacity). Small post_residual = tight fit.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..4

    // Reward tight fits (post_residual in lowest class) strongly.
    match post_class {
        0 => score -= 30.0,
        1 => score -= 10.0,
        2 => score += 5.0,
        3 => score += 12.0,
        _ => {}
    }

    // Exact fit: perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space penalty: unusable residue (smaller than any plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: prefer bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.05;
        } else {
            score += 6.0;
        }
        // Harmonic pairing: post_residual exactly complements next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // More open bins -> stronger reluctance to open another.
        score += open_bins_count as f64 * 3.0;
        // Late in stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Prefer bins with lower residual (best-fit flavor) scaled by mean residual.
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: post_residual that no item can use is waste.
    // Estimate the smallest plausible item size as min(next_item_size, item_size), floor at 1.
    let min_future = if next_item_size > 0 {
        next_item_size.min(item_size).max(1)
    } else {
        item_size.max(1)
    };

    if post_residual > 0 && (post_residual as u64) < (min_future as u64) {
        // Unusable gap: penalize heavily, scaled by how "trapped" the space is.
        score += 120.0 + 40.0 * (1.0 - post_residual as f64 / min_future as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap can host the lookahead item: reward (chained fit).
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 80.0;
        } else if (slack_after_next as u64) < (min_future as u64) {
            score += 60.0; // would create another dead gap
        } else {
            score -= 10.0;
        }
    }

    // Tight packing preference: relative fill of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 50.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += pressure * 2.0;

    // Prefer bins below mean residual (denser bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: default neutral-to-slightly-high; only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item also fits alongside the one after (soft lookahead)
        else if post_residual >= next_item_size {
            score -= 12.0;
        }
        // Next item cannot use the leftover: dead-space penalty scaled by gap
        else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer;
    // reward using them when post_residual stays near mean (balanced packing)
    let pr = post_residual as f64;
    let mean_gap = pr - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post_residual would be tiny/dead space)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if pr < 10.0 {
            score += 15.0; // but avoid near-unusable slivers
        }
    }

    // Penalize new-bin candidate mildly so open bins are preferred when decent;
    // allow opening a new bin when post_residual would be huge (poor fit elsewhere)
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (pr / bin_capacity as f64);

    // Large items: favor bins where they leave moderate, reusable residual
    if item_size >= 50 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Penalize dead space: small post_residual that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Penalize leaving a residual that just barely fails the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 0.6 * gap;
            }
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // encourage it late when open bins have fragmented residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 - 25.0 * progress;
        // If existing bins fit poorly (low tightness), allow opening a new bin.
        if tightness < 0.5 {
            score -= 18.0;
        }
    }

    // Penalize bins far from the mean residual (keeps residuals homogeneous,
    // enabling multi-item packing later).
    let deviation = ((bin_residual as f64) - mean_residual).abs();
    score += 0.15 * deviation;

    // Mild penalty for having many open bins: prefer consolidating.
    score += 0.3 * (open_bins_count as f64);

    // Slight preference for fuller bins as stream progresses.
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;
    // Non-linear polynomial coupling: post_residual weighted by stream progress
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 40.0 * coupling;
    // Reward tight fits, more so later in the stream
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(3);
    score -= 30.0 * tightness * (0.5 + progress);
    // Penalize dead space relative to mean residual
    let dead = (pr - mean_residual) / cap;
    score += 25.0 * dead * dead;
    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // Lookahead: favor bins that still fit the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - prn);
        } else {
            score += 8.0 * prn;
        }
    }
    // Slight penalty for opening a new bin early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 + prn);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // integer-division classes are penalized (dead space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class by post_residual / 10 buckets (integer division thresholds)
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,               // near-perfect fit, strongly reward
        1 => score -= 12.0,
        2 => score -= 5.0,
        3 => score += 3.0,                // moderate waste
        4 => score += 8.0,
        5 => score += 12.0,               // half-empty bin: bad unless reusable
        _ => score += 18.0,
    }

    // Modulo structure: leftover congruent to small classes (fits tiny items)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // round leftover, easier future packing
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // next item cannot use this leftover; penalize proportionally
            score += (next_item_size as f64 - pr).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Reward tightness relative to mean residual of open bins.
    score -= (mean_residual - pr) * 0.15;

    // Penalize opening a brand-new bin (residual == capacity) unless the item
    // is large relative to capacity or all existing bins fit poorly.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin is attractive for big items late in stream, or when many
        // bins are open and none fit well (fitting_bins_count small).
        let new_bin_bonus = 40.0
            - item_frac * 35.0
            - progress * 10.0
            - if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        score += new_bin_bonus.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Items 1..=100; gaps below ~10 (min item size) are pure waste,
        // gaps below 20 are hard to fill too.
        if dead < 10.0 {
            score += 500.0; // absolute dead space
        } else if dead < 20.0 {
            score += 150.0;
        } else if dead < 35.0 {
            score += 40.0;
        }
        // Smooth penalty proportional to unusability: gap that can't fit next item
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 30.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio;

    // Open bins pressure: discourage spreading into too many bins,
    // but allow new bin when current bins are crowded (mean residual low).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += 0.5 * pressure;

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are poor fits
    if bin_residual == bin_capacity {
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // opening a new bin wastes the mean residual of all open bins
        score += 60.0 + 0.3 * avg_open_residual;
        // but if this is a huge item with few fitting bins, opening is fine
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Mean residual coupling: prefer bins close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0 + 0.5 * post_residual as f64;
    }
    // Near match: next item fits with small waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.6;
    }
    // Next item cannot follow: penalize proportionally to dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Tight fits are good: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 / (1.0 + tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if current fit is very poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 60.0
            || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= 25.0;
        } else {
            score += 30.0;
        }
    }

    // Relative to mean residual: bins with less residual than average are more valuable to fill
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Early stream: be slightly conservative, prefer filling existing bins later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && post_residual >= next_item_size {
            1.0
        } else if post_residual >= 10 {
            0.5
        } else {
            0.0
        };
        score -= 6.0 * usable;
        if usable == 0.0 {
            score += 8.0; // dead-space penalty
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.1 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when few bins fit or residual is near capacity.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        let spread = (mean_residual - post_residual as f64).abs();
        score += 15.0 * (1.0 - pressure);
        score += 4.0 * spread / (bin_capacity as f64);
        score -= 10.0 * (1.0 - horizon) * (open_bins_count as f64 / 20.0).min(1.0);
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.min(bin_capacity as u32) {
            score += 6.0; // new bin won't help the next item much
        }
    }

    // Mildly prefer filling bins with larger residuals when many bins are open.
    score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Time-based nudge: early stream, consolidate more aggressively.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * horizon * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with a non-linear penalty
    // that grows super-linearly for large dead space.
    let mut score = norm_pr + 0.8 * norm_pr * norm_pr + 0.6 * norm_pr * norm_pr * norm_pr;

    // Smooth polynomial coupling with stream progress: early on, tolerate
    // slack (favor keeping bins flexible); later, become increasingly
    // intolerant of dead space.
    let progress_coupling = 0.5 * norm_pr * (progress * progress - 2.0 * progress + 1.0)
        - 0.35 * norm_pr * progress * (1.0 - progress);
    score += progress_coupling;

    // Interaction of item size with residual: reward large items filling
    // large holes smoothly via (item/cap)*(1 - norm_pr).
    let item_frac = item_size as f64 / cap;
    score -= 0.4 * item_frac * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward
    // using it (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Lookahead: if the next item fits into the post residual, reward this
    // placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let next_frac = next_item_size as f64 / cap;
        score -= 0.5 * next_frac * (1.0 - norm_pr);
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize opening a fresh bin unless residuals of
    // existing bins are already tight (smoothly modulated).
    if bin_residual == bin_capacity {
        score += 1.2 - 0.8 * (mean_residual / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // moduli are more "usable" by future items (typical sizes cluster).
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 6.0; }
        else if pr % 5 == 0 { class_bonus += 3.0; }
        if pr % 20 == 0 { class_bonus += 3.0; }
        if pr % 25 == 0 { class_bonus += 2.0; }
        score -= class_bonus;
    } else {
        // Perfect fill is ideal.
        score -= 50.0;
    }

    // Dead-space penalty: tiny leftovers that few realistic items can use.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt as u32) == pr {
            score -= 30.0;
        } else if (next_item_size as u32) < pr {
            let slack = (pr as f64 - nxt) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 5.0;
        }
    }

    // Fractional capacity thresholds on post_residual.
    let frac = pr as f64 / cap;
    if frac > 0.4 {
        score -= 4.0; // large leftover keeps bin flexible
    } else if frac < 0.1 && pr > 0 {
        score += 3.0; // nearly-full bin, low flexibility
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist
    // and the item fits reasonably elsewhere; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Prefer tighter bins: deviation from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(item_size)) {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open,
    // but allow opening a new bin when residuals are fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Last chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would not fit in post residual but would fit a fresh bin,
    // penalize slightly when this bin is a poor fit anyway.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: if this bin is far below mean residual,
    // it's already "wasted"; prefer to pack into it rather than tighter bins.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.min(20.0) * 0.5;
    }

    // New-bin candidate: empty bin should only win when open bins would
    // create dead space or are too fragmented.
    if bin_residual == bin_capacity {
        // Neutral baseline: slight penalty so existing good fits win,
        // but not so high that a bad fit in an open bin is preferred.
        score += 15.0;
        if post_residual == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual closely matches next item,
    // penalize when next item cannot fit here (forcing another bin).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to leftover dead space.
            score += 0.5 * post_residual as f64;
            // But if this residual is unusable anyway (too small for anything), soften.
            if post_residual < 10 {
                score -= 30.0;
            }
        }
    } else {
        // Last item: pure waste minimization.
        score -= 50.0;
    }

    // Compare against mean residual: placing in a bin with residual far above
    // mean wastes the "big" bins; prefer bins with residual near item_size.
    let diff = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or the stream is progressing (fewer chances to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 100.0 * progress;
        // Exception: if item is large and only one fitting bin, allow new bin less reluctantly.
        if fitting_bins_count == 1 {
            score -= 90.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.2 * (post_residual as f64 - (bin_capacity as f64 - item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space: post_residual too small for the smallest future item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fragmentation pressure: high mean residual spread relative to item size.
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        let new_bin_penalty = 20.0
            + 15.0 * (1.0 - progress)
            + (open_bins_count as f64).sqrt() * 3.0
            - fragmentation * 0.5;
        score += new_bin_penalty;
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (bin_residual as f64) * 0.05;

    // Global state: many open bins -> prefer consolidation into existing bins.
    score += (open_bins_count as f64).ln() * 2.0;

    // Time horizon: late in stream, be greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is below mean residual, slightly favor it
    // (keeps one "big space" bin alive for large items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual penalized more as stream progresses
    score += 12.0 * (pr / cap).powi(2) * (0.5 + progress);

    // Reward tight fits (low post residual) with smooth quadratic bonus
    score -= 10.0 * (1.0 - pr / cap).powi(2);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 6.0 * (1.0 - pr / ns) * (0.5 + progress);
        } else {
            score -= 5.0 * (pr - ns) / cap;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins near mean residual
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-band classification
    let item_class = item_size / 25;              // 0..3
    let next_class = (next_item_size as u32) / 25; // 0..3 (0 if lookahead absent)

    // Perfect fit reward: post_residual in {0, 10, 20, 25, 50}
    let pr = post_residual;
    if pr == 0 { score -= 60.0; }
    else if pr % 10 == 0 { score -= 12.0; }
    else if pr % 25 == 0 { score -= 10.0; }

    // Dead-space penalty: small, odd-class residual that likely cannot host
    // typical items (residual < 10 is dead; residual in 1..10 unusable)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Pairing bonus: if the next item fits exactly into the post residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
        // harmonic match: next item's class complements post residual band
        if pr / 25 == next_class { score -= 6.0; }
        // exact pair
        if next_item_size == pr { score -= 45.0; }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot follow here; slight penalty proportional to mismatch
        score += ((next_item_size - pr) as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the
    // current bin's post residual would be very tight OR item is huge
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its "post residual" = capacity - item
        score -= 5.0;
        if item_class == 3 { score -= 10.0; } // big items like fresh bins
    } else if pr < 10 && item_class == 3 {
        // placing a huge item leaving dead space is bad; fresh bin might win
        score += 20.0;
    }

    // Congestion coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading
    if open_bins_count > 2 && mean_residual > (cap * 0.4) {
        score -= 6.0;
    }

    // Progress term: late in stream, be more conservative about dead space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr % 7) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1..15] is nearly unusable
    // (min item size is small but typical items are large), so penalize heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward tight fits: post_residual == 0 is a perfect pack.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward;
    // if post residual is just barely too small for next item, penalize.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            score -= 8.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else if next - post_residual as f64 <= 10.0 {
            score += 12.0; // near-miss dead space relative to lookahead
        }
    }

    // Open-bin pressure: many open bins -> favor using existing bins
    // (esp. when this is the only fitting bin, i.e. last chance).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);
    score -= pressure * 3.0;

    if fitting_bins_count == 1 {
        score -= 15.0; // last chance: strongly prefer packing here
    }

    // Mean residual context: if this bin's residual is far below mean,
    // it's already fragmented; packing it is good (finishes it off).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.1 * dev;
    }

    // New-bin candidate: empty bin has large residual; make it less attractive
    // unless it would give a very clean residual (e.g. item is huge fraction).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 15.0 * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 60.0 / (1.0 + diff as f64);
        // Bonus if placing current item leaves room for next item
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny dead space (unusable slivers) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward bins tighter than average (good fits), penalize loose ones
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for consolidating into fewer bins early in stream
    if bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (perfect fit gets a big discount).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space quadratically, scaled by bin capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste * waste * 10.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin;
    // if the next item would leave this bin's remainder useless, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Remaining space after this placement can't host next item:
            // penalize proportionally to how "stranded" the residual is.
            score += 4.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits) or the item is huge.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used sparingly.
        score += 20.0;
        // Relax penalty when open bins are mostly full / few fit.
        let fit_ratio = if open_bins_count > 0 {
            fitting_bins_count as f64 / open_bins_count as f64
        } else {
            1.0
        };
        score -= 30.0 * (1.0 - fit_ratio);
        // Large items justify a fresh bin more than small ones.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.05 * residual_gap;

    // Mild preference for more-open bins being consumed rather than proliferated.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize wasted post residual, with non-linear (quadratic/cubic) shaping.
    let mut score = post + 40.0 * norm_post * norm_post * cap;

    // Tight fits are rewarded quadratically: small post_residual relative to item.
    let tightness = 1.0 - norm_post / (norm_item + 1e-6);
    score -= 12.0 * tightness.max(0.0) * tightness.max(0.0);

    // Smooth interaction: as stream progresses, prefer filling existing bins more aggressively.
    score *= 1.0 - 0.35 * progress * (1.0 - norm_post);

    // Dead-space penalty: post residual too small to be useful later (smooth sigmoid-like).
    let dead = ((norm_post - 0.15) / 0.1).tanh();
    if norm_post > 0.0 {
        score += 8.0 * (1.0 - dead) * (1.0 - dead);
    }

    // Last-chance bin bonus: avoid opening new bins when few fit.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - ((post - nxt) / cap).tanh());
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing), smooth.
    let dev = (residual - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in a "good"
    // residue class (multiples of 10, i.e. post_residual % 10 == 0) are more
    // likely to absorb future items exactly. Reward low-waste classes.
    let waste_class = post_residual % 10;
    score += waste_class as f64 * 0.8;

    // Harmonic class of item_size relative to capacity: items that divide the
    // capacity evenly (e.g. 50, 25, 20, 10) create perfectly packed bins.
    if bin_capacity % item_size == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: reward bins whose post_residual can exactly host
    // the next item (perfect pair packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            // Fractional harmony: next item leaves a small harmonic remainder.
            let rem = post_residual - next_item_size;
            score += rem as f64 * 0.35;
            if rem % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Dead space penalty scaled by how far next item misses the fit.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (mean residual below item size + margin).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - item_size as f64;
        if fragmentation > 0.0 && fitting_bins_count > 0 {
            score += 25.0 + fragmentation * 0.5;
        } else {
            score -= 2.0;
        }
    } else {
        // Prefer tight fits: reward small post_residual relative to capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 5.0;

        // Penalize bins far above/below mean residual (harmonic imbalance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (post_residual.min(50) as f64 / 50.0);

    // Small post_residual sweet spots (<=10) are nearly perfect closures.
    if post_residual <= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps strongly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward exact fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still fit a typical item
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 8.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * 0.05 * (1.0 + progress);

    // Penalize leaving residual just below a likely usable threshold
    if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits perfectly or well after this placement -> strong bonus
        let leftover_after_next = post_residual - next_item_size;
        score -= 25.0 + 0.5 * (leftover_after_next as f64).min(30.0);
        if leftover_after_next == 0 {
            score -= 20.0; // perfect two-item fill
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item will not fit here -> penalize leaving awkward residual
        let gap = (next_item_size - post_residual) as f64;
        if post_residual > 0 {
            score += 0.6 * gap.min(40.0);
        }
    }

    // Prefer bins whose residual is small relative to mean (tight fit)
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (resid_f - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize large dead space that is too small for typical items
    if resid_f > 0.0 && resid_f < 10.0 {
        score -= 8.0; // near-perfect fill is great
    } else if resid_f > 50.0 {
        score += 4.0; // wasteful large residual
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            next_item_size as f64 > mean_residual
        } else {
            false
        };
        if poor_fit || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 20.0; // discourage opening new bins unnecessarily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large post_residual (dead space).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * frac * frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last chance: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving awkward small residuals.
            if post_residual < next_item_size && post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Global state coupling: with many open bins, prefer filling existing bins more.
    let open_f = open_bins_count as f64;
    score -= 0.35 * open_f * (1.0 - frac);

    // Deviation from mean residual: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be more conservative (favor new bins for large items);
    // late in stream, squeeze into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item_frac = item_size as f64 / bin_capacity as f64;
    score += (1.0 - t) * 4.0 * item_frac;
    score -= t * 3.0 * (1.0 - frac);

    // New-bin candidate: make it attractive only when item is large or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 15.0 * item_frac + 10.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * (1.0 - progress) * norm_pr * norm_pr);

    let mut score = poly * cap;

    // Penalize bins that deviate strongly from the mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score += 5.0 * diff * diff;
    } else {
        score -= 3.0;
    }

    // Mild pressure toward consolidation as bins accumulate
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class: how well post_residual decomposes into expected future item sizes
    // Items 1..100; common small sizes divide residual into nice chunks.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        0.0
    } else {
        let mut h = 0.0;
        for d in [50u32, 40, 34, 25, 33, 20, 17, 14, 10] {
            if pr % d == 0 && pr / d >= 1 {
                h += 6.0;
            }
        }
        // residual exactly in [1..=5] is nearly dead space
        if pr <= 5 { h -= 25.0; }
        // residual 6..=9 also poor
        else if pr <= 9 { h -= 10.0; }
        h
    };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let r2 = pr - next_item_size;
            if r2 <= 5 { score += 8.0; } else { score -= 4.0; }
        } else {
            // next item won't fit here; mild penalty for wasting large residual
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let base = 55.0;
        // large items (>= 60) are fine to start fresh
        let discount = if item_size >= 60 { 30.0 } else if item_size >= 40 { 10.0 } else { 0.0 };
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += base - discount - 15.0 * (1.0 - progress);
        // if many open bins with high mean residual, discourage new bin
        score += 0.3 * mean_residual;
    }

    // Tie-break: prefer tighter bins (smaller residual before placement)
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // Slight preference for bins whose residual is far from capacity (already used)
    score -= 0.05 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward" residuals: too small for typical items (10..=20) but not zero.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-exact fits (tight packing).
    if post_residual <= 5 {
        score -= 25.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would leave another dead gap, discourage.
    if next_item_size > 0 && post_residual > next_item_size {
        let nxt_waste = post_residual - next_item_size;
        if nxt_waste < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are open; allow spreading when few are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if this bin is much looser than average,
    // it is a good place to dump the item (burns slack efficiently).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin pressure is low; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let relief = if fitting_bins_count <= 1 { 45.0 } else { 0.0 };
        let late = if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 { 5.0 } else { 0.0 };
        score = base - relief - late + open_bins_count as f64 * 2.0;
        // A fresh bin is great if the item is large (keeps small bins for small items).
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Progression: tighten packing as the stream matures.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0) * (1.0 - diff / 40.0).max(0.0);
        // Perfect match for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a gap that no typical item (>=1) can use if too small.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // dead space penalty (small unusable sliver)
        }
    }

    // Compare post_residual against mean residual: prefer bins that reduce residual dispersion.
    score -= 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in the stream, be more willing to open new bins (keep residual flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral baseline with slight early-stream preference.
        score = score.min(0.0) * 0.0 + bin_capacity as f64 * (1.0 - 0.3 * progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer filling tighter bins generally (small residual after placement).
    score += 0.3 * (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + 1.5 * progress);

    // Penalize dead space that can't fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 {
        // Reward bins that can still host the next item too (chain potential).
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize bins far from the mean residual (avoid fragmenting the pool unevenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // When many bins are open, favor consolidation (packing into existing bins);
    // a new empty bin gets a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 4.0 + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        score -= 1.0;
    }

    // Slight preference for bins whose post-residual is a "nice" small leftover.
    if post_residual > 0 && post_residual <= 10 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex to prefer tight fits
    let mut score = pr * (1.0 + 0.35 * norm_pr);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more strongly
    let progress_coupling = 1.0 + 1.2 * progress * progress + 0.8 * progress * norm_pr;
    score *= progress_coupling;

    // Smooth penalty when post_residual becomes unusable relative to smallest plausible item (1..100)
    let dead_zone = (norm_pr - 0.01).max(0.0);
    score += 25.0 * (1.0 - (-dead_zone * 12.0).exp());

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + progress);
    }

    // Mild reward when bin residual deviates from mean (diversification of residual sizes)
    score -= 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = pr - nx;
        if fit_gap >= 0.0 {
            score -= 6.0 * (fit_gap / cap);
        } else {
            score += 4.0 * (-fit_gap / cap);
        }
    }

    // Slight penalty for proliferating bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // common small-item sizes (modulo arithmetic on capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonic": divisible by common item classes
    // (multiples of 10, 20, 25, 50 -> likely future perfect fits).
    if post_residual > 0 {
        let mut harmonic_bonus = 0.0;
        if post_residual % 10 == 0 { harmonic_bonus += 6.0; }
        if post_residual % 20 == 0 { harmonic_bonus += 5.0; }
        if post_residual % 25 == 0 { harmonic_bonus += 4.0; }
        if post_residual % 50 == 0 { harmonic_bonus += 6.0; }
        // Perfect fill is ideal.
        if post_residual == 0 { harmonic_bonus += 40.0; }
        score -= harmonic_bonus;
    } else {
        score -= 45.0; // exact fill
    }

    // Penalize awkward dead space: residual in (0,10) or narrow odd classes
    // that almost no item (min size 1..100 unknown, but small residuals waste).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    } else if post_residual > 0 && post_residual < 25 && post_residual % 5 != 0 {
        score += 8.0; // non-harmonic narrow band
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by tightness.
            let tight = (next_item_size as f64 / pr.max(1.0)).min(1.0);
            score -= 15.0 + 15.0 * tight;
        } else if next_item_size > bin_residual {
            // Next item can't fit here even before placement; this bin's
            // leftover is free real estate for later small items.
            score -= 4.0;
        } else {
            // Next item would need another bin anyway; slight penalty for
            // leaving a residual that matches next_item modulo class poorly.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 5.0; // near-miss creates temptation but fails
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin unless post_residual would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish base; encourage it only when open bins
    // are crowded (high mean residual) or stream is early (room to consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / cap;
        score = cap * 0.5
            + 25.0 * (1.0 - crowded)
            + 20.0 * progress
            - (open_bins_count as f64) * 2.0;
        // Don't open a new bin when the current placement is already harmonic.
        if fitting_bins_count > 0 && post_residual % 10 == 0 && pr < cap * 0.35 {
            score += 15.0;
        }
    }

    // Mild diversity penalty: too many open bins -> consolidate.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance archetype.
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Penalize "unusable" small gaps: gaps that cannot fit even the smallest
    // plausible item (<= 10) or only tiny items are dead space.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0; // hard dead-space penalty
    } else if post_residual > 0 && post_residual < dead_threshold * 2 {
        score += 12.0; // soft penalty for near-dead gaps
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits perfectly in the post-residual, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < dead_threshold {
        // placing current item would leave a gap that fits next item but creates
        // a tiny remainder afterwards: mild penalty
        score += 8.0;
    }

    // Open-bin pressure: penalize spreading across many bins, but ease off
    // when this is the last fitting bin (avoid forcing a new bin anyway).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);
    score += pressure;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // last chance: strongly favor using this bin over opening a new one
        score -= 30.0;
    }

    // New-bin candidate handling: make a fresh bin a mediocre default, chosen
    // only when all open bins would produce heavy dead space.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slightly above a good fit, below a bad fit
        score = 55.0 + 0.25 * mean_residual + pressure;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 25.0; // an open bin can fit it: discourage wasting it
        }
    }

    // Mean residual coupling: when open bins are already loose, prefer bins
    // that tighten the spread (small post_residual already does this); add
    // mild bonus for reducing variance.
    if (mean_residual - post_residual as f64).abs() < 10.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // chain fit: post residual exactly matches next item
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64; // next item still fits
        } else {
            score += 0.75 * (next_item_size - post_residual) as f64; // dead space relative to next item
        }
    }

    // Relative residual matching: prefer bins whose residual is close to mean residual
    // (keeps residuals homogeneous so future items fit many bins).
    let res = post_residual as f64;
    let dev = (res - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize large residual waste beyond half capacity (dead space creation).
    if post_residual > bin_capacity / 2 {
        score += 0.5 * (post_residual - bin_capacity / 2) as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Mild pressure to use existing bins when many are open.
    score -= 0.5 * open_bins_count as f64;

    // Late in the stream, prefer tighter packs (smaller post residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * progress * res;

    // New-bin candidate (empty bin): only attractive if nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless post residual (== capacity - item) is large
        // and there is lookahead mismatch elsewhere.
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin keeps room for the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 0.8;

    // Penalize dead space: residuals too small for the smallest plausible item
    let dead = if post_residual < 10 { (10 - post_residual) as f64 * 2.5 } else { 0.0 };
    score += dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into the post residual, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size <= bin_residual {
            // next item would need another bin anyway; mild penalty for wasting space
            score += (post_residual as f64) * 0.05;
        }
        // exact chaining bonus
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below mean residual (denser bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate logic: an empty bin is attractive only when the fit is poor
    // or few bins fit; otherwise discourage spreading out.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        if poor_fit || fitting_bins_count <= 1 {
            score -= 8.0;
        } else {
            score += 12.0;
        }
    }

    // Mild penalty for leaving residuals that are awkward (between 40 and 60)
    let pr = post_residual as f64;
    if pr > 40.0 && pr < 60.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, smoothed by quadratic coupling with stream progress.
    // Early on (progress ~ 0), residual space is cheap; late (progress ~ 1),
    // wasted residual is penalized quadratically.
    let mut score = pr * (1.0 + 1.7 * progress * progress);

    // Non-linear coupling: penalize residual that is too small to be useful
    // (dead space) with a smooth saturating term.
    let dead = (norm_pr / (norm_pr + 0.18)).exp() - 1.0;
    score += 12.0 * dead * (0.5 + progress);

    // Reward tight fits: item size relative to residual, smooth polynomial.
    let tightness = norm_item * norm_item / (norm_pr + norm_item * norm_item + 0.05);
    score -= 9.0 * tightness;

    // Lookahead coupling: favor bins whose post residual can host next item.
    if next_item_size > 0 {
        let fits_next = if pr >= norm_next * cap { 1.0 } else { 0.0 };
        let gap = ((pr - norm_next * cap).abs()) / cap;
        score -= 6.0 * fits_next * (1.0 - gap).max(0.0) * (1.0 - progress * 0.4);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * progress;

    // Nudge toward bins near the mean residual to keep residual distribution balanced.
    score += ((mean_residual - pr) / cap).powi(2) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes into reusable chunks.
    // Class A: post_residual is a multiple of 10 (common item granularity) -> highly reusable.
    // Class B: post_residual in (0,10) -> dead space (items are >= 1, but small classes waste).
    // Class C: large residual with room for the lookahead item -> bonus.
    let class_a = (post_residual % 10 == 0) as i32;
    let dead = (post_residual > 0 && post_residual < 10) as i32;

    score -= 8.0 * class_a as f64;
    score += 15.0 * dead as f64;

    // Tight fit reward: post_residual small but nonzero is bad; zero is perfect.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: evaluate its harmonic class
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 12.0; }
            if nr < 10 { score += 8.0; }
        } else {
            // next item won't fit here: slight penalty if this bin was the only fit
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize it so we prefer existing bins with decent fits, but if the best
    // existing fit leaves tiny dead space, the empty bin can still win.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a new bin is more attractive early when few bins are open
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // If current item is huge relative to capacity, new bin is natural
        if item_size * 5 >= bin_capacity * 4 {
            score -= 10.0;
        }
    }

    // Progress-aware scaling: late in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far below the mean (it's tight),
    // prefer filling it to consolidate fragmentation.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small gaps that likely cannot fit future items.
    if post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    } else if post_residual > 50 {
        // Large post residual is fine; slight reward to keep big gaps for big items.
        score -= (post_residual - 50) as f64 * 0.3;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count and progress.
        score += 15.0 + open_bins_count as f64 * 4.0 + progress * 20.0;
    } else {
        // Slight preference for tighter bins when many bins are open.
        score += (mean_residual - post_residual as f64).abs() * 0.1;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small dead space (unusable fragments), reward larger post_residual
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0;
        } else {
            score -= pr * 0.3;
        }
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            // next item fits: reward proportionally to how snugly
            score -= 40.0 + (n / (post_residual as f64)) * 30.0;
        } else {
            // next item won't fit: mild penalty scaled by wasted potential
            score += 10.0 * (1.0 - n / 100.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current open bins have poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is worse early; also worse if many open bins already
        score += 50.0 + 30.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // But if mean residual is small (open bins nearly full), new bin less bad
        score -= mean_residual * 0.4;
        if next_item_size > 0 && item_size <= 30 && next_item_size <= 30 {
            // small items: better to keep compacting
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end with near-zero waste.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= 12.0 * (1.0 - pr / cap).powf(6.0);

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
        if post_residual > 0 && post_residual < item_size {
            score += 3.0;
        }
    }

    // New-bin candidate: only attractive when current bins are crowded or fit poorly.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 * (1.0 - crowded) - 10.0 * progress;
        // Discard new bins when a good fit exists elsewhere.
        if post_residual + item_size as f64 <= cap && (cap - item_size as f64) < 0.25 * cap {
            score += 15.0;
        }
    }

    // Prefer filling bins with lower residual relative to the fleet mean (balance).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream, keep bins tight; late, allow more slack to close bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - t) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Reward tight fits, amplified as stream progresses (smooth cubic coupling)
    let tightness = 1.0 - (pr / cap);
    let progress_poly = progress * progress * (3.0 - 2.0 * progress);
    score -= tightness * tightness * (1.0 + 3.0 * progress_poly) * cap * 0.35;

    // Penalize small dead space more than large (quartic smooth term)
    let dead = pr / cap;
    score += 12.0 * dead * dead * (1.0 - dead) * (1.0 - dead);

    // Last-chance bonus when few fitting bins remain
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth gaussian-like coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_term = (-(gap * gap) / (2.0 * 400.0)).exp();
        score -= 6.0 * match_term;
    }

    // Mild penalty for proliferating open bins early on
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual (smooth quadratic)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Slight bias against opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class 0: post_residual is 0 (perfect fill) -> best possible outcome.
    // Class 1: post_residual in 1..=10 (tiny dead space) -> heavily penalized.
    // Class 2: post_residual divisible by 5 (aligns with common item sizes) -> mild bonus.
    // Class 3: post_residual divisible by 10 (harmonic with decade-sized items) -> bigger bonus.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score += 25.0; // dead space: nothing 10+ can ever use it
    } else {
        if pr % 10 == 0 {
            score -= 18.0;
        } else if pr % 5 == 0 {
            score -= 8.0;
        }
        // Integer-division thresholds: leftover quarters of the bin
        let quarter = bin_capacity / 4;
        if pr <= quarter {
            score += 6.0; // low leftover, likely stranded
        } else if pr >= 3 * quarter {
            score -= 5.0; // roomy leftover, still flexible
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains perfectly: reward, more if it's a tight fit
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 - slack.min(15.0) * 0.5;
        } else if next_item_size <= bin_residual {
            // Next item would have fit BEFORE this placement but not after:
            // penalize blocking the lookahead.
            score += 12.0;
        }
        // Harmonic alignment of next item with post-residual decade classes
        if pr >= next_item_size && (pr % 10 == 0 || next_item_size % 10 == 0) {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && pr <= 10 {
        score -= 20.0;
    } else if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins generally; only favor the new bin when the
    // current item would leave a very awkward remainder in every case.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (fragmentation cost)
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean-residual context: when open bins are already loose on average,
    // gently discourage stuffing this one into a bad class.
    if mean_residual > pr as f64 + 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space below the minimum item size is pure waste.
            score += 30.0;
        } else {
            // Small gaps are unlikely to be filled later; penalize superlinearly.
            let gap = post_residual as f64;
            score += (12.0 / gap) * (1.0 + gap / 20.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many bins open, prefer packing into existing bins
    // rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover; mild penalty for large gaps.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: neutral baseline, slightly penalized so it's only
    // chosen when existing bins have bad fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.1 * open_bins_count as f64;
    }

    // Mean residual coupling: when average residual is low, preserve tight bins.
    if (post_residual as f64) < mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score += (post_residual as f64 / cap) * 15.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post_residual as f64 - nxt;
        if diff == 0.0 {
            score -= 60.0; // perfect 2-chain
        } else if diff > 0.0 {
            // next fits: reward proportionally to how snug
            score -= 40.0 * (1.0 - diff / cap);
        } else {
            // next item cannot fit here: penalize leaving a gap next item can't use
            score += 12.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 30.0 * (1.0 - post_residual as f64 / cap) };
        // make new bin costly unless it enables a perfect next-item chain
        let chain_bonus = if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) == next_item_size { 35.0 } else { 0.0 };
        score = cap * 0.9 + desperation + 20.0 * progress - chain_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize leaving dead space below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Global state coupling: when many bins are open and mean residual is high,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    score -= consolidation * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it unattractive unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * (1.0 - progress);
        // If item is large and would leave a very tight residual in an existing bin,
        // opening a fresh bin becomes relatively more attractive.
        if item_size > bin_capacity / 2 && next_item_size > post_residual && post_residual > 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for very large leftovers relative to mean residual (imbalance).
    if post_residual as f64 > mean_residual * 1.5 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / c;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr_norm * (1.0 + 2.5 * progress + 3.0 * p2 + 2.0 * p3) * 20.0;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (15.0 + 25.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 1.5 * progress);
        } else {
            score -= (1.0 - (pr - nx) / c) * 5.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / c;
    score += dev * dev * (10.0 + 20.0 * p2);

    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Make new-bin candidate less attractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fraction classes.
    // Residuals in (0, 10] are near-dead space; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic classes via integer division: post_residual / 10 buckets.
    // Small buckets (0..2) are dead space; large buckets are reusable.
    let bucket = post_residual / 10;
    match bucket {
        0 => score += 15.0,             // residual 0..9 handled above too
        1 => score += 5.0,              // residual 10..19: marginal
        2..=4 => score -= 4.0,          // 20..49: decent
        _ => score -= 8.0,              // >=50: very reusable
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving space exactly usable by next item (harmonic match).
            score -= 12.0;
            // Extra reward if it's a near-perfect match (within 5).
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else {
            // Post-residual too small for next item: dead space risk.
            let overflow = next_item_size - post_residual;
            score += (overflow as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when item is large relative to capacity
        // and mean residual across open bins is small (fragmented state).
        score += 30.0;
        score -= (item_size as f64) * 0.2;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 25.0;
        }
    }

    // Prefer filling bins that are already relatively full (low residual):
    // best-fit bias beyond raw post_residual.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 5.0;
    }

    // Mean residual coupling: if open bins are on average roomy, penalize
    // spreading into a fresh bin less; if tight, favor tight fits.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Small harmonic tiebreak on item_size mod 10 class.
    let cls = item_size % 10;
    if cls == 0 {
        // Round items pack cleanly; slight reward for any placement.
        score -= 2.0;
    } else if post_residual % 10 != 0 && post_residual > 0 {
        // Placing awkward items into non-round residuals risks fragmentation.
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward tight fits.
    score -= 3.0 * item_size as f64 / bin_capacity as f64 * 10.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Slight preference for using bins with larger residuals when mean is low.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no open bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but scale against the mean residual landscape.
    score = score * 0.6 + (post_residual as f64 - mean_residual) * 0.4;

    // 2-step lookahead: reward bins whose post_residual exactly accommodates next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // Perfect chain fit: post_residual == next_item_size leaves zero waste next step.
            let gap = (pr - nxt).abs();
            let tightness = 1.0 - gap / bin_capacity as f64;
            score -= 18.0 * tightness * tightness;
            // Slight bonus if the chained fit is exact.
            if gap < 0.5 {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit here: post_residual becomes dead space risk.
            // Penalize proportional to how close it is to being useless (small but nonzero).
            let deadness = 1.0 - pr / nxt;
            score += 6.0 * deadness * deadness;
        }
    } else {
        // Last item: pure tight-fit mode.
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        // Extra reward if the leftover after placement is still usable for small items.
        if post_residual >= 10 {
            score -= 4.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when it enables a clean
    // two-item pairing with the lookahead item, or all open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening a fresh bin that can host both this item and the next is good
            // when the pair leaves little waste.
            let pair_waste = (post_residual - next_item_size as u32) as f64;
            new_bin_score -= 25.0 * (1.0 - pair_waste / bin_capacity as f64);
        }
        // Late in the stream, discourage opening bins with lots of residual left.
        new_bin_score += progress * 5.0 * (mean_residual / bin_capacity as f64);
        score = new_bin_score;
    }

    // Mild penalty for scattering across many open bins (bin consolidation).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 22.0 + 0.35 * next_item_size as f64;
        } else {
            // Penalize leaving residual that next item cannot use but is still sizable.
            let waste = post_residual as f64;
            if waste >= next_item_size as f64 * 0.5 {
                score += 8.0;
            }
        }
    } else {
        // Last item: pure tightness.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less as stream progresses.
        let new_bin_penalty = 55.0 - 25.0 * progress;
        // Extra penalty if many open bins already exist and item fits elsewhere well.
        score += new_bin_penalty + 0.15 * open_bins_count as f64;
    } else {
        // Prefer using existing bins more as stream progresses.
        score -= 6.0 * progress;
    }

    // Global state coupling: if mean residual is high, prefer bins below mean
    // (fill the emptier bins to balance residuals).
    if bin_residual as f64 > mean_residual {
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Slight preference to keep number of open bins from exploding early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on, prefer tight fills less aggressively;
    // late in the stream, dead space is more costly, so amplify residual penalty.
    let progress_amp = 0.5 + 1.5 * progress * progress;
    score *= progress_amp;

    // Reward bins whose residual closely matches the item (smooth Gaussian-like fit term)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * (-fit_gap * fit_gap * 50.0).exp();

    // Lookahead: if next item fits into post_residual, reward this placement smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 8.0 * nx * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when bin residual is far below mean residual (fragmenting the pool)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate handling: empty bin gets a smooth cost that shrinks with progress
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (mod classes) are more likely reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that fall into "useful" residue classes.
        // A residual is useful if a typical item (10..80) could exactly fill it
        // or leave a small, still-usable remainder.
        if pr % 10 == 0 {
            score -= 8.0; // round residual: highly reusable
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Penalize awkward dead-space bands via integer-division thresholds.
        let band = pr / 10; // 0..10 harmonic band
        match band {
            0 => score += 15.0,           // 0..9: nearly dead space
            1 => score += 6.0,            // 10..19: only tiny items fit
            2 | 3 => score -= 2.0,        // 20..39: decent
            4 | 5 | 6 => score -= 5.0,    // 40..69: very flexible
            _ => {}                       // 70+: fine, little penalty
        }
    } else {
        score -= 20.0; // perfect closure of the bin
    }

    // Lookahead: does this placement let the next item fit well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact fit for next item is golden.
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                let slack = post_residual - next_item_size;
                if slack % 10 == 0 {
                    score -= 10.0;
                } else {
                    score -= 5.0;
                }
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow class.
            let overflow = next_item_size - post_residual;
            score += (overflow / 10) as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current residual is small/useless and stream is not near the end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin; cheap early, expensive late.
        score = bin_capacity as f64 * (0.55 + 0.45 * progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin fits the lookahead comfortably
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    // Congestion: many open bins -> prefer tightening existing ones.
    let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += congestion * 0.15;

    // Mild phase coupling: early stream, tolerate loose fits; late stream, be strict.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste. Penalize them hard.
    if post_residual > 0 {
        // If the leftover cannot fit the next item (or any typical small item),
        // it is likely dead space.
        let min_useful = if next_item_size > 0 { next_item_size } else { 1 };
        if (post_residual as u64) < (min_useful as u64) {
            score += 60.0; // unusable gap for the lookahead item
        }
        if post_residual < 10 {
            score += 45.0; // tiny sliver, likely dead space in general
        }
    }

    // Reward tight fits (small post_residual) superlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is close to (item + next item) so both fit.
    if next_item_size > 0 {
        let combined = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64) >= combined {
            score -= 12.0;
        }
        // Penalize if placing here leaves a gap just below the next item size
        // (worst kind of near-miss dead space).
        if post_residual > 0 && (post_residual as f64) < next_item_size as f64 && post_residual >= 1 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many bins open, prefer consolidation into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: only attractive when current item barely fits
        // nowhere well or there are few open bins.
        score += 10.0 + 15.0 * pressure;
        // A new bin is reasonable if this item is large relative to residual mean.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a forced new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize dead space relative to mean residual.
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it can chain the next item well
    // and current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Penalize leaving very small unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 + 5.0 * (6 - post_residual) as f64;
    }

    // Penalize large dead space, more so late in the stream.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let dead = post_residual as f64;
    score += 0.4 * dead * dead / bin_capacity as f64 * (0.5 + t);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * slack;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual likely unusable by next item: penalize.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with residuals below the mean (consolidating tight bins),
    // but slightly counteract when open bin count is high.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.15 * diff * (1.0 + open_bins_count as f64 / 20.0);

    // Mild preference for using existing bins over opening new ones early;
    // later, allow new bins more freely to avoid fragmentation.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 30.0 * (1.0 - t) - 10.0 * t;
        score += new_bin_bonus;
        // Opening a new bin is attractive if the item is large and mean residual is small.
        score -= 0.3 * (item_size as f64) - 0.2 * mean_residual;
    }

    // Slight reward for filling big items into partially filled bins.
    score -= 0.05 * item_size as f64 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling: post-residual penalized more as stream progresses
    let coupling = norm_pr * (1.0 + 2.0 * progress * norm_pr + progress * progress * norm_pr * norm_pr);
    score += 40.0 * coupling;
    // reward tight fits (small post-residual relative to item)
    let tight = 1.0 - (pr / (item_size as f64 + 1.0)).min(1.0);
    score -= 25.0 * tight * (1.0 + progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }
    // lookahead: favor bins whose post-residual fits next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 10.0 * (1.0 - progress);
    }
    // penalize bins deviating from mean residual (smooth quadratic)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;
    // new-bin candidate: mildly penalize early, allow late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10.
    // Residuals that are "dead" (small, unusable) are penalized.
    let class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space class
    } else if class == 0 {
        score -= 8.0; // perfectly divisible residual is reusable
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // If the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item nearly fills this bin
        }
    } else if next_item_size > 0 {
        score += 12.0; // next item cannot use this bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fraction-of-capacity thresholds on post_residual via integer division.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 10.0; // small leftover, poor future utility
    } else if post_residual >= bin_capacity / 2 {
        score -= 10.0; // roomy bin stays attractive
    }

    // Late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 * 0.3);

    // Prefer bins below mean residual (compact bins absorb items).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
            if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
                score -= 25.0; // big next item benefits from fresh bin
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum conceivable item footprint) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    }

    // Reward near-perfect fits quadratically.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if the item would leave a very
        // usable remainder and open bins are congested (high mean residual
        // relative to item size means poor fits elsewhere).
        score += 45.0 + 2.0 * open_bins_count as f64;
        if post_residual >= 10 && post_residual <= 50 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // new bin can also host the next item
        }
    } else {
        // Existing bin: reward if the leftover can host the lookahead item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 5.0; // leftover likely dead for the next item
        }
    }

    // Slight global pressure: as the stream progresses, discourage spreading
    // across many bins; favor consolidating into existing residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    score -= 0.3 * mean_residual * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead bonus: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 - gap * 1.5;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportional to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += shortfall * 0.8;
    }

    // Exact fit of current item is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit, tiny dead space
    }

    // Penalize bins that deviate from the mean residual (prefer balanced usage),
    // but only mildly so lookahead dominates.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless post_residual is huge
    // (i.e., item is small) or lookahead suggests a large item next.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 55.0; // opening a bin sized for the next item is good
        }
    }

    // Late in the stream, tighten packing: prefer filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0;
        }
        // Perfect two-item packing: this bin takes item then next item exactly.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (penalize new bin in that case).
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (mean_residual.max(1.0));
        // Open a new bin if mean residual across open bins is small relative
        // to the item, or many bins are already open with poor fit.
        if mean_residual < item_size as f64 * 1.15 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 5.0 + pressure;
        }
        // Late in the stream, avoid opening new bins with leftover capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Crowd control: with many open bins, prefer consolidating into tighter fits.
    if open_bins_count > 4 {
        score -= 0.5 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_fit = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Base: post residual, with non-linear polynomial shaping
    let pr_n = pr / cap;
    let mut score = pr * (1.0 + 0.5 * pr_n * pr_n);

    // Smooth coupling: residual squared penalized more as stream progresses
    score += 20.0 * pr_n * pr_n * progress;

    // Reward tight fits (small post residual) with smooth term
    score -= 15.0 * (1.0 - pr_n) * (1.0 - pr_n) * fit_ratio;

    // Lookahead: penalize if next item cannot use the post residual (smooth)
    let gap = (pr - next_item_size as f64).max(0.0) / cap;
    score += 12.0 * gap * gap * (1.0 - next_fit);

    // Last-chance bonus: smooth sigmoid-like weight on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).max(0.0));
    score -= 25.0 * last_chance * (1.0 - progress * 0.5);

    // Fragmentation pressure: penalize bins far below mean residual
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate handling: empty bin gets mild baseline penalty
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress * (1.0 - fit_ratio);
    }

    // Open bins count pressure (smooth)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr_n;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: treat capacity as 4 quarters.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward near-exact fills: post_residual in {0} is perfect, small values good.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space in the "useless zone": residual that no typical
    // item (>=10, but unknown distribution so assume >= half of smallest
    // plausible) can use. Modulo-style banding on post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny sliver, nearly dead
    }

    // Harmonic class penalty: post_residual in the lowest quarter but not tiny
    // is awkward; post_residual in upper half is comfortable for future items.
    if post_residual > half {
        score -= 6.0;
    } else if post_residual > quarter {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 4.0 * (quarter as f64 - post_residual as f64) / quarter as f64;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has neutral base; make it
    // slightly unattractive unless open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, must open
        }
        // If many open bins with large mean residual, prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if next item fits the post-residual well, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0; // next item completes this bin nicely
            } else if slack <= quarter {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here: post_residual becomes dead space
            // unless some future small item uses it; mild penalty.
            score += 3.0;
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers mildly.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit typical future items are wasted.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item in this bin,
    // but reward when the next item fits exactly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            score += (next_item_size - post_residual as u32) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage filling.
    let obp = open_bins_count as f64;
    score += obp * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below mean (tighter bins get filled).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it unattractive unless it is a genuinely good option
    // (i.e., only chosen when all open bins would leave large dead space).
    if bin_residual == bin_capacity {
        score += 30.0 + obp * 2.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If next item is large, a fresh bin is more tolerable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space relative to smallest possible item
    if post_residual > 0 {
        score += (post_residual as f64 / 10.0).powi(2) * 0.5;
    } else {
        score -= 30.0; // perfect fit reward
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how well it fits after
            let after2 = post_residual - next_item_size;
            score -= 10.0 - (after2 as f64) * 0.1;
        } else {
            // next item cannot follow: penalize leftover gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only bin that fits item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare residual against mean residual of open bins
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Prefer opening new bins only when fit is terrible
    if bin_residual == bin_capacity {
        // new empty bin: competitive baseline
        score = (bin_capacity - post_residual) as f64 + 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: strongly favor bins where the item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: penalize leaving dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to next item
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.9 * waste.min(30.0);
        } else if post_residual >= next_item_size {
            // leaving room for the next item is good
            score -= 6.0;
            // extra reward if next item fills the leftover almost exactly
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score -= 8.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // into existing bins is poor or we are early with few bins open
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // early in stream, opening bins is cheaper (builds a pool)
        score -= 35.0 * (1.0 - progress);
        // fewer open bins -> cheaper to open another
        score -= 3.0 * (10usize.min(open_bins_count)) as f64;
        // if many bins can fit the item, opening new is wasteful
        score += 8.0 * (fitting_bins_count as f64).min(6.0);
        // large items waste less in a fresh bin
        score -= 0.25 * item_size as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global state coupling: prefer bins near the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late in the stream: consolidate aggressively, avoid spreading
    if progress > 0.7 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual); later,
    // slight relaxation so residual flexibility is preserved.
    let progress_warp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let base = pr * (1.0 - 0.35 * progress_warp);

    // Non-linear dead-space penalty: quadratically punish small unusable
    // residuals, scaled by whether the next item could use them.
    let dead_penalty = if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 { 0.6 * gap * gap / cap } else { -0.4 * (-gap) / cap }
    } else {
        0.12 * norm_pr * norm_pr * cap
    };

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    let last_chance = if fitting_bins_count == 1 { -18.0 } else { 0.0 };

    // Penalize bins whose residual deviates strongly from the mean
    // (keeps the pool of usable residuals homogeneous).
    let spread = (pr - mean_residual) / cap;
    let homogenize = 3.0 * spread * spread * cap;

    // Mild crowding penalty: spreading across many open bins is costly.
    let crowding = 0.05 * open_bins_count as f64;

    // Smooth fit-quality term: reward near-exact fits via a Gaussian bump.
    let fit_quality = -6.0 * (-(norm_pr * norm_pr) / 0.005).exp();

    let mut score = base + dead_penalty + homogenize + crowding + fit_quality + last_chance;

    // New-bin candidate: encourage opening a fresh bin only when residuals
    // across open bins are fragmented and the item is large.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score -= 4.0 * (1.0 - fragmentation) * (1.0 - progress);
        score += 2.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify post_residual by integer division thresholds (dead-space bands).
        let q = post_residual / 10; // 0..10 harmonic class
        score += match q {
            0 => -40.0,               // leftover < 10: nearly unusable, great fit
            1 => -20.0,               // 10..19: fits only tiny items
            2 => -5.0,                // 20..29
            3 => 5.0,
            4 => 12.0,
            5 => 18.0,                // ~half capacity free: moderately useful
            6 => 15.0,
            7 => 8.0,
            8 => -2.0,                // 80..89: big space, very reusable
            9 => -10.0,
            _ => -20.0,
        };

        // Modulo coupling: leftover divisible by common item classes is friendlier.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }

        // Lookahead: reward leftovers that exactly fit the next item.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 60.0;
            } else if post_residual >= next_item_size {
                score -= (post_residual - next_item_size).min(20) as f64 * 0.5;
            } else {
                // leftover cannot host next item: mild penalty scaled by shortfall
                score += (next_item_size - post_residual).min(30) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when the stream is early
    // or no good existing option exists (large item, tight fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = post_residual < 10;
        // Prefer new bin when item is large (poor fits likely) or late in stream
        // with many open bins (fragmentation already high).
        let mut new_bin_bonus = -10.0
            + progress * 20.0
            + (item_size as f64 - 50.0).max(0.0) * 0.6
            + (open_bins_count as f64).ln().max(0.0) * 3.0;
        if tight_fit {
            new_bin_bonus += 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // next item pairs perfectly with this item in a fresh bin
            new_bin_bonus += 30.0;
        }
        score += new_bin_bonus;
        // Baseline: a fresh bin keeps residual = capacity - item_size,
        // which the base score already reflects; keep it competitive.
        score -= 5.0;
    }

    // Spread-awareness: prefer bins below mean residual (keep big holes open).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host the
    // smallest plausible item (1..100 stream) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize mid-range unusable gaps more aggressively than large leftovers.
    if post_residual >= 10 && post_residual <= 30 {
        score += 12.0 + 0.3 * (30 - post_residual) as f64;
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than opening yet another one.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make the empty bin moderately attractive
    // only when the current bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual > 40 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item can exactly fill this bin's post-residual,
    // reward keeping that gap; otherwise penalize gaps that nothing can use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Late in the stream, tighten up: prefer tighter packs as we approach the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            // Perfect lookahead fit: next item exactly fills the leftover space.
            let match_quality = (pr - next).abs();
            score -= 60.0 * (1.0 - match_quality / 100.0);
            // Extra bonus if post residual is small but usable (tight two-item chain).
            if pr - next <= 10.0 {
                score -= 25.0;
            }
        } else {
            // Post residual too small for the next item: penalize dead space.
            score += 20.0 + 0.5 * next;
        }
    }

    // Compare post_residual against mean residual: keep bins below-average (tighter) preferred.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 10.0 * rel;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit well (post_residual small).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * (open_bins_count as f64);
    }

    // Slight preference to fill bins more tightly overall as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (size ~1..100 unknown, use 10 as safe floor).
    if post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Wasted space that cannot serve the next item.
        score += 2.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Global pressure: when many bins are open relative to progress, prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.15 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual deviates below the mean (consolidate small leftovers).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, be more conservative: penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress;
        // But early on, allow new bins to keep flexibility.
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual, modulated by stream progress.
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: interaction of item size with progress.
    score -= 30.0 * norm_item * (1.0 - norm_item) * (0.4 + progress);

    // Penalize dead space that cannot fit the next item (smooth coupling).
    let gap_next = (pr - next_item_size as f64).max(0.0) / cap;
    score += 25.0 * gap_next * gap_next * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when bin is far below mean residual (keeps balance).
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only early or when item is large.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).powf(2.0);
        score -= 15.0 * early + 10.0 * norm_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "usable slots"
    let post = post_residual as i64;
    let residue = post % 10;
    // Dead-space penalty: residuals that can't host small items (sizes >= 1..100)
    if post > 0 && post < 10 {
        score += 40.0; // unusable sliver
    } else if residue == 0 {
        score -= 12.0; // perfectly aligned residual
    } else if residue <= 3 {
        score += 6.0;  // awkward small remainder
    } else {
        score -= 3.0;  // reasonably reusable residual
    }

    // Integer-division thresholds: how many "half-bin" chunks remain
    let half_chunks = post / 50;
    score -= 8.0 * half_chunks as f64;

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx <= post {
            // reward proportional to how snugly next item fits
            let slack = (post - nx) as f64;
            score -= 15.0 - 0.3 * slack;
            // harmonic bonus if combined packing leaves aligned residual
            if (post - nx) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize slightly unless bin nearly full
            let overflow = (nx - post) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // last item: just minimize waste
        score += 0.5 * post as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        score = cap_f * 0.75 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && (next_item_size as u32) >= item_size {
            score -= 10.0; // fresh bin preserves room for larger follow-up
        }
    }

    // Progress-aware tightness: later in stream, prefer tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post as f64) * 0.2;

    // Deviation from mean residual: prefer bins below mean (tighter)
    score += 0.1 * ((post as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it is nonzero but smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling
    // existing bins and penalize opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += open_pressure;
        // But if the next item pairs well with the leftover space, soften the penalty.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Filling an existing bin slightly relieves pressure.
        score -= open_pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins tighter than the mean residual (fill the emptiest-fitting bins least;
    // i.e., favor bins whose residual is close to what we consume).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits snugly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for next item -> strong bonus
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.6;
            // If next item cannot fit into the post-residual, penalize wasted space
            if (post_residual as i64 - next_item_size as i64) < 0 {
                score += (next_item_size as f64 - post_residual as f64) * 0.4;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins that are much emptier than the mean (fragmentation risk)
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.1;
    }

    // Prefer filling bins tightly: small post-residual is good
    if post_residual < 10 {
        score -= 15.0;
    }

    // Discourage opening a new bin late in the stream unless necessary
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 45.0 + 40.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, dead space below threshold is penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 6.0 * (1.0 - dead / 10.0).max(0.0); // tiny leftovers (1..10) are wasteful
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving moderately small gaps
            let gap = post_residual as f64;
            if gap < next_item_size as f64 && gap > 0.0 {
                score += 4.0 * (1.0 - gap / (next_item_size as f64));
            }
        }
    } else {
        // last item: prefer minimal residual
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (favor spreading);
    // late in the stream, consolidate tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 - 20.0 * t); // new bins favored early, penalized late

    // Global state coupling: many open bins with high mean residual -> discourage new bins,
    // encourage using existing slack.
    let mr = mean_residual;
    score += new_bin * (mr / 20.0);
    if !new_bin.bit() {
        score -= (mr - post_residual as f64).max(0.0) * 0.05;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    score += new_bin * (open_bins_count as f64 * 0.3);

    // Item size interaction: large items prefer bins with just-enough room.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;
    // Reward tight fits: strongly discount small post-residuals
    score -= (1.0 - pr / cap).powi(3) * 30.0;
    // Penalize dead space that is too small for typical future items
    let dead = (pr / cap).clamp(0.0, 1.0);
    score += 12.0 * dead * (1.0 - dead) * (1.0 + progress);
    // Stream-progress coupling: later in the stream, prefer tighter packing more aggressively
    score -= progress * (1.0 - pr / cap) * 15.0;
    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste = pr - nxt;
            score -= 8.0 * (1.0 - waste / cap).powi(2);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }
    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // Mild penalty for proliferating bins relative to mean residual
    score += (open_bins_count as f64).ln() * 0.5;
    // Prefer bins whose residual is close to the mean (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals in fine-grained classes are more reusable; penalize coarse classes.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class
    score += (class as f64) * 2.0;

    // Reward small post_residual (tight fit) with a non-linear bonus.
    if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 5.0;
    }

    // Dead-space penalty: residuals that few typical items can use.
    // Modulo check: residual that is not close to any "nice" fraction of capacity.
    let nice = [0u32, 20, 25, 30, 40, 50, 60, 70, 75, 80, 90, 100];
    let mut min_dist = 1000u32;
    for &n in &nice {
        let d = (pr as i32 - n as i32).abs() as u32;
        if d < min_dist { min_dist = d; }
    }
    score += (min_dist as f64) * 0.6;

    // Harmonic pairing: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Partial reward scaled by how much of the residual the next item consumes.
        let fill = next_item_size as f64 / pr as f64;
        score -= 15.0 * fill;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // avg leftover across open bins
        // If open bins are crowded (low mean residual) or few bins fit, new bin is fine.
        let crowding = 1.0 - pressure;
        score += 35.0 * pressure;      // penalize new bin when open bins have room
        score -= 20.0 * crowding;      // reward new bin when bins are crowded
        if fitting_bins_count <= 1 {
            score -= 45.0;             // poor fit everywhere -> open new bin
        }
        // Early stream: slightly prefer consolidating into few bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is too small for even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Nonlinear penalty on small-but-nonzero dead space: the tighter the fit,
    // the better, but gaps that are tiny relative to capacity are risky.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    if pr > 0.0 {
        // Exponential penalty for very small gaps (hard to reuse)
        score += 40.0 * (-pr / 12.0).exp();
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 15.0;
    }
    // Penalize if next item almost fits but not quite (creates temptation to waste)
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across too many bins,
    // but encourage using existing bins when many are open.
    let ob = open_bins_count as f64;
    score += 0.6 * ob;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless the fit
    // into existing bins would be terrible (large post_residual).
    if bin_residual == bin_capacity {
        // Base cost of a new bin
        score += 55.0;
        // But if all existing fits would leave big dead space, allow new bin
        if pr < 20.0 {
            score -= 35.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is close to item
    // (tight packing) when mean residual is high (many loose bins available).
    let mr = mean_residual;
    if mr > 0.0 {
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * tightness * (mr / cap);
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (exploration); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post-residual (tight fit).
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that no item (>=1) can use is pure waste.
    // With unknown distribution, assume items >= 10 unless stream is tiny;
    // penalize residuals below the plausible minimum item size heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Tightness bonus: reward near-perfect fills.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate calibration: an empty bin has post_residual = capacity - item.
    // Make it attractive only when existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slight preference to reuse bins when they fit well.
        score += 6.0;
        // Early in stream, opening bins is cheap (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item could exactly fill this bin's post-residual,
    // reward leaving that gap; if next item cannot fit the post-residual but
    // could fit other bins, penalize wasting space here.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain placement
        } else if next_item_size > post_residual {
            // post-residual becomes dead space for the next item
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits; small reward proportional to how snugly
            score -= 0.15 * (post_residual - next_item_size) as f64;
        }
    }

    // Global state coupling: penalize adding to bins whose residual is far
    // above the mean (they are the "big holes" better saved for large items),
    // and reward bins near the mean residual.
    let resid_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * resid_gap;

    // If many bins are open, prefer consolidating into existing space.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);
    }

    // Discourage leaving residuals in the awkward 1..=9 range (hard to fill).
    if post_residual >= 1 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / c;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.35 * progress);

    // Quadratic dead-space penalty: small post residuals are great, but
    // very small ones (unusable slivers) get a smooth extra reward curve.
    let norm_post = post / c;
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * fit_ratio;

    // Cubic coupling between post residual and stream progress:
    // late in the stream, tighter packing matters more.
    score += 8.0 * norm_post.powf(3.0) * (0.5 + progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Lookahead: reward if next item fits smoothly into the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let snug = (post - nx) / c;
            score -= 6.0 * (1.0 - snug * snug);
        } else {
            // penalize blocking the next item
            score += 4.0 * (nx - post) / c;
        }
    }

    // Mild penalty for spreading across many bins vs. mean residual
    score += 0.05 * (open_bins_count as f64) * norm_post;
    score += 0.02 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is "wasted" grows
    // when post_residual falls below the smallest possible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver -> strong penalty
    }

    // Integer division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    let bucket = post_residual / quarter;
    score += match bucket {
        0 => -6.0,   // post_residual < 25: very tight fit, great
        1 => -2.0,   // 25..49: decent
        2 => 2.0,    // 50..74: mediocre
        _ => 6.0,    // >=75: wasteful placement
    };

    // Modulo arithmetic: residuals divisible by common item sizes (10, 20, 25, 50)
    // are reusable "harmonic" gaps -> reward them.
    let r = post_residual;
    if r > 0 {
        let mut harmonicity = 0.0;
        if r % 10 == 0 { harmonicity += 4.0; }
        if r % 20 == 0 { harmonicity += 3.0; }
        if r % 25 == 0 { harmonicity += 3.0; }
        if r % 50 == 0 { harmonicity += 4.0; }
        score -= harmonicity;
    }

    // Lookahead coupling: if next_item_size fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // next item also leaves a harmonic residual? bonus.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to typical open-bin residuals, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and mean residual is small (poor fits elsewhere)
        let attractiveness = item_frac - mean_frac;
        score = 55.0 - attractiveness * 40.0 + progress * 5.0;
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference to keep open bin count low late in the stream.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps after placement.
    // A post_residual that is too small for the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize large post_residual when mean residual is already high (wasteful spread).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Open bins pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when residuals across bins are poor.
        score += 30.0 + 20.0 * progress - 0.3 * mean_residual;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills leftover space
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.5;
        } else {
            // Next item won't fit here: penalize wasted potential
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize creating unusable dead space relative to smallest possible items
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // dead space below min item size
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate: discourage opening a new bin unless the fit is poor
    if bin_residual == bin_capacity {
        score += 60.0;
        // But allow opening if item is large and fits poorly elsewhere
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that can't hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
        } else {
            score += 3.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let openness = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += openness * (bin_residual as f64) * 0.3;

    // Pull toward bins with residual below the mean (use the emptier side less)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: later in the stream, be more conservative about opening new bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless item is large
        score += 15.0 + 25.0 * progress - 0.05 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild bonus for exact-capacity-friendly large items in nearly matching bins
    if item_size as f64 / cap > 0.6 && fit_ratio > 0.8 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger residuals (cheap bins); later,
    // penalize residual quadratically to force tight packing.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += progress_weight * 40.0 * norm_post * norm_post * cap;

    // Reward near-perfect fills with a smooth cubic bonus.
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (next - post).max(0.0) / cap;
        score += 25.0 * gap * gap * cap;
        // Smooth reward when post_residual still accommodates the next item.
        let fit_next = (post / next).min(1.0);
        score -= 12.0 * fit_next * fit_next;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_item);
    }

    // Mild dispersion penalty: avoid fragmenting residuals far below mean.
    let disp = (mean_residual - post) / cap;
    score += 10.0 * disp * disp;

    // Encourage consolidation when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 create "dead zone" classes
    let residue_class = (post_residual % 10) as f64;
    // Residuals that are small-but-nonzero (1..=9) are nearly dead space; penalize hard
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - residue_class * 2.0;
    }

    // Perfect fit reward (harmonic zero class)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Integer-division thresholds: how many size-10 "slots" remain
    let slots = post_residual / 10;
    score -= slots as f64 * 3.0;

    // Next-item lookahead: harmonic match between post_residual and next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can chain into this bin: reward proportional to leftover after chain
            let chain_left = post_residual - next_item_size;
            score -= (chain_left as f64) * 0.8 + 15.0;
        } else {
            // next item cannot fit here: penalize by the gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // modulo coupling: next item aligns with residual class (residual % 10 == next % 10)
        if post_residual > 0 && (post_residual % 10) == (next_item_size % 10) && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // base penalty so a fresh bin is not chosen unless existing fits are bad
        score += 20.0;
        // early in stream, opening bins is cheaper; late in stream, pack tightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        // if many open bins with high mean residual, opening new bin is wasteful
        score += mean_residual * 0.15;
    }

    // Prefer bins tighter than the mean residual (good fill balance)
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Large items: prefer placing into bins where they leave harmonic-friendly residuals
    if item_size >= 50 && post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

