    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced as stream progresses.
        score = bin_capacity as f64 * 0.5 + 40.0 - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
