    } else if fitting_bins_count > 1 {
        // With many fitting bins, mild preference toward tighter ones via residual deviation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Global state: when many bins are open with large mean residual, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are spacious or early in the stream.
        score += 45.0 + 30.0 * (1.0 - progress) + 0.05 * mean_residual * open_bins_count as f64;
        // But if the item is huge relative to capacity, new bin may be justified.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Reward using existing bins more as the stream progresses (consolidation).
        score -= 10.0 * progress;
    }

    // Size-aware micro-adjustment: large items prefer largest residual bins.
    if item_size > bin_capacity / 2 {
        score += 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Core: quadratic penalty on leftover space (waste minimization)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: later in the stream, tighten more aggressively
    let tighten = 1.0 + 2.0 * progress * progress;
    score *= tighten;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // good chaining: leftover accommodates next item
            let chain_fit = 1.0 - (pr - nxt).abs() / cap;
            score -= 3.0 * chain_fit * (1.0 - progress);
        } else {
            // leftover too small for next item: penalize dead space
            score += 0.5 * (pr / nxt) * (1.0 - progress);
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor, smooth)
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= 2.0 * mean_gap;

    // Penalize opening a new bin unless item is large relative to capacity
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let fill_ratio = item_size as f64 / cap;
        score += cap * (0.6 - 0.5 * fill_ratio) * (1.0 - 0.3 * progress);
    }

    // Mild dispersion pressure: avoid hoarding many loose bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small dead space" classes (mod thresholds) are penalized less.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => -40.0,                              // perfect fit
        1..=5 => -25.0,                          // near-perfect
        6..=10 => -12.0,
        11..=20 => 0.0,
        21..=30 => 6.0,
        31..=50 => 12.0,
        _ => 20.0,                               // large leftover: wasteful
    };
    score += class_bonus;

    // Modulo-10 harmonic refinement: leftovers that are multiples of 10
    // are more reusable for typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 15.0 + 0.1 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to the upcoming item.
        score += 0.3 * (next_item_size - pr) as f64;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the current fit is genuinely bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins become less attractive as the stream matures.
        let new_bin_penalty = 10.0 + 35.0 * progress + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // A fresh bin is decent if the item is large (poor fit elsewhere likely).
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        // If the next item is large too, a fresh bin preserves flexibility.
        if next_item_size as f64 > 0.5 * cap {
            score -= 10.0;
        }
    } else {
        // Prefer tighter bins: reward small residual before placement.
        score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Mean-residual coupling: if open bins are generally loose, discourage
    // spreading; if they are tight, prefer any fitting bin.
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Fractional capacity fill reward: how full the bin becomes.
    let fill = 1.0 - (post_residual as f64 / cap);
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's too small to hold even the smallest plausible item.
    let min_item = 1.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Penalize small-but-nonzero post_residual more aggressively (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: residual mostly consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: discourage spreading across many bins when few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 - progress);
    score += bin_pressure * 2.5;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    // (large dead space) and open-bin pressure is high.
    if bin_residual == bin_capacity {
        let dead_space_penalty = post_residual as f64; // = capacity - item
        let fit_quality = mean_residual - dead_space_penalty;
        if fit_quality < 0.0 && open_bins_count > 2 {
            score -= 20.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 1.5;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - next_fit / (bin_capacity as f64));
            if post_residual == next_item_size {
                score -= 80.0; // chained perfect fit
            }
        } else {
            // Next item cannot use this bin's remainder: penalize dead space.
            score += 25.0;
        }
    }

    // Compare against mean residual: bins with less residual than mean are more valuable to fill.
    let diff = mean_residual - (bin_residual as f64);
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize slightly unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: be slightly more willing to open bins; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual quadratically.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space: post-residual too small to ever fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Extra reward for perfectly chaining current + next item.
        if item_size + next_item_size <= bin_residual && bin_residual == bin_capacity {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 15);
        let large_item = (item_size as f64) > mean_residual;
        if poor_fits && large_item {
            score -= 30.0;
        } else {
            // Discourage wasteful new bins, especially early in the stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into bins above the mean (filling laggards).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late-stream consolidation: as the stream ends, prefer bins that get
    // closest to full to avoid stranding capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (fraction of bin left empty)
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: penalize large residuals more as stream progresses
    score += 40.0 * progress * pr_norm * pr_norm;

    // Penalize medium dead-space quadratically (unusable gaps)
    score += 10.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly early on
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / bin_capacity as f64;
        score += 20.0 * gap * gap;
        // Bonus if next item fits exactly
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: mild pressure to consolidate into existing bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Mean residual coupling: prefer bins near the mean residual (smooth interaction)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it attractive only when item is large and fits poorly elsewhere
    if bin_residual == bin_capacity {
        score += 6.0 + 25.0 * (1.0 - item_size as f64 / bin_capacity as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual classes mod 10
    let class = post_residual % 10;
    // Dead-space penalty for residuals that are hard to fill (small nonzero slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }
    // Favor residuals that are multiples of 10 (harmonic alignment with capacity 100)
    if class == 0 && post_residual > 0 {
        score -= 25.0;
    } else if class == 5 {
        score -= 8.0;
    }

    // Integer-division threshold coupling: post_residual / next_item_size
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward tight coupling
            let ratio = post_residual as f64 / next_item_size as f64;
            if ratio < 1.6 {
                score -= 40.0; // near-perfect chain
            } else {
                score -= 15.0 / ratio;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing residuals are large-but-awkward and item is big
        if item_size > 60 && fragmentation > 0.4 {
            score -= 30.0 * progress;
        } else {
            score += 80.0 + 40.0 * (1.0 - progress);
        }
    }

    // Mild preference to fill bins with small residuals (close them out)
    if bin_residual < bin_capacity {
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // Encourage consolidation when many bins are open
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills remaining space
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack * 0.3);
            if slack == 0.0 {
                score -= 60.0; // exact 2-item fill is ideal
            }
        } else {
            // Next item won't fit: penalize dead space creation
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score += 0.25 * dev;

    // Penalize very small unusable post-residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish base, penalize unless current fit is bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no existing bin fits well, allow opening a new bin
        if post_residual as f64 > mean_residual {
            score -= 50.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 30.0 * fill_ratio * fill_ratio;
    }

    // Penalize dead space: small post_residual that cannot hold typical items is fine,
    // but mid-range post_residual is wasted. Reward exact or near-exact closures.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 25.0;
    } else if pr < 10.0 {
        score -= 12.0 * (10.0 - pr) / 10.0;
    } else if pr >= 10.0 && pr < 30.0 {
        // awkward dead zone
        score += 8.0 * (1.0 - (pr - 10.0) / 20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
            // extra reward if next item exactly fills post-residual
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // penalize leaving a gap just slightly smaller than the next item
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > -10.0 && gap < 0.0 {
                score += 6.0 * (1.0 + gap.abs() / 10.0);
            }
        }
    }

    // Global state coupling: many open bins with large mean residual suggests
    // fragmentation; be more selective and favor consolidating into existing bins.
    let fragmentation = mean_residual / bin_capacity as f64;
    if open_bins_count > 3 {
        score -= 5.0 * fragmentation * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, keep bins flexible (avoid tiny residuals);
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (pr / bin_capacity as f64);
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    // or the stream is early and fragmentation is low (fresh bin keeps future options).
    if bin_residual == bin_capacity {
        let bad_fit = fill_ratio_proxy(item_size, bin_capacity);
        let early = 1.0 - progress;
        score = score.max(0.0) + 15.0 - 20.0 * bad_fit * early - 8.0 * fragmentation;
        if fitting_bins_count == 1 {
            score += 30.0; // don't waste an almost-fitting bin
        }
    }

    score
}

#[inline]
fn fill_ratio_proxy(item_size: u32, bin_capacity: u32) -> f64 {
    (item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // smooth coupling: penalize small-but-nonzero post residual (dead space)
    let dead = (1.0 - pr_norm).exp() - 0.9;
    score += 12.0 * dead * (1.0 + progress);

    // reward tight fits with lookahead compatibility
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (pr - nxt).abs() / cap;
        score -= 8.0 * (-4.0 * compat).exp();
        if nxt <= pr {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // spread penalty vs mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // new-bin candidate: mildly discourage unless residuals are tight
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // smooth polynomial progress interaction
    score -= 3.0 * progress * pr_norm * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it cannot fit even the smallest plausible item.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Dead space penalty grows sharply as the gap shrinks (quadratic).
        let gap = (dead_threshold - post_residual) as f64;
        score += 40.0 + gap * gap * 0.8;
    }

    // Perfect fit bonus: strongly favor bins that are exactly filled.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item when it fits exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize placements that strand a gap too small for the next item
    // while the next item is itself small (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // no open bin offers a decent fit. Penalize the fresh bin mildly,
    // but relax the penalty when mean residual is already tight.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 18.0 * (1.0 - tightness) + 6.0;
    }

    // Slight preference for bins with below-average residual
    // (pack into nearly-full bins first).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit: huge reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);

        // Perfect chain: next item fills this bin exactly
        if post_residual == next_item_size {
            score -= 120.0;
        }

        // Penalize leaving dead space that next item cannot use
        if post_residual > 0 && next_item_size > post_residual {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer filling existing bins as much as possible
        score -= 60.0 * tightness;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should be discouraged
    // unless current residuals are large and the item is big (poor fit elsewhere)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / bin_capacity as f64;
        score += 80.0;                       // base penalty for new bin
        score -= 60.0 * waste_pressure;      // easier to justify when open bins are full
        score -= 30.0 * progress;            // slightly cheaper to open bins early (more future use)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;                   // new bin can also host the next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0;                  // no alternative: new bin is fine
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // New-bin candidate branch
    if bin_residual == bin_capacity {
        // Base cost: residual left in a fresh bin equals capacity - item.
        score = (bin_capacity - item_size) as f64 + 1.0;
        // If no open bin fits, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If exactly one open bin fits and it is a last chance, prefer using it
        // unless its post-fit residual would be badly fragmented.
        if fitting_bins_count == 1 {
            score += 15.0;
        }
        // If mean residual across open bins is large, reuse is cheap; penalize opening.
        if mean_residual > item {
            score += (mean_residual - item) * 0.5;
        }
        // Late in the stream, closing out existing space matters more.
        score += t * 6.0;
        // If the next item would fit perfectly in the fresh residual, mild bonus.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 4.0;
        }
    } else {
        // Dead-space penalty: residuals too small for the minimum item size are waste.
        if post_residual > 0 && post_residual < 10 {
            score += 60.0;
        }
        // Lookahead coupling: reward when the next item also fits this bin.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0;
            } else {
                score += (next_item_size as f64 - post_residual as f64) * 0.4;
            }
        }
        // Last-chance discount: if this is the only bin that fits, using it
        // avoids opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Tightness reward scaled by stream progress: prefer filling bins snugly
        // as the horizon advances.
        score -= (item / cap) * 8.0 * (0.5 + t);
        // Slight preference for bins whose residual deviates below the mean
        // (consolidating fragmentation).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let mut score = post_residual as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = r * r * (1.0 + progress) - r * progress * (1.0 - progress);
    score += 40.0 * poly;
    // Reward tight fits, scaled smoothly by progress
    score -= 30.0 * (1.0 - r) * (1.0 - r) * (1.0 + 0.5 * progress);
    // Penalize wasted space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).abs();
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - r);
    }
    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let fits_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 15.0 * fits_next * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        score += 10.0 * (1.0 - fits_next) * r;
    }
    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * r;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: small leftovers (dead space) are bad
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Penalize leftovers in "dead zone": too small to fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..10 classes
    score += (10 - class) as f64 * 0.5; // prefer larger leftover classes slightly

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill;
        } else {
            // next item won't fit here: mild penalty scaled by wasted potential
            score += 15.0 * ((next_item_size - post_residual) as f64 / cap_f);
        }
    }

    // Last chance: only this bin can fit the item -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would leave a very awkward leftover AND item is large
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish baseline; make it unattractive unless item huge
        score += 30.0;
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 600.0; // must open new bin
        }
        // opening fresh is decent if item is large and would leave small residue
        let pr = bin_capacity - item_size;
        if pr <= 5 && fitting_bins_count > 0 {
            score -= 250.0;
        }
    }

    // Progress-based modulation: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - frac);

    // Prefer bins below mean residual (tighter bins) to keep slack bins flexible
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Modulo coupling: leftovers that are multiples of common item sizes (10,20,25,50)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure on number of open bins: prefer reusing existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use
        score += 10.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score -= 15.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits: reward exact/tight matches.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward for near-perfect chain (post_residual == next_item_size).
            if gap < 1.0 {
                score -= 12.0;
            }
        } else {
            // Next item does NOT fit: penalize leaving a dead residual smaller than next item.
            let dead = post_residual as f64;
            score += 6.0 * (dead / nxt);
            // But if this bin becomes exactly full, that's ideal (no dead space).
            if post_residual == 0 {
                score -= 25.0;
            }
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Penalize bins far from mean residual (avoid fragmenting average space).
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when item is large or no good fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 22.0;
        }
    }

    // Mild preference to keep many small open bins consolidated early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: only one bin fits the item; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, to keep options open.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize blocking the next item.
            score += 6.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Time-horizon scaling: early in the stream, be more conservative with
    // opening new bins; late in the stream, tight fits matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin gets baseline cost, adjusted by
    // global state (few open bins / early stream -> cheaper to open).
    if bin_residual == bin_capacity {
        let open_cost = 30.0
            - 20.0 * (1.0 - progress)
            - 3.0 * (open_bins_count as f64).min(10.0).ln().max(0.0);
        // If no open bin fits well, opening is attractive; if this bin is a
        // last chance, opening is discouraged.
        if fitting_bins_count == 1 {
            score + open_cost + 60.0
        } else {
            score + open_cost
        }
    } else {
        // Prefer bins with residual below the mean (consolidate space).
        score += 0.5 * ((bin_residual as f64) - mean_residual);

        // Slight preference to fill already-open bins vs. proliferating bins.
        score -= 1.0 * (open_bins_count as f64).min(20.0) * 0.5 * (1.0 - progress);

        score
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t * t + 0.4 * t * t * t;
    score += 12.0 * norm_pr * norm_pr * poly;

    // Penalize waste relative to mean residual state
    let dev = pr as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + t);

    // Last-chance bin: strong penalty for opening new bin late
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.3 + 0.7 * t);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - t * 0.5);
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize dead space smoothly
        score += 3.0 * norm_pr * (1.0 + t);
    }

    // Mild penalty for proliferating open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: keep it neutral-to-slightly-high unless very late
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 quantizes "dead space quality"
    let dead_class = post_residual % 10;
    // Residuals that are multiples of 5 or small (<10) are more reusable
    if dead_class == 0 {
        score -= 6.0;
    } else if dead_class == 5 {
        score -= 3.0;
    } else if post_residual < 10 {
        score -= 8.0; // nearly perfect fit
    } else {
        score += dead_class as f64 * 0.4; // awkward remainder penalized
    }

    // Integer-division thresholds: how many "typical small items" (<=10) fit
    let small_slots = post_residual / 10;
    score -= small_slots as f64 * 1.5;

    // Lookahead: does next item fit exactly or partially in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 4.0;
            let leftover = post_residual - next_item_size;
            if leftover % 10 == 0 { score -= 2.0; }
            score += leftover as f64 * 0.05;
        } else {
            score += 2.0; // next item won't chain here
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.3;
        score += 20.0 + pressure - progress * 5.0;
        if item_size >= 60 { score -= 10.0; } // big items tolerate fresh bins
    }

    // Coupling with mean residual: bins far from mean get mild normalization
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Fraction-of-capacity harmonic penalty: post_residual near half capacity is wasteful
    let frac = post_residual as f64 / bin_capacity as f64;
    if (frac - 0.5).abs() < 0.05 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 200.0;
        return score;
    }

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste — heavy penalty proportional to their tightness.
    if post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    } else {
        // Usable gap: reward proportional to how well the next item could slot in.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // gap remains useful for the lookahead item
        } else if next_item_size > 0 {
            // gap smaller than next item: partially dead
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // residual is already poor; encourage closing out crowded states.
    let open_pressure = open_bins_count as f64 * 0.6;
    score += open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter-than-average bins get used up first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, be more tolerant of imperfect fits to avoid
    // spawning extra bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Brand-new bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual).
    if bin_residual == bin_capacity {
        score += 25.0 - (item_size as f64).max(mean_residual).min(100.0) * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (low post_residual), already in base score.

    // Aggressive 2-step lookahead: reward bins whose post_residual can host
    // the next item (chain packing), penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish -> strong reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (-slack as f64 / 10.0).exp();
        } else {
            // Near miss: penalize dead space that blocks the next item,
            // scaled by how close it was to fitting.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (-miss / 6.0).exp();
        }
        // If the next item fits with zero slack, that's a perfect chain.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 2.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are more
    // valuable to fill completely; looser bins are better targets.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the fit into this bin would leave large unusable residue.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of opening a new bin.
        score += 20.0;
        // More willing to open new bins when many bins are open and
        // current fit is poor (large post_residual).
        score += 0.05 * open_bins_count as f64;
        if post_residual as f64 > mean_residual + 15.0 {
            score -= 15.0; // poor fit elsewhere -> new bin wins
        }
        score -= 5.0 * (1.0 - progress); // early stream: new bins cheap
    }

    // Discard tiny residues as dead space (unusable for items >= 1... but
    // sizes can be small; treat residue < 10 as near-waste).
    if post_residual < 10 {
        score -= 8.0; // finishing a bin is good
    } else if post_residual > 60 {
        score += 3.0; // leaving a big hole is wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed.
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Penalize small post-residuals only mildly when they are "dead" (unusable)
    // relative to typical item sizes; usable leftover space is rewarded.
    let usable = if post_residual >= 10 { 1.0 } else { (post_residual as f64) / 10.0 };
    score -= usable * 6.0;

    // Reward tight fits: small waste relative to bin capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 25.0;

    // Last-chance bins: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 14.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Post-residual too small for next item: penalize if it's dead space.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    } else {
        // Last item in stream: minimize leftover waste aggressively.
        score += waste_ratio * 30.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than spreading.
    let spread = mean_residual - post_residual as f64;
    if spread > 0.0 {
        score += spread * 0.35;
    }

    // Dynamic time horizon: early in the stream, keep flexibility
    // (penalize very small leftovers less, prefer balanced residual);
    // late in the stream, pack tightly.
    let horizon = (1.0 - t).clamp(0.0, 1.0);
    score += horizon * (post_residual as f64) * 0.12;

    // Discourage opening new bins when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 10.0 + open_pressure * 2.0;
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += snug * snug * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * progress * 2.0;
    score += 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: strongly favor this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post residual (smooth reward)
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let slack = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 20.0 * fits_next * (1.0 - slack) * (0.6 + 0.4 * progress);
    }

    // Mild penalty for many open bins to encourage consolidation early
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    // New-bin candidate: penalize lightly so it wins only on poor fits
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 120.0 * tight * tight;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class: post_residual divisible by common item sizes is reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse = 0.0;
        if pr % 10 == 0 { reuse += 15.0; }
        if pr % 20 == 0 { reuse += 10.0; }
        if pr % 25 == 0 { reuse += 8.0; }
        if pr % 50 == 0 { reuse += 12.0; }
        // Integer-division thresholds: residual in "usable" bands.
        let band = pr / 10; // 0..=10
        if band >= 1 && band <= 3 { reuse += 5.0; } // small dead space bands
        score -= reuse;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        if slack == 0 { score -= 60.0; }
    } else if next_item_size > pr {
        // Next item cannot use this residual: penalize wasted space proportionally.
        score += 0.15 * pr as f64;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream and when
    // open bins with decent residual exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0 + 60.0 * progress;
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0;
        }
        // If the item is large, a fresh bin is more acceptable.
        score -= 0.3 * item_size as f64;
    }

    // Mild penalty for spreading many bins with large residuals.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving room for the lookahead item if it fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // blocking the next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize creating additional bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But allow a new bin if all fits would create dead space.
        if post_residual == bin_capacity - item_size && (bin_capacity - item_size) < 10 && fitting_bins_count >= 1 {
            score -= 55.0;
        }
    }

    // Mild preference for tighter bins relative to the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 0.35 * post_residual as f64;
    }

    // Tight fits are good: minimize post_residual relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Prefer bins with residual below mean residual (compact the waste).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Late in the stream, consolidation matters more: penalize leaving
    // large residuals that likely go unused.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * tightness;

    // New-bin candidate: only attractive when existing fits are terrible
    // (item leaves big unusable gap in every open bin).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward perfect fill.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 + 10.0 * chain_fit;
    }
    // Penalize placements that leave residual just below the next item size (blocking).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: make empty bins attractive only when current bins
    // would be badly fragmented or this is a large item with a large next item.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= 100;
    if is_new_bin {
        // Baseline cost of opening a bin: moderately high, reduced late in stream
        // or when many bins are open (consolidation pressure).
        let mut open_cost = 45.0;
        open_cost -= 20.0 * progress;
        if open_bins_count > 3 {
            open_cost -= (open_bins_count as f64 - 3.0).min(5.0) * 3.0;
        }
        // Big items with big lookahead favor fresh bins.
        if item_size > bin_capacity / 2 && next_item_size > bin_capacity / 3 {
            open_cost -= 20.0;
        }
        // If mean residual across open bins is high, opening a new bin is wasteful.
        open_cost += mean_residual * 0.3;
        score = open_cost + score.min(0.0) * 0.0 + post_residual as f64 * 0.5;
    }

    // Prefer bins below mean residual (pack fuller bins tighter, keep loose bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild penalty for very loose fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio < 0.5 {
        score += (0.5 - fit_ratio) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer tight fits (small post_residual), with a convex penalty
    let mut score = pr * pr / cap + pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheaper; late, waste is heavily penalized.
    let progress_weight = 1.0 + 3.0 * t * t + 2.0 * t;
    score += (pr / cap) * (pr / cap) * progress_weight * cap * 0.5;

    // Last-chance bonus: strongly reward using a bin when few alternatives exist.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * t;
    }

    // Mild penalty for spreading across many open bins when residuals are high.
    score += 0.5 * open * (mean_residual / cap) * (mean_residual / cap);

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * gap / cap * 0.3;
        // Perfect lookahead fit reward (smooth, non-piecewise)
        score -= 10.0 * (-gap * gap / 50.0).exp();
    }

    // New-bin candidate: encourage opening a fresh bin when it fits well
    // relative to current average fill, especially early in the stream.
    if bin_residual == bin_capacity {
        score = pr * 0.6 + 5.0 * t * t;
        score -= 15.0 * (1.0 - t);
    }

    // Slight reward for bins already tightly packed (low residual relative to mean).
    score -= 10.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space value by residue class mod 10.
    let class = post_residual % 10;
    let dead_penalty: f64 = match class {
        0 => -40.0,               // perfectly reusable residual
        1..=3 => 6.0,             // small sliver, low utility
        4..=6 => -8.0,            // mid class, decent utility
        7..=9 => 2.0,             // awkward class
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: residual >= 50 means half-full utility remains.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 12.0;
    } else if post_residual >= bin_capacity / 4 {
        score += 4.0;
    } else {
        score += 15.0; // near-dead bin
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Harmonic pairing: post_residual % 10 == next_item_size % 10 bonus
            if post_residual % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin pressure: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0;
    }

    // Mean residual alignment: bins deviating below mean are less valuable.
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    // Slight preference for opening new bins early in the stream when many bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score = 40.0 + 30.0 * progress - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Mid-range awkward gaps (10..20) mildly penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits (wasted potential).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (10.0 + progress * 20.0)).min(3.0);
    score += 6.0 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * pressure - (bin_residual - item_size) as f64 * 0.3;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward a perfect chain (item + next item fills bin) ---
    if next_item_size > 0 {
        let chain = post_residual as i64 - next_item_size as i64;
        if chain == 0 {
            // Perfect 2-item fill: extremely desirable
            score -= 60.0;
        } else if chain > 0 && chain <= 20 {
            // Next item fits with modest slack left
            score -= 25.0 - (chain as f64) * 0.8;
        } else if chain < 0 {
            // Next item won't fit here; dead space likely
            score += (-chain as f64) * 0.35;
        }
    } else {
        // Last item: minimize post_residual directly (already the base)
        score -= 10.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual below the mean are "well used"; prefer filling them.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= 0.6 * (mean_residual - res_f);
    } else {
        score += 0.3 * (res_f - mean_residual);
    }

    // --- Tight fit reward ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness * tightness;

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is large relative
        // to capacity (poor fit elsewhere) or nothing else fits well.
        let big_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        } else if big_item > 0.6 && next_item_size > post_residual {
            score -= 5.0; // large item, poor chaining prospects elsewhere
        } else {
            // Discourage wasting fresh capacity when fits exist
            score += 30.0 + 40.0 * (1.0 - big_item);
        }
    }

    // --- Small dead-space penalty for very small leftovers ---
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // --- Mild stream-progression pressure: consolidate early, tighten late ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is hard to reuse (post_residual in awkward band).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: reward if the post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (bin consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor low post_residual less aggressively); late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * fit_ratio;
    score += progress * 0.02 * post_residual as f64;

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced if the item is large (less wasteful).
        let base = 10.0 - 0.05 * item_size as f64;
        // If existing bins are fragmented (high mean residual spread), opening is cheaper.
        score = base + post_residual as f64 * 0.3
            - if fitting_bins_count <= 1 { 6.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // 0..1 normalized post residual
    let norm_fit = (item_size as f64) / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, prefer tight fills less aggressively; later, reward tight fills strongly.
    let tightness = 1.0 - norm_pr; // how full the bin becomes
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= tightness * tightness * 30.0 * (0.4 + 0.6 * progress_weight);

    // Penalize dead space that is too small to be useful (non-linear quadratic trough)
    let useless = if norm_pr < 0.1 { (0.1 - norm_pr) * (0.1 - norm_pr) } else { 0.0 };
    score += useless * 200.0;

    // Reward leaving room for the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let fit_next = ((norm_pr - nx).max(0.0)) / cap;
        score -= fit_next * fit_next * 40.0 * (1.0 - progress_weight);
        // penalize if post residual barely misses next item (smooth hinge squared)
        let miss = (nx - norm_pr).max(0.0);
        score += miss * miss * 60.0;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress_weight;
    }

    // Mild penalty when bin deviates from mean residual (smooth variance term)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: keep it moderately unattractive unless residuals are all tight
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * (1.0 - progress_weight) - 20.0 * (mean_residual / cap);
    }

    // Slight preference to fill larger items into tighter bins (coupling with item size)
    score += norm_fit * (1.0 - tightness) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space classes: residuals <=10 are nearly unusable (min item 10) -> big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 40 {
        score += 6.0;
    }

    // Harmonic class of post_residual: penalize residuals in awkward modulo bands.
    let pr_class = post_residual % 25;
    if pr_class >= 21 {
        score += 8.0; // awkward sliver
    } else if pr_class <= 4 && post_residual > 0 {
        score -= 5.0; // near-perfect class
    }

    // Lookahead: if next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use leftover: penalize proportionally to wasted fraction
        score += 0.3 * (post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when stream is early or open bins are full-ish.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score += 40.0 * pressure - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Prefer tighter bins overall (best-fit coupling with mean residual).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for hoarding too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable dead space after placement.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // If the next item would fit exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    }
    // Penalize if next item cannot fit in post residual but could fit an empty bin.
    if next_item_size > post_residual && next_item_size <= bin_capacity {
        score += 8.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 1.5 * open_bins_count as f64;

    // Slightly favor bins whose residual is above average (keeps big gaps alive).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to residuals) or item is huge.
    if bin_residual == bin_capacity {
        if item_size > 55 || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward a perfect chain fit
    // (item placed, then next item exactly fills post_residual).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Reward if next item fits into post_residual (chain continues).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }
    // Penalize very small unusable post_residual (wasted slack).
    if post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins with residual below mean (tighter bins first),
    // keeping loose bins available for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin early in the
    // stream; relax later when fragmentation dominates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 25.0 * progress;
        // If next item is small, a fresh bin is fine.
        if next_item_size <= 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Dead-space penalty for residuals too small to hold typical items
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: penalize opening new bins when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * open_bins_count.max(1) as f64);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        if poor_fit && mean_residual < item_size as f64 {
            score -= 20.0 + 10.0 * (1.0 - crowded);
        } else {
            score += 60.0;
        }
    }

    // Time horizon: early in the stream, be conservative with open bins; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (rebalance toward filling emptier bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild penalty for opening many bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Smooth polynomial coupling: base fit term, quadratic waste penalty,
    // and progress-modulated cubic shaping of the post-residual.
    let mut score = pr;

    // Quadratic waste penalty scaled by stream progress.
    score += (norm_pr * norm_pr) * cap * (0.5 + progress);

    // Cubic interaction between fit ratio and normalized post-residual.
    score -= fit * norm_pr * cap * (1.0 - norm_pr) * (1.0 + progress);

    // Reward tight fits more as the stream progresses (fewer wasted chances).
    score -= fit * cap * (0.2 + 0.8 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + progress);
    }

    // Dead-space avoidance: penalize residuals that no plausible item can use.
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += dead * dead * cap * 2.0;

    // Slight preference for bins deviating below mean residual (balance load).
    score += (mean_residual - pr) * 0.05;

    // Mild penalty for scattering across many open bins late in the stream.
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes mod 10.
    let class = post_residual % 10;
    // Residue classes 1..9 leave a gap that only tiny items can fill; penalize them
    // proportionally to how "lonely" the class is (odd classes are worst).
    let class_penalty: f64 = match class {
        0 => -6.0,                    // perfectly harmonic residual
        5 => -2.0,                    // half-class: many items fit
        2 | 4 | 6 | 8 => -1.0,        // even classes: decent fill odds
        _ => (class as f64) * 0.6,    // odd classes 1,3,7,9: hard-to-fill gaps
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: how many "average" slots remain.
    let slots = post_residual / 25;
    score -= (slots as f64) * 2.5;

    // Coupling with next item (lookahead k=2): if the next item fits harmonically
    // into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_class = (post_residual - next_item_size) % 10;
        if next_class == 0 {
            score -= 8.0; // perfect chaining fit
        } else if next_class <= 4 {
            score -= 3.0;
        } else {
            score += 2.0; // next item would strand odd residue
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover; leftover is likely dead space.
        score += (post_residual as f64) * 0.15;
    }

    // Capacity fraction logic: residual as fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 4.0; // nearly closed bin: excellent
    } else if frac > 0.6 && fitting_bins_count > 1 {
        score += 5.0; // wasting a large residual when other bins fit too
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residual would be tiny anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when nothing fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish base; add pressure as open bins grow so we consolidate.
        score += 12.0 + (open_bins_count as f64) * 0.5;
        // If item is large relative to capacity, opening fresh is fine.
        score -= (item_size as f64) * 0.05;
        // Late in the stream, prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild tie-breaking toward compacting global state.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving gaps that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving a gap exactly usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: prefer filling the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Favor bins tighter than average (best-fit style).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.4 * slack; // penalize leftover after next item
        } else {
            // next item won't fit here; penalize small unusable post_residual
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0 * (10.0 - dead);
            }
        }
    } else {
        // last item: just minimize waste
        score += 5.0 * tightness;
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidate fuller bins)
    score += 3.0 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if post_residual would be tiny waste anyway
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Late in stream: discourage opening bins, prefer filling existing ones
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Slight penalty for many open bins already (fragmentation control)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next < 10 {
                score -= 6.0; // perfect pair packing
            }
        } else {
            // post residual cannot host next item: mild penalty scaled by waste
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, consolidate aggressively into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Prefer filling bins with below-average residual (balance bin usage)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with the number of open bins, but is relaxed when current bin is a bad fit
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if post_residual > 50 { 0.0 } else { 15.0 };
        score = 40.0 + 2.0 * open_bins_count as f64 + poor_fit_penalty - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 12.0; // big next item: fresh bin may be wise
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: reward tight fits (low post_residual), with non-linear shaping
    let mut score = pr as f64;
    score -= 0.35 * cap * (1.0 - (1.0 - x) * (1.0 - x)); // smooth preference for small x
    score += 12.0 * x * x * x; // penalize large dead space non-linearly

    // Progress coupling: early on, tolerate waste (many items remain); late, pack tight
    let p2 = progress * progress;
    score += 18.0 * x * p2;          // waste becomes more costly as stream ends
    score -= 6.0 * x * (1.0 - p2);   // early stream: slight reward for spreading

    // Lookahead: if next item fits the post-residual, strongly reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = next_item_size as f64 / pr;
        score -= 10.0 * (1.0 - (fit_ratio - 1.0) * (fit_ratio - 1.0)) * (0.5 + 0.5 * progress);
    }
    // If next item is close to fitting, mild bonus
    if next_item_size > 0 && pr > 0.0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score -= 2.0 * (1.0 - gap / 10.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into existing bins
    let obn = open_bins_count as f64;
    score += 0.5 * obn * x; // more open bins -> penalize leaving residual behind

    // Mean-residual coupling: if this bin's residual is below mean, it's a tight bin; prefer using it
    let diff = (mean_residual - pr) / cap;
    score -= 5.0 * diff * (1.0 - 0.5 * progress);

    // New-bin candidate: penalize so we only open when existing bins are truly bad
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * progress + 0.3 * obn;
        // but if item is large relative to mean residual, opening is less penalized
        score -= 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (residuals that many item sizes can still fill), penalize dead-space classes.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fill: strongly reward.
        score -= 1000.0;
    } else {
        // Class via integer division: small residuals are hard to fill later.
        let class = pr / 10; // 0..=10 harmonic buckets
        let class_penalty = match class {
            0 => 60.0,                 // 1..9: nearly dead space
            1 => 35.0,                 // 10..19
            2 => 18.0,                 // 20..29
            3 => 8.0,                  // 30..39
            4 => 3.0,                  // 40..49
            _ => 0.0,                  // >=50: still broadly usable
        };
        score += class_penalty;

        // Modulo-10 harmonic: residuals that are multiples of 10 pair cleanly
        // with the min item size (1..100 stream), reward them slightly.
        if pr % 10 == 0 {
            score -= 5.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // Reward proportional to how tight the follow-up fit is.
            score -= (40.0_f64 * (1.0 - slack as f64 / 50.0)).max(0.0);
        } else {
            // Next item won't fit here: mild penalty, this bin likely closes.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size).min(30) as f64;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // unless current bin would leave large dead space.
    if bin_residual == bin_capacity {
        // New empty bin baseline: post_residual = capacity - item_size.
        // Make new bins attractive only for small items / when bins are fragmented.
        let fragmentation = (mean_residual - bin_capacity as f64 / 2.0).abs();
        score += 30.0 + fragmentation * 0.5;
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    // Late in the stream, prefer tightening existing bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are costly.
    // Treat post_residual <= 10 (min item size) as fully wasted space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0; // unusable sliver: heavy penalty
    } else {
        // Usable leftover: mild reward for larger usable residual, but prefer tight fits.
        score -= 8.0;
        score += (post_residual as f64) * 0.15;
    }

    // Exact-fit style reward scaled by how much of the bin was consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // Candidate new bin: base cost plus pressure from existing open bins.
        score += 30.0 + open_bins_count as f64 * 3.0;
        // A new bin is acceptable if the item is large (little fragmentation risk).
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // If next item would fit in the new bin's future residual, slight bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Slight preference for bins whose residual is close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0; // enables a near-perfect follow-up fit
        }
    }

    // Late-stream tightening: as the stream progresses, be more conservative with
    // residual waste since future compensation opportunities diminish.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * lookahead_gap;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain: place here
        }
        // Penalize residuals too small for the next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 + 0.4 * mean_residual;
    }

    // Mild tie-breaking: prefer bins tighter than the mean (denser packing)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Progress scaling: later in the stream, be greedier about small residuals
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 {
            if (next_item_size as u32) > post_residual {
                score += 0.35 * dead; // lookahead item cannot use this leftover
            } else {
                score -= 0.25 * dead; // leftover reusable by next item
            }
        } else {
            score += 0.10 * dead; // last item: leftover is pure waste
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize mildly, but allow it when existing bins fit poorly
    // (large post_residual) or when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let poor_fit_elsewhere = (post_residual as f64 - mean_residual).abs();
        score += 8.0 - 12.0 * frag - 0.05 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity / 2 {
            score -= 3.0; // fresh bin preserves room for medium next item
        }
        let _ = poor_fit_elsewhere;
    }

    // Time-horizon coupling: early in the stream, be frugal with new bins;
    // late in the stream, consolidate into existing residual aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - tightness);

    // Global fragmentation pressure: if mean residual is small, waste hurts more.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * mean_residual.min(50.0);

    // Slight preference for bins whose residual exceeds item size with margin,
    // keeping bins usable for a range of future sizes.
    if bin_residual > item_size {
        let margin = (bin_residual - item_size) as f64;
        score -= 0.05 * margin.min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to stream progress.
    let mut score = r * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial penalty on normalized residual: mid-range residuals are wasteful.
    score += 12.0 * rn * (1.0 - rn) * (1.0 + progress);

    // Reward tight fits more as the stream progresses (quartic coupling).
    let tightness = 1.0 - rn;
    score -= 6.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > r {
            score += 4.0 * (1.0 + progress);
        } else {
            // Reward leaving a residual that perfectly accommodates the next item.
            let fit = 1.0 - ((r - nxt) / cap);
            score -= 5.0 * fit * fit;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it moderately attractive only early or for big items.
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress) + 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: exact-fill reward via modulo structure.
    if post_residual == 0 {
        score -= 60.0; // perfect fill, best possible outcome
    } else {
        // Residual class buckets: small dead space is tolerable, mid-range waste is bad.
        let class = post_residual / 10; // integer division harmonic class 0..10
        score += match class {
            0 => 2.0,
            1 => 5.0,
            2 => 12.0,
            3 => 18.0,
            4 => 22.0,
            5 => 25.0,
            6 => 22.0,
            7 => 18.0,
            8 => 12.0,
            9 => 6.0,
            _ => 0.0,
        };
        // Exact divisibility harmony: residual divisible by common item classes
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 5 == 0 { score -= 3.0; }
    }

    // Lookahead harmony: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin -> reward, stronger for tight chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / cap);
            if post_residual % next_item_size.max(1) == 0 { score -= 4.0; }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally
            let waste_frac = 1.0 - post / cap;
            score += 6.0 * waste_frac;
        }
    } else {
        // Last item: prefer minimal residual regardless
        score -= 5.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when open bins score badly.
    if bin_residual == bin_capacity {
        score = 40.0 + post; // base cost of a fresh bin
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
        if open_bins_count == 0 { score -= 45.0; }
    }

    // Mild global pressure: many open bins with high mean residual -> consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - 0.5).abs() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Reward tight-but-usable residuals, favor residuals that can still
        // hold small items (>= 10) or the lookahead item.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        if post_residual >= 10 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: keep room for the next item if this bin can.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size >= 10 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to known next item
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using a bin when few fitting alternatives exist.
    score += 0.35 * open_bins_count as f64;
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0; // last-chance bin: avoid opening a new bin
    }

    // Mean-residual coupling: prefer bins close to the mean (balanced packing).
    score += 0.10 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when current bins would waste space.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 18.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 45.0; // overriding last-chance: new bin better than bad fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 40.0; // perfect lookahead match: item + next item fill bin
        } else {
            // penalize mismatch relative to magnitude of gap
            score += (diff as f64).powf(1.3) * 0.5;
        }
        // Bonus if next item fits into post_residual at all
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Penalize creating unusable dead space (too small for smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // open new bin only if mean residual barely fits the item (wasteful fits elsewhere)
        score += 30.0 - mean_gap * 0.4;
        // if lookahead next item is huge, a fresh bin is attractive
        if next_item_size > item_size && next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) early on
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    score -= 30.0 * (-post_residual as f64 / 20.0).exp();

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 25.0; // perfect slot for lookahead item
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8; // wasted for next item
        } else {
            score += (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Reward filling bins close to capacity (residual below ~15 becomes fragile).
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 2.0;
    }

    // Global state coupling: when many bins are open, prefer consolidation;
    // when few bins are open, new-bin cost is lower.
    let openness = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 2.0 * openness;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit them); late in the stream, pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 15.0 * t; // new bins get progressively less attractive
        score += 5.0 * (mean_residual / 100.0).max(0.0);
    } else {
        score -= 10.0 * t; // late stream: favor existing bins
    }

    // Slight preference for bins whose residual deviates from the mean
    // (keep a diverse residual portfolio for future items).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr
        + 60.0 * norm_pr * norm_pr
        + 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Waste penalty: squared normalized dead space, amplified late in stream.
    let waste = 25.0 * norm_pr * norm_pr * (0.3 + 2.0 * progress * progress);

    // Tight fit reward: smooth bell around small post_residual.
    let tight = -18.0 * (-(norm_pr * 6.0)).exp();

    // Last-chance bonus: strongly prefer the only bin that fits.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -30.0
    } else {
        0.0
    };

    // Lookahead: reward if next item fits the post residual well.
    let look = if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        -12.0 * (1.0 - (fit_ratio - 1.0) * (fit_ratio - 1.0))
    } else if next_item_size > post_residual && post_residual > 0 {
        8.0
    } else {
        0.0
    };

    // New-bin candidate handling: penalize opening a new bin, more when
    // alternatives exist, but relax late when open bins are fragmented.
    let new_bin_penalty = if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        35.0 + 25.0 * (1.0 - progress) - 20.0 * frag
    } else {
        0.0
    };

    // Congestion coupling: mild reward for filling bins when many are open.
    let congestion = -3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    base + waste + tight + last_chance + look + new_bin_penalty + congestion
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // residue classes modulo 10 (common item granularity).
    let residue_class = post_residual % 10;
    // Dead-space penalty: residuals that are small but nonzero are the worst,
    // since they can rarely host future items (sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if residue_class == 0 && post_residual > 0 {
        // Perfectly divisible leftover: highly reusable, reward it.
        score -= 25.0;
    } else if residue_class <= 2 {
        score += 12.0;
    }

    // Integer-division thresholds: how many "typical" items (size 10) fit post-placement.
    let slots = post_residual / 10;
    score -= (slots as f64) * 6.0;

    // Lookahead harmonic coupling: does the next item divide the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 - snug * 0.4;
            // Harmonic bonus if next item exactly consumes the residual.
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: only prefer it when all open bins would leave
    // pathological fragments and the stream is early enough to amortize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fragment = post_residual > 0 && post_residual < 10;
        if bad_fragment || open_bins_count == 0 {
            score -= 20.0;
        } else {
            // Opening new bins late in the stream wastes capacity.
            score += 35.0 + progress * 30.0;
        }
    }

    // Mild pressure toward consolidating into few bins.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the min item size)
    // are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that is too small for the known next item
    // (dead space relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 1.5;

    // Mild pull toward bins with residual near the mean (keeps bins uniform,
    // preserves a few large-residual bins for big future items).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: only attractive when current item is large or no
    // open bin fits well; otherwise keep it out of contention.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        let no_good_fit = fitting_bins_count == 0;
        score += 35.0 - 30.0 * big_item - (if no_good_fit { 25.0 } else { 0.0 }) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear pressure.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect match: post_residual exactly fits next item -> strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: any residual is dead space; minimize it hard.
        score += (post_residual as f64) * 2.0;
    }

    // Relative-to-mean coupling: bins with residual near the mean are "normal" targets;
    // prefer placing into bins already below mean residual (tightening them).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave big dead space
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish base (post_residual = capacity - item_size),
        // penalize slightly so tight existing fits win.
        score += 15.0;
        if next_item_size > 0 && post_residual <= next_item_size {
            // Opening fresh bin that will exactly host next item is fine.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Late in stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space relative to capacity
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 80.0;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        // extra reward for near-exact two-item fill
        let combined = post_residual as f64 - next_item_size as f64;
        score -= (combined / bin_capacity as f64) * 40.0;
    }
    // If next item does NOT fit, mild penalty proportional to tightness kept
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).max(0.0);
    }

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: opening a new bin should be discouraged unless
    // current fit is very poor or many bins are open with little residual
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 250.0;
        // cheaper to open new bin late in stream when open bins have small residuals
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 80.0;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 150.0; // existing bins are nearly full anyway
        }
    }

    // Slight preference for filling fuller bins (smaller residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * progress)
        - 18.0 * (1.0 - norm_post).powi(3) * (1.0 + progress);

    // Reward tight fits, more so as stream progresses
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (post - ns).max(0.0) / cap;
        score += 15.0 * gap * gap;
        score -= 10.0 * (1.0 - gap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: smooth in fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 20.0 * scarcity * (1.0 - norm_post);

    // Mild penalty for spreading across many bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Encourage balanced residuals relative to mean
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (multiples of common item granularities), penalize awkward dead space.
    let pr = post_residual;
    if pr > 0 {
        let class_reward: f64 = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else {
            2.0
        };
        score += class_reward;

        // Integer-division thresholds: residual buckets
        let bucket = pr / 20; // 0..=5
        score -= bucket as f64 * 1.5;
    } else {
        // Perfect fit is ideal
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100)
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size <= pr {
            score -= 6.0 + (pr - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit here: penalize large leftover less if it's a
            // harmonic class usable by future items (multiples of 10)
            if pr % 10 == 0 { score += 1.0; } else { score += 4.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when post_residual (full capacity) is
    // harmonic and mean residual across open bins is already fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score = 8.0 + frag * 20.0 - (pr % 10 == 0) as i32 as f64 * 4.0;
        // early in stream, prefer open bins less aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Slight preference for tighter bins overall (small residual before placement)
    score += (bin_residual as f64 - item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // awkward gap (items >= 10 can fit but barely)
        }
    } else {
        score -= 40.0; // perfect closure is highly desirable
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else if post_residual > 0 && (next_item_size as u64) > (post_residual as u64) {
            score += 8.0; // next item won't fit here; dead space likely
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fill < 0.55 {
            score += 45.0; // discourage opening new bin when open bins are loose
        } else {
            score -= 5.0; // mildly encourage fresh bin when existing ones are crowded
        }
    }

    // Late-stream consolidation: as stream progresses, favor reusing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // next item fits perfectly: strong reward
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0; // exact chain completion
            }
        } else {
            // next item would NOT fit here: penalize leaving a gap smaller than next item
            score += gap * 0.8;
        }
    }

    // Penalize dead space that no typical item (min size ~ small) can use
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // tiny unusable sliver
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (keep large-residual bins flexible for larger future items)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slightly penalize so only genuinely bad fits trigger a new bin
        score += (bin_capacity as f64) * 0.5; // ~50 baseline
        // As stream progresses, opening new bins becomes cheaper (fewer future repacks)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins are open and residuals are fragmented, opening fresh is attractive
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If next item is large and post_residual here (== capacity - item) is small,
        // a fresh bin is fine since score already reflects that.
    }

    // Slight preference to fill bins that are already heavily loaded (reduce bin count)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small for any item (1..=100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the tightest (already via post_residual)
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate small leftovers)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: early in stream, be more open to new bins (keep flexibility);
    // late in stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus flexibility adjustments
        score = bin_capacity as f64 - 35.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if post_residual > 0 && post_residual < 10 {
            score += 0.0; // not applicable for empty bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0; // next item needs a fresh bin anyway
        }
        // penalize new bin if many open bins already (fragmentation)
        score += 2.0 * (open_bins_count as f64).min(15.0);
    } else if open_bins_count <= 2 && progress < 0.3 {
        // early phase with few bins: slight preference to consolidate
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic in normalized post residual modulated by progress
    score += (norm_pr * norm_pr) * (1.0 + progress) * 20.0;
    score -= norm_pr * (1.0 - progress) * 10.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 15.0;

    // Penalize dead space relative to mean residual (smooth cubic interaction)
    let dev = norm_pr - (mean_residual / cap);
    score += dev * dev * dev * 25.0;

    // Last-chance bonus (smooth exponential rather than hard switch)
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space compatible with next item (smooth Gaussian-like term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let compat = (-gap * gap / 200.0).exp();
        score -= compat * 12.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: reward tight fits non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual too small to ever be useful again.
    // Harmonic class: residuals in (0, 10) are nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: bins whose residual is a divisor-friendly
    // class (multiples of 10) remain highly reusable for typical item sizes.
    let pr = post_residual as i64;
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: classify residual into usable tiers.
    let tier = post_residual / 25; // 0: tiny, 1: quarter, 2: half, 3: three-quarter
    match tier {
        0 => score += 12.0 * (1.0 - fit_ratio),
        1 => score += 3.0,
        2 => score -= 2.0,
        _ => score -= 4.0,
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use leftover: penalize small leftover more.
            score += 6.0 * (1.0 - (next_item_size - post_residual).min(20) as f64 / 20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins normally; relax when open bins are crowded.
        score = 55.0 - 30.0 * pressure - 10.0 * progress;
        if item_size >= 50 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins with larger mean residual (consolidation).
    score -= 0.02 * mean_residual;

    // Mild tie-break: prefer fewer open bins (bin consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for any item (1..=100)
    // are pure waste; the smaller and more "stranded" the gap, the worse.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 4 {
        // Unusable micro-gap: treat as dead space, penalize heavily.
        score += 25.0;
    } else if post_residual < 10 {
        // Likely dead space for typical item distributions.
        score += 15.0;
    } else if post_residual <= 20 {
        // Small gap: mildly penalize relative to raw residual.
        score += 6.0;
    } else {
        // Usable gap: slight reward to encourage keeping usable space.
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (dead-space creating).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 20.0;
        } else {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would create dead space in every existing bin, or bins are very full.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; scaled by open bin pressure.
        let pressure = open_bins_count as f64;
        score += 45.0 + pressure * 2.0;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Lookahead: if the post residual exactly accommodates the next item,
    // reward this placement (chains a perfect second fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 6.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize new bins implicitly by rewarding tight fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    score += consolidation * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Deviation from mean residual: bins far fuller than average are good targets.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_gap / (bin_capacity as f64));
        if next_item_size == post_residual {
            score -= 50.0; // perfect 2-step chain: bin becomes exactly full next step
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual; penalize leaving awkward dead space
        score += 0.5 * (post_residual as f64);
    }

    // Penalize residuals that are likely unusable (small dead space)
    if post_residual < 10 {
        score -= 10.0; // near-full bin is good, waste is minimal
    } else if post_residual < 20 {
        score += 5.0;  // awkward sliver
    }

    // Tight fit reward relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Prefer bins below mean residual (keeps residuals balanced / preserves large gaps)
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = next_item_size == post_residual
            || (next_item_size > 0 && next_item_size <= post_residual && (post_residual - next_item_size) < 10);
        if good_fit_exists {
            score += 100.0; // keep using open bins with good fits
        } else {
            score += 25.0; // moderate penalty; allow new bin only if open bins are poor
        }
    }

    // Late in stream: consolidate harder, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 8.0;
    }
    // If next item would exactly fill post_residual, even better.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if next item cannot fit into post_residual and post_residual is dead space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 6.0;
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If item is large relative to capacity, new bin is reasonable.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If mean residual across open bins is small, a new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
    }

    // Penalize creating small unusable fragments (post_residual between 1 and 9).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Slight preference for bins with residual close to mean (balance load).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: normalized post residual, polynomially coupled with stream progress.
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = x.powi(2) * (1.0 + 2.0 * progress) + x * (1.0 - progress);

    // Penalize dead space quadratically as stream progresses (less slack tolerated late).
    score += 3.0 * progress * x * x * x;

    // Reward tight fits (small post_residual) with smooth exponential shaping.
    score -= (1.0 - x).powi(3) * 2.5 * (1.0 - progress);

    // Last-chance bin: strongly favor using it (avoid opening a new bin needlessly).
    if fitting_bins_count <= 1 && !is_new_bin {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 1.5 + 2.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Penalize leaving post_residual that can't fit the next item, worse early/mid.
        score += 1.0 * (1.0 - progress) * (pr / cap);
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    if is_new_bin {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        let mean_crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 6.0 - 4.0 * mean_crowding - 0.5 * crowd + 2.0 * progress;
        // A fresh bin is perfect if the item is large; reward proportionally.
        score -= (item_size as f64 / cap) * 3.0;
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).clamp(0.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals in "dead zones"
    // (odd / non-divisible-by-10 residuals are harder to fill later).
    let pr = post_residual;
    if pr > 0 {
        let div10 = pr % 10 == 0;
        let div5 = pr % 5 == 0;
        if div10 {
            score -= 6.0;
        } else if div5 {
            score -= 2.0;
        } else {
            score += 4.0; // odd-ish dead space penalty
        }
        // Very small unusable slivers
        if pr < 5 {
            score += 20.0;
        } else if pr < 10 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strongly reward
        score -= 40.0;
    }

    // Capacity-fraction coupling: prefer filling bins past half capacity.
    let fill_frac = 1.0 - (post_residual as f64) / cap;
    if fill_frac >= 0.5 {
        score -= 8.0 * fill_frac;
    } else {
        score += 4.0 * (0.5 - fill_frac);
    }

    // Harmonic pairing with lookahead: if next item fits exactly in post
    // residual, big reward; if next item fits at all, mild reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack.min(10.0);
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current item is huge relative
    // to all residuals or many bins already open with high mean residual.
    if bin_residual == bin_capacity {
        let huge = item_size as f64 > 0.8 * cap;
        let crowded = open_bins_count as f64 * mean_residual > 3.0 * cap;
        if huge && !crowded {
            score -= 5.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64) * 0.05 * (1.0 - progress);

    // Tie-break: prefer bins below mean residual (denser packing).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items are waste.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize post-residual that cannot fit the lookahead item in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain-friendly
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + post_residual as f64 * 0.2;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the mean residual (good fills).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild progression term: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less so early when few bins exist.
        score += 20.0 + open_bins_count as f64 * 2.0 - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Post residual can still host the next item: mild reward proportional to slack.
        score -= 6.0;
        score -= 10.0 / (1.0 + (post_residual - next_item_size) as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally to wasted gap.
        score += 8.0 + 0.35 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare post_residual against mean residual: leaving average slack is good.
    score -= 0.25 * (post_residual as f64 - mean_residual);

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += desperation
            + if next_item_size > 0 && next_item_size >= item_size { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 4.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with the least residual waste (already in base).
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global residual pressure: if mean residual is high, prefer filling bins down.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be more willing to open/keep bins flexible;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Discourage opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New-bin candidate: add penalty unless the item is large relative to capacity
        // or no open bin fits well.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - large_item);
    }

    // Mild penalty per open bin to encourage consolidation over time.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let res = bin_residual as f64;

    // Base: prefer minimal post residual, normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (quadratic in progress)
    let dead = post / cap;
    score += dead * dead * (0.5 + 2.0 * progress);

    // Reward tight fits: smooth sigmoid-like term on fill ratio
    let fill = item / res.max(1.0);
    score -= (fill * fill).tanh() * (1.0 + progress);

    // Penalize leaving residual that is small-but-unusable (smooth valley around tiny residuals)
    let tiny = (post / cap) * (1.0 - (post / cap) * 4.0).max(0.0);
    score += tiny * 0.8;

    // Last-chance bin: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.6 + 0.5 * progress;
    }

    // Interaction with mean residual: opening bins when others are packed is bad
    let mean = mean_residual / cap;
    score += (open_bins_count as f64).ln().max(0.0) * mean * 0.15;

    // Lookahead: bonus if post residual can fit next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as f64 >= nxt {
            score -= 0.4 * (1.0 - progress);
        } else {
            score += 0.15 * (1.0 - (post / nxt.max(1.0)));
        }
    }

    // New-bin candidate: neutral-ish baseline with slight progress-dependent penalty
    if bin_residual == bin_capacity {
        score = 1.0 + 0.8 * progress - 0.3 * mean;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;

    // Harmonic class of the residual: bins whose leftover is divisible by
    // small "friendly" sizes are more likely to be filled later.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // perfectly harmonic leftover (multiple of 10)
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr % 3 == 0 {
            score -= 1.5;
        } else {
            score += 2.0; // awkward leftover class
        }
    }

    // Fraction-of-capacity coupling: reward using a large fraction of the bin.
    let fill_frac = item_size as f64 / c;
    score -= fill_frac * 12.0;

    // Integer-division thresholds on post_residual.
    if pr < 10 && pr > 0 {
        score += 15.0; // dead space below the minimum item size
    } else if pr < 20 {
        score += 5.0;
    } else if pr >= 60 {
        score -= 4.0; // bin still very flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            score -= 4.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 3.0; // next item cannot follow into this bin
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer fresh bins only when existing
    // residuals are small relative to the item.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / c;
        // Open a new bin if the stream is early or open bins are tight.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 30.0 * pressure - 10.0 * progress;
        // Discourage opening a new bin for a tiny item.
        if item_size < 30 {
            score += 10.0;
        }
    }

    // Mild preference to balance against mean residual (avoid clustering
    // all waste in one bin).
    score -= 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual can still hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Open-bins pressure: penalize adding to already-open bins when many are open,
    // pushing toward opening new bins rather than fragmenting many bins.
    score += (open_bins_count as f64) * 0.15;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it mildly attractive only when current bin fits poorly.
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Penalize bins far below mean residual (relatively full bins get priority).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space that is
    // too small to be reusable is extra costly. Penalize unusable slivers.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 0.3 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (relative tightness).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
    }

    // Global state coupling: when many bins are open relative to progress,
    // encourage consolidating into existing bins (penalize new-bin option).
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty grows with number of open bins
        score += 20.0 + 2.0 * open_bins_count as f64;
        // early in the stream, opening bins is cheaper
        score -= 25.0 * (1.0 - t);
        // if next item is large, a fresh bin may be valuable
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // existing bin: reward matching the mean residual state
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // late in the stream, filling existing bins is even more valuable
        score -= 10.0 * t;
    }

    // Mild penalty for very empty existing bins being consumed by tiny items
    if item_size < 20 && bin_residual > 80 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling between post_residual and stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 25.0
                 - norm_pr * norm_pr * norm_pr * 15.0;
    score -= coupling;
    // Penalize wasted space relative to mean residual (smooth interaction)
    let mean_gap = (mean_residual - pr) / cap;
    score += mean_gap * mean_gap * 30.0 * (0.5 + progress);
    // Reward near-perfect fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 20.0;
    // Last-chance bonus
    if fitting_bins_count == 1 { score -= 35.0; }
    // Lookahead: reward residual matching next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 18.0 * (1.0 - progress);
    }
    // Mild pressure to prefer existing bins as stream progresses
    score += progress * 5.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = bin_capacity / 4;   // 25
    let fifth = bin_capacity / 5;     // 20
    let tenth = bin_capacity / 10;    // 10

    // Class bonus: post_residual in [0,10) = perfect closure (harmonic class 0)
    if post_residual < tenth {
        score -= 40.0;
    } else if post_residual < fifth {
        // class 1: small dead space, mildly good
        score -= 12.0;
    } else if post_residual < quarter {
        // class 2: moderate residual, neutral-ish
        score += 4.0;
    } else {
        // class 3: large residual left, wasteful placement of a small item
        score += 18.0;
    }

    // Exact fill: harmonic ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain into this bin: strong reward, scaled by fit tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.2 * tight;
        } else {
            // next item won't fit here: penalize leaving awkward mid-range gaps
            let gap_class = (post_residual / (tenth.max(1))) as u32;
            if gap_class >= 1 && gap_class <= 3 {
                score += 10.0; // unusable-for-next dead space in 10..40 range
            }
            // if next item exactly equals residual, it would have been perfect; missing it hurts
            if next_item_size > post_residual && post_residual >= item_size.min(next_item_size) / 2 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows with
    // how many bins are already open (discourage bin proliferation early).
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if nothing open fits well (many fitting bins means alternatives exist),
        // opening is fine; if few fitting bins and item is large, opening is attractive.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: penalize bins far from mean residual (outliers),
    // keeping residual distribution homogeneous.
    let dev = (post - mean_residual).abs();
    score += 0.08 * dev;

    // Stream progression: late in the stream, be greedier about closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post / cap);

    // Modulo harmonic classes on post_residual: residues that are multiples of
    // common item sizes (10, 20) are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps that are too small to be useful.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Semi-dead zone: small gaps rarely get filled efficiently.
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins are heavily fragmented.
        score += open_bins_count as f64 * 3.0;
        // Bonus for new bin if mean residual across open bins is very low (all tight).
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Slight preference for tighter existing bins as stream progresses.
        score += (bin_residual as f64 - post_residual as f64) * 0.0; // neutral placeholder
        score -= (bin_capacity - bin_residual) as f64 * 0.1; // favor fuller bins
    }

    // Progress-based tightening: later in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (25.0 - post_residual.min(25) as f64) * progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits; reward tightness relative to post residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit after this placement: penalize wasted potential
            score += 80.0 + 0.5 * post_residual as f64;
        }
    }

    // Prefer bins tighter than the mean residual (good fits), penalize looser bins
    let resid = post_residual as f64;
    score += 0.6 * (resid - mean_residual);

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 200.0;
        // late in the stream, opening new bins is more costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward low post_residual non-linearly.
    score -= (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize dead space that can never host typical future items.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 20.0).powi(2);
        score += dead * (1.0 - (step_index as f64 / total_items.max(1) as f64).max(0.0));
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: bonus if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + next_item_size as f64 * 0.3;
        } else if post_residual > 0 && next_item_size > post_residual {
            // penalize leaving a gap just smaller than the next item
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins below mean (tighter bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.2;

    // Time horizon: late in the stream, be more conservative with new bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - t);
        // only open a new bin if the fit elsewhere is really bad
        if post_residual < 15 { score -= 30.0; }
    }

    // Prefer exact-ish fills early, avoid wasting large residual bins.
    if item_size >= 60 && post_residual <= 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * fit * fit);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheaper; later, tight packing matters more.
    let tightness = (1.0 - fit).powi(3);
    score -= 30.0 * progress * tightness * it / cap;
    score += 20.0 * (1.0 - progress) * fit * fit * cap;

    // Penalize dead space relative to mean residual (smooth quadratic).
    let dead = (pr - mean_residual).abs();
    score += 0.15 * dead * dead / cap;

    // Last-chance bin bonus (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward residual that can host the next item (smooth Gaussian-like).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        score -= 18.0 * (-8.0 * d * d).exp() * (1.0 - progress * 0.5);
        // Penalize residuals that are just barely too small for the next item.
        if pr < nx {
            score += 0.4 * (nx - pr) as f64;
        }
    }

    // New-bin candidate: prefer it only when open bins would create large waste.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        score = 60.0 + 40.0 * (1.0 - progress) - 0.5 * avg_waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: absolute best outcome.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes (mod classes) are more reusable than awkward remainders.
    let pr = post_residual as i64;
    let mut reusability = 0.0;
    for m in [10i64, 20, 25, 50, 100].iter() {
        if *m > 0 && pr % m == 0 && pr > 0 {
            reusability += 1.0;
        }
    }
    score -= reusability * 15.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Extra reward when the next item fits *snugly* (harmonic pairing).
        let slack = post_residual - next_item_size;
        let snug = if slack == 0 { 60.0 } else if slack <= 10 { 30.0 } else { 12.0 };
        score -= snug;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize small awkward gaps.
        score += 25.0;
        // Penalize modulo-misaligned gaps harder.
        if pr % 10 != 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified for large items or when no open bin
        // fits well; otherwise discourage (prefer packing into open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.5 * (bin_capacity as f64);
        if large_item {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin anyway
        }
        // Slightly discourage new bins late in the stream when open bins exist.
        if open_bins_count > 0 {
            score += 30.0 * (1.0 - progress);
        }
        // Empty-bin post_residual is exactly capacity - item; keep it neutral
        // otherwise so it competes fairly on post_residual.
    }

    // Mild tie-breaker: prefer bins with below-average residual (tighter bins),
    // keeping big residuals for future large items.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit a plausible
    // future item are heavily penalized. Small gaps (< ~15) are almost dead.
    if post_residual < 15 {
        score += 40.0 + (15 - post_residual) as f64 * 3.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small but still usable).
    if post_residual > 0 && post_residual <= 30 {
        score -= 10.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / 100.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual too small for the lookahead item: mild penalty.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is penalized implicitly by favoring
    // low post_residual more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 0.4 + mean_residual * 0.05;
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base, penalized by open-bin pressure and
        // early-stream caution (early on, packing tight is cheap).
        score = 100.0 + pressure * (1.0 - progress * 0.5);
        // If the item fits very poorly everywhere else, new bin may win:
        // handled naturally since open bins get dead-space penalties.
    } else {
        // Slight preference to use bins below mean residual (larger leftovers
        // elsewhere stay flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
        // Late in the stream, filling existing bins is even more valuable.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Favor bins where the next item leaves a small, still-usable residual.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.8 * miss.min(50.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bin is a bad fit
    // (large item, huge post residual, or item barely fits).
    if bin_residual == bin_capacity {
        let waste_if_used = (bin_capacity - item_size) as f64;
        // Prefer a fresh bin when the item would leave lots of dead space
        // and other bins are relatively full.
        let pressure = mean_residual / bin_capacity as f64;
        score += 50.0 + 0.4 * waste_if_used - 120.0 * pressure;
        // Lookahead: a new empty bin can always host the next item perfectly.
        if next_item_size > 0 && post_residual == item_size && post_residual >= next_item_size {
            score -= 40.0;
        }
        // Never open a new bin when this is a trivially good fit elsewhere.
        if item_size >= 60 && fitting_bins_count > 1 {
            score += 200.0;
        }
    }

    // Late in the stream: consolidate, avoid spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (open_bins_count as f64).powf(0.3) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0 * (10.0 - post_residual as f64);
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward for perfect chaining (post_residual exactly fits next item).
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 5.0;
        if post_residual < 5 {
            score += 15.0; // but avoid creating near-useless residue
        }
    }

    // New-bin candidate handling: an empty bin gets a moderate penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are open and fragmented, opening new bins is worse.
        score += 0.3 * open_bins_count as f64;
    }

    // Global state: when mean residual is high (bins are loose), prefer filling
    // loose bins to consolidate; when mean residual is low, tightness dominates.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: early in the stream, keep space flexible (penalize very small
    // residuals slightly more); late in the stream, just fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 20 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, damped by a smooth polynomial in progress.
    let mut score = pr * (1.0 - 0.35 * progress * progress);

    // Non-linear penalty on small residuals (dead space), coupled with progress.
    score += 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Reward tight fits: post_residual near 0 gets a smooth quadratic bonus.
    score -= 18.0 * (1.0 - norm_pr).powi(2) * norm_pr;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.6 + 0.4 * progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward it smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / cap;
        score -= 10.0 * fit_frac * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize proportionally to leftover size.
        score += 6.0 * norm_pr * (1.0 - progress);
    }

    // Mild diversification: when many bins are open, prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * norm_pr;

    // New-bin candidate: empty bin should only win when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual - pr).abs() / cap;
        score += 8.0 + 10.0 * (1.0 - frag) - 20.0 * progress * (1.0 - norm_pr);
    }

    // Mean residual alignment: prefer bins close to the mean residual (smooth coupling).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: dead space quality ---
    // Residuals that are multiples of common item sizes (10s) are "harmonic"
    // and reusable; odd remainders are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class A: post_residual divisible by 10 -> highly reusable
    if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        // penalize by how far off the nearest multiple of 10 we are
        let off = (10 - (pr % 10)) as f64;
        score += off * 1.5;
    }

    // Class B: perfect-fit detection (post_residual == 0 or tiny)
    if pr == 0 {
        score -= 40.0;
    } else if pr < 10 {
        // unusable dead space (min item is 10 in classic setting, but sizes 1..100 allowed)
        score += 8.0;
    }

    // --- Coupling with next item: lookahead fit quality ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, weighted by tightness
            let tightness = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 10.0 + 15.0 * tightness;
            // extra reward if next item lands post_residual exactly at a multiple of 10
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot follow here: penalize proportional to overshoot
            let over = (next_item_size - pr) as f64;
            score += 0.3 * over.min(60.0);
        }
    }

    // --- Integer-division thresholds on item_size (size classes) ---
    let size_class = item_size / 10; // 0..10
    match size_class {
        0 | 1 => score -= 3.0,      // tiny items: easy to place anywhere, mild preference
        7 | 8 => score += 4.0,      // big items: prefer fresher bins, penalize tight ones
        _ => {}
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // this is the only bin that fits: avoid opening a new bin
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost. Attractive when open bins fit poorly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening cost grows slightly over stream (sunk bins already paid)
        score = 55.0 - 10.0 * progress;
        // Prefer opening a new bin for large items with poor harmonic fit elsewhere
        if item_size > 60 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0; // room for lookahead in fresh bin
        }
        return score;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter fills) ---
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 4.0 * (mean_residual - res_f) / cap;
    } else {
        score += 3.0 * (res_f - mean_residual) / cap;
    }

    // --- Congestion pressure: many open bins -> consolidate ---
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1) can
    // plausibly use are heavily penalized; tiny unusable slivers are worst.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead <= 10.0 {
            score += 40.0 * (11.0 - dead); // sliver penalty, up to ~400
        } else if dead <= 20.0 {
            score += 8.0 * (21.0 - dead); // small-gap penalty
        } else {
            score += 0.05 * dead; // mild pressure toward tighter fits
        }
    } else {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Reward using a bin whose residual closely matches the item (low waste).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // New-bin candidate: attractive only if it enables a good future fit
        // with the lookahead item (e.g. next item exactly fills leftover).
        if next_item_size > 0 {
            let pair_waste = (post_residual as i64 - next_item_size as i64).abs();
            if pair_waste <= 5 {
                score -= 90.0; // item + next item pack perfectly here
            } else {
                score += 25.0 + 2.0 * open_bins_count as f64;
            }
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Placing here leaves exactly the room the next item needs.
        score -= 100.0;
    }

    // Mild global pressure: fewer open bins is better late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin {
        score -= 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Tie-break toward bins with residual near the mean (balanced packing).
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly or nearly fits the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact 2-step fill is the best possible outcome.
            if slack == 0.0 {
                score -= 60.0;
            } else {
                // Reward decays quadratically with leftover-after-next slack.
                score -= 40.0 * (1.0 - slack / bin_capacity as f64).powi(3);
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much of the next item is left stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.25 * stranded;
        }
    } else {
        // Last item: prefer tightest final fill.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than average behind is good (compact packing).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Dead-space penalty: tiny post_residual that no future item (min size 1,
    // typically >=10) can use is wasted capacity.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins are badly fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slightly discourage early in the stream
        // and when many bins are already open (consolidation is preferred).
        score = 55.0 + 0.1 * open_bins_count as f64
            + 20.0 * (step_index as f64 / total_items.max(1) as f64).powi(2);
        // If the next item is large, an empty bin is more attractive.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially when it nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual < 10 {
        score -= 25.0 * fill_ratio;
    } else if post_residual < 30 {
        score -= 8.0 * fill_ratio;
    }

    // Penalize dead space that no future item (min size 1..10 typical) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver is wasted
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * use_ratio;
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more selective (prefer tight fits);
    // late in the stream, just fill anything reasonable.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 4 && mean_residual > 40.0 {
        score -= 5.0;
    }
    // Few open bins and low mean residual -> opening a new bin is less costly.
    if open_bins_count <= 2 && mean_residual < 20.0 {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin should win only when fit is bad elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * item_size as f64;
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let item_n = item_size as f64 / cap;
    let mean_rn = mean_residual / cap;

    // Base: reward tight fits (low post residual), scaled non-linearly by stream progress.
    let mut score = prn * (1.0 + 0.8 * progress * prn) * 100.0;

    // Non-linear coupling: post residual squared penalty for large dead space.
    score += 30.0 * prn * prn * (0.5 + progress);

    // Reward using bins whose residual is close to the item (smooth gaussian-like fit term).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 40.0 * (-fit_gap * fit_gap * 8.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidates slightly more as stream progresses (consolidate late).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 12.0 + 20.0 * progress + 5.0 * (open_bins_count as f64).ln();
        // But allow new bin if item is large relative to mean residual (poor fits elsewhere).
        if item_n > mean_rn * 1.4 {
            score -= 25.0 * (item_n - mean_rn * 1.4);
        }
    }

    // Lookahead: penalize leaving residual that fits next item poorly (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (prn - nxt).abs();
        score += 15.0 * gap * gap - 10.0 * (-gap * gap * 20.0).exp();
    }

    // Mild open-bin consolidation pressure.
    score += 0.5 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals that lie in "useful" residue classes.
    // Small post-residuals are good; multiples of common item-size classes are reusable.
    let pr = post_residual;
    if pr > 0 {
        // class of pr modulo 10: residues near 0 (10,20,...) are highly reusable
        let m = (pr % 10) as f64;
        score -= (10.0 - m) * 0.35; // residues divisible by 10 get biggest bonus
        if pr % 20 == 0 {
            score -= 4.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        // dead-space penalty for tiny unusable slivers
        if pr < 10 {
            score += 12.0;
        }
    } else {
        score -= 10.0; // perfect fit
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= 6.0;
        } else {
            score += 3.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Empty new-bin candidate: neutral baseline, only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.2 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    // Tightness reward: prefer bins that become nearly full
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 5.0;

    // Slight preference to balance residual against mean as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).abs() * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: tiny unusable gaps are heavily penalized ---
    if post_residual > 0 && post_residual <= 12 {
        // Dead space that almost nothing can use (items >= 10, or >=1 in general).
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0; // truly unusable gap
        } else {
            // Gap smaller than the smallest plausible item: quadratic penalty.
            let gap = post_residual as f64;
            score += (13.0 - gap) * (13.0 - gap) * 8.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // --- Prefer bins whose residual closely matches the item (tight fit) ---
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening new bins ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- New-bin candidate handling: only open a new bin when no good fit exists ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score = bin_capacity as f64 + 80.0 + (open_bins_count as f64) * 3.0;
        // If some existing bin fits well (small post residual), discourage new bin.
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            score += 150.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // --- Open bins pressure: mildly discourage scattering across many bins ---
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // --- Lookahead: if next item fits exactly in the post residual, reward this placement ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 90.0; // sets up a perfect follow-up fit
            } else {
                score -= slack * 0.3;
            }
        } else {
            // Next item cannot use the leftover: slight penalty proportional to waste.
            score += 5.0;
        }
    }

    // --- Mean residual coupling: placing into a bin far below mean residual spreads capacity ---
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += dev * 0.4; // prefer bins with below-average residual (fuller bins)
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match for next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match bonus: next item fills this bin perfectly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Avoid leaving a residual that cannot fit the next item (dead space risk).
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Prefer bins already below mean residual (compact bins), penalize outlier-large residuals.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-full bin on a small item (large post_residual waste).
    if item_size <= 20 && post_residual >= 40 && bin_residual != bin_capacity {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { 50.0 } else { 10.0 * fitting_bins_count as f64 };
        score += open_pressure;
        // Late in the stream, opening new bins is more costly (fewer future chances to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty per open bin to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.15;
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Large items early or when mean residual is fragmented favor new bins.
        score += 35.0 - 45.0 * tightness * (1.0 - 0.5 * progress);
        if mean_residual < item_size as f64 + 10.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Prefer bins with residual close to item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * gap;

    // Mild pressure to consolidate: fewer open bins relative to items -> favor reuse.
    if open_bins_count > 0 {
        score += 2.0 * (open_bins_count as f64).ln() / (1.0 + mean_residual / 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let tight = 1.0 - pr / cap;
    let smooth = tight * tight * (3.0 - 2.0 * tight);
    let mut score = pr * (1.0 + 0.6 * smooth);
    score -= 25.0 * smooth * (0.5 + 0.5 * progress);
    score += 0.05 * (open_bins_count as f64) * pr;
    score -= 8.0 * (1.0 - smooth) * (mean_residual / cap) * progress;
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 10.0 * (1.0 - n / cap);
        } else {
            score += 5.0 * (n / cap);
        }
    }
    score += 2.0 * (progress - 0.5).abs() * (pr / cap);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 4 quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4

    // Reward tight fits (small post_residual), especially in low classes.
    match class {
        0 => score -= 18.0,                       // post_residual < 25: near-perfect fit
        1 => score -= 8.0,                        // 25..49
        2 => score -= 2.0,                        // 50..74
        3 => score += 6.0,                        // 75..99: wasteful
        _ => {}                                   // empty bin class handled below
    }

    // Dead-space penalty: residuals that no future item (10..80 typical) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Harmonic coupling: post_residual mod 10 — small moduli are more reusable
    // since item sizes are multiples/clustered near 10s.
    let m = post_residual % 10;
    if m == 0 {
        score -= 5.0; // round residual is highly reusable
    } else if m >= 7 {
        score += 3.0; // awkward remainder
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: harmonic check
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 || next_post < 10 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; mild penalty if we consume a lot now
            score += (item_size as f64) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: neutral baseline, penalized relative to decent fits,
    // but preferred over creating large dead space.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 4.0;
        // If current fit would be terrible elsewhere, new bin looks better naturally.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) && item_size >= 50 {
            score -= 5.0; // big items pair well in fresh bins
        }
    }

    // Stream progression: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (rebalance toward filling emptier bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item
    // (below the minimum item size of 1 => treat <12 as near-dead given typical sizes).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    } else if post_residual >= 12 && post_residual < 30 {
        // Medium-small gaps are risky; scale penalty with how little fits there.
        score += (30.0 - post_residual as f64) * 0.6;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins;
    // a fresh empty-bin candidate (bin_residual == bin_capacity) gets a penalty
    // that grows with open_bins_count so consolidation is preferred.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
        // But allow opening a new bin early in the stream or when existing bins fit poorly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting the gap.
        score += 5.0;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty: quadratic in how small the leftover is.
        let dead = post_residual as f64;
        score += (bin_capacity as f64 - dead) * 0.0; // no-op keep clarity
        score += (dead / bin_capacity as f64).powi(2) * 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual will fit the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward tight two-item packing.
            if slack_after_next == 0 {
                score -= 700.0;
            } else {
                score -= 200.0 - (slack_after_next as f64 / bin_capacity as f64) * 150.0;
            }
        } else {
            // Next item won't fit here after placing current item: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    } else {
        // Last item: any placement that empties residual is great.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0 + (item_size as f64 / bin_residual.max(1) as f64) * 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it only
    // when the fit here would create large dead space and open bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Slight bias against new bins early, stronger late (consolidate at end).
        score += 30.0 + progress * 60.0;
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.5;
    } else {
        // Prefer bins tighter than the mean residual (best-fit flavor).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild preference for reusing many open bins rather than spreading.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear reward for tight fits: cubic suppression of post_residual.
    score -= 2.5 * (1.0 - post / cap).powi(3) * cap * 0.5;

    // Penalize large post_residual quadratically, amplified by stream progress
    // (late in the stream, wasted space is more costly).
    let waste = post / cap;
    score += waste.powi(2) * cap * (0.5 + 1.5 * progress);

    // Interaction: post_residual relative to mean residual across open bins.
    // Prefer bins tighter than average; penalize bins looser than average.
    let mean_r = mean_residual.max(0.0);
    if mean_r > 0.0 {
        let rel = post / mean_r;
        score += (rel - 1.0).powi(2) * 10.0 * (1.0 - progress * 0.5);
    }

    // Perfect-fit bonus (post_residual near zero) scaled by progress.
    if post == 0 {
        score -= 50.0 + 50.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if post_residual is too small for next item, penalize
    // mildly (dead space) unless post_residual itself is small.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post as f64 - nxt;
            score += 0.3 * gap; // leave room for next item => small gap is good
            if gap == 0.0 {
                score -= 30.0; // exact two-item chain
            }
        } else {
            // dead space for the lookahead item
            score += 0.2 * (nxt - post).min(cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins; make it costly unless current bin residual is tiny relative
    // to capacity and open bin count is large (fragmentation pressure).
    if bin_residual == bin_capacity {
        let frag = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let small_left = (item_size as f64) / cap; // fraction used of fresh bin
        let early = 1.0 - progress;
        score += 20.0 + 60.0 * frag * (1.0 - small_left) + 30.0 * early;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= 40.0 * small_left * small_left * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by 10 are more reusable
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0; // perfectly harmonic residual, highly reusable
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr % 2 == 0 {
        score -= 2.0;
    } else {
        score += 4.0; // odd residuals pair poorly with even-dominated streams
    }

    // Fraction of capacity left after placement
    let frac = pr as f64 / bin_capacity as f64;
    score -= 30.0 * frac * frac; // reward keeping a large usable fraction

    // Dead-space penalty: residuals too small for the smallest plausible item
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item's harmonic class?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            // reward exact or near-exact two-item fills
            if slack % 10 == 0 {
                score -= 15.0;
            } else if slack <= 5 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item won't fit here; penalize proportionally to its size class
            score += 8.0 + (next_item_size / 20) as f64 * 4.0;
        }
    } else {
        // last item: any bin is fine, slightly favor emptier bins
        score -= 5.0 * frac;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly, but allow when existing fits are poor
        score += 10.0;
        if post_residual > 0 && post_residual % 10 != 0 {
            score -= 5.0; // fresh bin keeps clean harmonic residual
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (mean_residual / bin_capacity as f64);

    // Tie-break toward fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: gaps too small for the smallest plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 && post_residual > 0 {
        score += 60.0;
    }
    // Penalize small-but-nonzero gaps that likely become waste (post_residual in [1, 15]).
    if post_residual > 0 && post_residual <= 15 {
        score += 25.0 * (1.0 - (post_residual as f64) / 15.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space avoidance: if the residual left cannot accommodate the next item,
    // but the bin could have (i.e., we are stranding space), penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 18.0;
    }
    // Reward bins whose post-residual still fits the lookahead item (keeps bin usable).
    if next_item_size > 0 && post_residual >= next_item_size as u32 && post_residual > 0 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // allow opening new bins for better packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * 3.0 * (0.5 + progress);

    // New-bin candidate: penalize moderately so it's chosen only when fits are poor,
    // but less when few bins are open (early stream benefits from fresh bins).
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * (1.0 - progress);
        // If current bin would leave a very tight residual, new bin becomes attractive.
        if post_residual > 0 && post_residual <= 10 {
            score -= 35.0;
        }
    }

    // Slight preference for bins below mean residual (balance load across bins).
    score -= 0.05 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space relative to typical next item size.
        let next = if next_item_size == 0 { 30.0 } else { next_item_size as f64 };
        if (post_residual as f64) < next {
            // Post residual too small for the next item: dead space penalty.
            score += 0.35 * (post_residual as f64 - 0.5 * next);
        } else {
            // Post residual can host the next item: reward the match.
            score -= 0.9 * (post_residual as f64 - next).min(20.0);
        }
    }

    // Exact 2-step lookahead: does post_residual fit next item exactly-ish?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - (slack as f64) / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to remaining capacity needs, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins mildly; more when stream is late.
        score += 18.0 + 25.0 * progress;
        // But if the item is huge and would leave a tiny post_residual in any
        // existing bin, opening fresh is fine — handled by comparison anyway.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Prefer filling fuller bins (smaller residual before placement).
    score += 0.15 * (bin_residual as f64);

    // Slight preference for reusing existing bins vs opening new ones.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 25.0;

    // Penalize leaving dead space that cannot fit typical items
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny dead space is fine (nearly full)
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 6.0; // residual unusable by lookahead item
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins fit poorly and mean residual is low
        let pressure = (mean_residual - item_size as f64).max(0.0);
        score = 60.0 - pressure * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // big next item: fresh bin useful
        }
        return score;
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - fit_ratio);

    // Penalize scattering across many open bins; reward filling existing ones
    score += open_bins_count as f64 * 0.4;
    score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.1;

    // Reward bins whose residual is close to mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (bins can still be filled).
    // Late in the stream: strongly penalize residual (dead space is costly).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    score += 0.6 * w_late * pr * (pr / cap);
    score -= 0.4 * w_early * pr * (1.0 - pr / cap);

    // Penalize residual far from "useful" sizes: quadratic deviation from mean residual
    // creates a smooth basin around average slack, avoiding dead-space extremes.
    let dev = pr - mean_residual;
    score += 0.15 * (dev * dev) / cap;

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tight = 1.0 - ((pr - nxt) / cap);
            score -= 1.5 * tight * nxt / cap;
        } else {
            // Post-residual cannot host next item: smooth dead-space penalty.
            let waste = (nxt - pr) / cap;
            score += 0.8 * waste * waste;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 3.0 + 0.5 * (item_size as f64 / cap);
    } else if fitting_bins_count > 1 {
        // Mild competition pressure: prefer bins with less post-residual among many options.
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Reward closing bins tightly (near-zero residual) with smooth saturation.
    let tightness = 1.0 - (pr / cap);
    score -= 0.5 * tightness * tightness * (1.0 - w_early);

    // Mild penalty for proliferating bins late in the stream.
    score += 0.05 * w_late * (open_bins_count as f64).sqrt();

    // New-bin candidate: make empty bins attractive only when item is large or
    // current residual would leave big unusable gap.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        let gap_benefit = if next_item_size > 0 { ((pr as u32) >= next_item_size) as f64 } else { 0.0 };
        score = 2.0 + 4.0 * (1.0 - large_item) - 1.0 * gap_benefit - 2.0 * w_late * large_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via integer division thresholds.
    // Classes: 0 (perfect), 1-9 (great), 10-19 (ok), 20-39 (poor), >=40 (bad).
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -40.0
    } else if pr <= 9 {
        -20.0 + pr as f64
    } else if pr <= 19 {
        5.0 + (pr - 10) as f64 * 0.5
    } else if pr <= 39 {
        15.0 + (pr - 20) as f64 * 0.75
    } else {
        35.0 + (pr - 40) as f64
    };
    score += class_penalty;

    // Modulo arithmetic: residual divisible into nice chunks (multiples of 5/10) are reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 5 == 0) {
        score -= 6.0;
    }
    // Harmonic resonance: post_residual matches next item size class (same /8 bucket).
    if next_item_size > 0 {
        let nb = (next_item_size / 8) as f64;
        let pb = (pr / 8) as f64;
        if nb == pb && pr >= next_item_size {
            score -= 18.0; // next item fits this bin exactly in class terms
        } else if pr >= next_item_size {
            score -= 4.0;
        } else {
            // next item cannot use leftover: dead space likely
            score += (next_item_size as f64 - pr as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: only attractive when all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap; // 0 = tight bins, 1 = empty bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 30.0 * (crowding - 0.25).max(0.0) / 0.75 + 10.0 * progress;
        score += -new_bin_bonus + (open_bins_count as f64) * 0.5;
        // A new bin is bad if item is small (wastes capacity).
        score += (cap - item_size as f64) * 0.15;
    }

    // Prefer filling fuller bins overall.
    score -= (1.0 - bin_residual as f64 / cap) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (small but nonzero) is heavily penalized since nothing else fits there.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny unusable slivers are worst
        } else if gap < 20.0 {
            score += 25.0 * (20.0 - gap) / 10.0;
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        score -= 40.0 * (item_size as f64) / (bin_residual as f64).max(1.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is great.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current fit is bad (large post_residual) or no real alternatives exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 30.0;
        // But if this item would leave a terrible gap in an existing bin,
        // a fresh bin becomes competitive.
        if post_residual > 30 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balance loads).
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual as i64 == next_item_size as i64 {
            score -= 150.0;
        }
        // Penalize residual too small for next item (dead space risk)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins below mean residual (tight packing), penalize above-mean usage
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Mild pressure against hoarding many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scaled waste penalty that grows for small post-residuals
    // that are too small to be reusable later.
    let t = step_index as f64 / total_items.max(1) as f64;
    let reusable_threshold = 10.0 + 30.0 * t; // later in stream, small leftovers are more costly
    if (post_residual as f64) < reusable_threshold && post_residual > 0 {
        score += (reusable_threshold - post_residual as f64) * 1.5;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Lookahead: penalize leaving a residual that fits next item awkwardly
    // (next item barely fits, wasting this bin's flexibility), reward if
    // residual is either too small or comfortably fits next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            let slack = post_residual as f64 - nr;
            if slack < 10.0 {
                score += 8.0; // next item would leave near-zero here anyway, fine either way
            } else {
                score -= 5.0; // room for the next item too: good chaining
            }
        } else if (post_residual as f64) > 0.0 && nr - post_residual as f64 <= 15.0 {
            score += 6.0; // next item just misses fitting: dead space risk
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into bins with below-average residual usage.
    if open_bins_count > 0 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev; // bins with residual below mean (fuller) get lower score
        if open_bins_count > 8 && (bin_residual as f64) > mean_residual + 20.0 {
            score += 10.0; // discourage using sparse bins when many bins open
        }
    }

    // New-bin candidate handling: neutral baseline, penalize early in stream
    // when consolidation is cheap, allow late if it avoids fragmentation.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 * (1.0 - t) + 15.0;
        score += new_bin_penalty;
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 5.0; // pairing large items into fresh bin can be fine
        }
    }

    // Mild preference for filling larger-capacity-remaining bins early.
    score += 0.05 * (bin_residual as f64 - item_size as f64) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post residual), scaled by capacity.
    let mut score = pr / cap;

    // Smooth non-linear coupling: waste penalty grows quadratically with progress
    // (dead space becomes more costly as the stream matures).
    let waste = (pr / cap).powi(2);
    score += waste * (0.5 + 2.0 * progress);

    // Cubic interaction between post residual and mean residual: bins with
    // residuals similar to the average are neutral; extremes penalized smoothly.
    let mr = mean_residual / cap;
    score += 0.3 * (pr / cap) * (pr / cap - mr).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 1.0;
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Next item won't fit here; slight penalty for leaving awkward gap.
        score += 0.2 * (next_item_size as f64 / cap);
    }

    // New-bin candidate: neutral baseline with mild openness pressure; early in
    // the stream opening bins is cheap, later it is penalized.
    if bin_residual == bin_capacity {
        score = 0.9 + 0.6 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else {
        // Harmonic class of post_residual: how "reusable" is the leftover space?
        // Residuals that are multiples of 10 (or common item sizes 10..80) are more reusable.
        let pr = post_residual;
        let mut reusability = 0.0;
        if pr % 10 == 0 { reusability += 8.0; }
        if pr % 5 == 0 { reusability += 3.0; }
        if pr >= 10 && pr <= 80 { reusability += 4.0; } // in the plausible item-size range
        if pr < 10 { reusability -= 15.0; } // dead space penalty
        score -= reusability;

        // Dead-space harshness grows with stream progress: late in the stream,
        // waste matters more since there is less time to fill gaps.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if pr < 10 {
            score += 20.0 * progress;
        }

        // Lookahead coupling: strongly reward bins whose post_residual can fit next item.
        if next_item_size > 0 {
            if pr >= next_item_size {
                score -= 12.0;
                // Extra reward if post_residual - next_item_size is again reusable.
                let after = pr - next_item_size;
                if after == 0 { score -= 25.0; }
                else if after % 10 == 0 { score -= 6.0; }
                else if after < 10 { score += 5.0; }
            } else {
                score += 10.0; // leftover can't host the next item
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // open bins are fragmented (high mean residual spread) or item is large.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 * 0.5)).abs();
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        // Baseline: new bin is neutral-ish; subtract when bins are fragmented or item huge.
        score += 5.0; // slight preference for existing bins by default
        score -= fragmentation * 0.3 + large_item_bonus;
        // Late in stream, reusing bins is even more valuable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64).min(20.0) * 0.5 * (bin_residual == bin_capacity) as i32 as f64;

    // Small harmonic nudge on item size class: big items prefer bins with big residuals.
    if item_size >= 50 && bin_residual >= 60 {
        score -= 5.0;
    }
    if item_size < 20 && post_residual > 70 {
        score += 3.0; // don't waste a big gap on a tiny item if alternatives exist
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more harshly than large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: when many bins are open, favor filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Penalize bins far above mean residual (wasteful large bin usage)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // New bin candidate: mild penalty so it's only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward tight coupling, scaled by how close it is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 / (1.0 + slack / 20.0);
        } else {
            // Next item won't fit: penalize leaving a small unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap;
        }
    }

    // Prefer bins whose residual is already below the mean (consolidate fullness).
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: only open bin that fits gets strong preference.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize tiny dead space (< 10, minimum item size) — unusable residue.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // New-bin candidate: make it costly unless no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 60.0;
        let pressure = if fitting_bins_count == 0 { -1000.0 } else { 0.0 };
        score = base - pressure + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: penalize if next item could fit in post_residual (keep space for it),
    // reward if next item won't fit here anyway (wasted space is less costly)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score += 12.0; // keeping this bin for next item is attractive -> slightly deprioritize now? Actually penalize consuming it
        } else {
            score -= 8.0; // space unusable by next item anyway
        }
        // If next item exactly fills post_residual, strongly prefer this bin
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty for consuming a scarce-residual bin
    if fitting_bins_count > 2 {
        score += 5.0;
    }

    // Global residual pressure: if mean residual is high, prefer filling fullest bins
    score += (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: early in stream, opening new bins is cheap; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin more as stream progresses
        score += 20.0 + 60.0 * progress;
        // But if open bins are all poor fits and item is large, new bin is fine
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 45.0;
        }
    } else {
        // Late stream: reward consolidating into existing bins
        score -= 15.0 * progress;
    }

    // Prefer bins with larger current residual when many bins open (spread vs cluster)
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: penalize post residual, but non-linearly (dead space hurts more as it grows)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills mildly; late in stream, weight residual more heavily
    let progress_coupling = pr * (0.5 + 1.5 * progress) * (1.0 - fit * fit);
    score += progress_coupling;

    // Interaction: does next item fit into post_residual? smooth quadratic reward
    let gap = nxt - pr / cap;
    let fits_next = (1.0 - gap.clamp(0.0, 1.0)).clamp(0.0, 1.0);
    score -= 12.0 * fits_next * fits_next * (1.0 - progress * 0.5);

    // Last-chance bin bonus (smooth)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 6.0 * last_chance * last_chance;

    // Penalize bins whose residual deviates from mean (imbalance) via smooth term
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (0.5 + progress);

    // Mild penalty for spreading across many bins
    score += 0.3 * (open_bins_count as f64).sqrt() * norm_pr;

    // New-bin candidate: penalize opening a new bin unless residual is truly unusable
    if bin_residual == bin_capacity {
        let waste = 1.0 - (1.0 - norm_pr); // = 1 for empty bin
        score += 15.0 * (1.0 - progress) * waste;
        // allow new bin if current post_residual would leave tiny unusable gap
        let unusable = (norm_pr * (1.0 - norm_pr)).clamp(0.0, 0.25);
        score -= 20.0 * unusable * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity/4, /2, /3 are "usable" classes
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    // Penalize dead space that falls into awkward harmonic classes (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 {
        // Reward post-residuals that are multiples of common size blocks
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % quarter == 0 && post_residual > 0 {
            score -= 4.0;
        }
        if post_residual % third == 0 && post_residual > 0 {
            score -= 3.0;
        }
        // Penalize residues that can't fit the smallest possible item comfortably
        if post_residual < 20 {
            score += 8.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 10.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.25;
            }
        } else {
            // next item won't fit here; mildly penalize leaving large gap unused
            score += 2.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 8.0 * fill_ratio;
    }

    // New-bin candidate handling: only prefer new bin if all open bins are badly fragmented
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 12.0; // open bins nearly full -> new bin is fine
        } else if pressure > 0.35 {
            score += 15.0; // open bins still have room; discourage new bin
        } else {
            score += 4.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // leftover can host the next item: mild reward scaled by slack match
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // leftover too small for next item: penalize dead space
            let dead = post_residual as f64;
            if dead > 0.0 {
                score += 10.0 + dead * 0.5;
            }
        }
    }

    // Penalize very small unusable leftovers (dead space) generally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // late in the stream, opening fresh bins is less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Coupling with mean residual: bins far below mean residual are tighter; prefer tighter bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Prefer bins among many fitting candidates only if they are tight fits.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 35.0 * next_tight;
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (balance consolidation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 for empty bin
        let open_pressure = open_bins_count as f64;
        // Base new-bin score slightly above a good existing fit, but drops with many open bins
        // having large residuals (fragmentation).
        score = 55.0 + 0.3 * open_pressure - 10.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
        if progress > 0.8 {
            score += 15.0; // late stream: avoid opening bins
        }
        let _ = poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post residual (tight fit), scaled non-linearly.
    let mut score = (pr / cap).powf(2.0) * cap;

    // Smooth coupling of post_residual with stream progress: late in the stream,
    // dead space becomes increasingly costly.
    score += (pr / cap).powf(3.0) * cap * (0.5 + 1.5 * progress);

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= tightness.powf(2.0) * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap as f64 * (0.5 + progress);
    }

    // Penalize creating residual that cannot fit the lookahead item (smooth penalty).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += gap.powf(2.0) * cap * (0.5 + progress);
        } else {
            // Smooth reward if lookahead fits exactly-ish.
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack).clamp(0.0, 1.0) * progress * 10.0;
        }
    }

    // New-bin candidate: penalize opening new bins, more so late in the stream
    // and when many bins are already open; allow it early or when current bin is crowded.
    if is_new_bin {
        let crowd = ((open_bins_count as f64 - mean_residual / cap.max(1.0)) / 10.0).clamp(0.0, 1.0);
        let mut penalty = cap as f64 * (0.6 + 1.4 * progress) + 5.0 * open_bins_count as f64;
        // If existing bins are very fragmented (high mean residual), opening fresh is cheaper.
        penalty -= (mean_residual / cap).clamp(0.0, 1.0) * cap * 0.4 * (1.0 - progress);
        penalty -= crowd * 10.0;
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "clean" and more likely reusable by future items (sizes 1..100).
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -14.0,               // perfectly aligned residual
        5 => -4.0,                // half-class, moderately reusable
        2 | 4 | 6 | 8 => 3.0,     // even but misaligned
        _ => 7.0,                 // odd residuals: near-dead space
    };
    score += class_penalty;

    // Integer-division thresholds: how many "typical" chunks still fit.
    let chunks = post_residual / 20;
    score -= chunks as f64 * 5.0;

    // Lookahead coupling: reward if next item fits into post_residual
    // (chained placement), penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra harmonic bonus when both residuals and next item align mod 10
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 6.0;
            }
        } else {
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when item is large relative
    // to capacity or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64) / (bin_capacity as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        score += 30.0 - tight_fit * 40.0 + fragmentation * 10.0;
        if post_residual == 0 {
            score -= 60.0; // perfect fill of a fresh bin
        }
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure of an existing bin
    }

    // Mild pressure toward consolidating bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + progress * 0.5);

    // Penalize bins far from the mean residual when mean residual is large
    // (prefer balanced packing); reward when mean residual is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08 * (1.0 - mean_residual / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space below minimum item size: heavily penalize.
            score += 60.0;
        } else if post_residual < 25 {
            // Awkward gap: only useful for small items; moderate penalty.
            score += 25.0;
        } else if post_residual < 40 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits generally (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = 20.0 + 30.0 * (open_bins_count as f64 / 10.0).min(2.0) + 15.0 * progress;
        score += pressure;
        // If the next item could use the fresh bin's full space, soften slightly.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Prefer bins with residuals close to what we consume (avoid fragmenting large gaps).
    score += 0.3 * ((mean_residual - bin_residual as f64).abs());

    // Lookahead: if next item fits exactly in the resulting residual, reward.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (a perfect chain match).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else {
            // Penalize dead space too small to ever be useful (below min item size 1..100
            // means anything < ~10 is nearly unusable, but keep generic).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.75;
            }
            // Reward leaving space that could still fit a future item.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= post_residual as f64 * 0.3 * (1.0 - progress);
        }
    }

    // Compare against mean residual: prefer bins whose post-residual stays
    // near/below the mean (keeps residual distribution compact).
    score += (post_residual as f64 - mean_residual).abs() * 0.4;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize scattering across many open bins slightly; encourage filling
    // tight bins first.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when no good fit exists — make the
    // empty bin costly so it is chosen only when open bins would waste space.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the next item matches the full residual well, allow opening.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 10 {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, especially non-usable slivers.
    if post_residual > 0 {
        let sliver = post_residual < 10;
        score += if sliver { 25.0 } else { (post_residual as f64).powf(1.35) * 0.25 };
    } else {
        score -= 20.0; // perfect fit bonus
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize if post_residual is a small dead zone.
            let gap = next_item_size as f64 - post_residual as f64;
            if post_residual > 0 && gap < 15.0 {
                score += gap * 0.8;
            }
        }
    }

    // Prefer filling bins with large residuals when many bins are open (reduce fragmentation).
    let spread = bin_residual as f64 - mean_residual;
    if open_bins_count > 3 {
        score += spread * 0.3;
    }

    // New-bin candidate logic: only open a new bin when the item is large and
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; discount when item is big and mean residual is low.
        let mut new_bin_penalty = 18.0 + 20.0 * (1.0 - tightness);
        if mean_residual < item_size as f64 + 5.0 {
            new_bin_penalty -= 15.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 40.0; // must open a bin
        }
        new_bin_penalty += 10.0 * progress; // late in stream, consolidate more
        score += new_bin_penalty;
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Polynomial decay: early stream, prefer tight fits (low post_residual) more strongly
    let progress_weight = 0.5 + 2.0 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= progress_weight * (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0;

    // Non-linear penalty on very small post residuals that create dead space
    let dead = (norm_pr * (cap - pr) / cap).sqrt();
    score -= dead * 10.0;

    // Coupling with mean residual: penalize bins far from mean (smooth quadratic)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: reward if next item fits the post residual (smooth gaussian-like)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-(gap * gap) / (2.0 * 400.0)).exp();
    }

    // Last-chance bin: smooth reward via logistic of fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp() * 2.0);
    score -= last_chance * 8.0;

    // New-bin candidate: penalize opening new bins smoothly, more early on
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    // Mild reward for larger items filling bins (non-linear in fill ratio)
    score -= 5.0 * fit_norm * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (divisible into small chunks) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the residual by harmonic division of capacity:
    // class 0: residual divisible by 50, 25, 20, 10 -> highly reusable
    let div_bonus = ((post_residual % 50 == 0) as i32) * 8
        + ((post_residual % 25 == 0) as i32) * 4
        + ((post_residual % 20 == 0) as i32) * 3
        + ((post_residual % 10 == 0) as i32) * 2;
    score -= div_bonus as f64;

    // Dead-space penalty: residuals that cannot host typical small items
    // (1..=10 range assumption: anything < 10 with no small-item lookahead)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty for wasting large residual
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals
    // are large relative to the item (poor fits) or many bins are open.
    if bin_residual == bin_capacity {
        // Base preference for reusing: new bin slightly penalized.
        score += 15.0;
        // But if the item leaves a harmonically clean residual in a fresh bin
        // and mean residual is badly fragmented, allow opening.
        let fragmentation = (mean_residual - pr).abs();
        if mean_residual > 60.0 && post_residual % 25 == 0 {
            score -= 25.0;
        }
        if fragmentation < 5.0 && post_residual < 40 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer tighter bins overall (small residual before placement is good).
    score += (bin_residual as f64) * 0.05;

    // Mild pressure against too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (near-zero post residual is great if usable).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward;
    // if post residual is too small for next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance pressure: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(0.6) * (1.5 + 2.0 * progress);

    // Prefer bins with below-mean residual (fill emptier ones keeps tight ones tight).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: make it moderately expensive unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (item exactly fills the bin).
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual < next_item_size {
            // Dead space for the next item: penalize proportionally to how wasted it is.
            score += (next_item_size - post_residual) as f64 * 3.0;
        } else {
            // Next item fits after this one: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + slack);
        }
    }

    // Penalize residual far below the mean residual (fragmented bin relative to fleet).
    let res = post_residual as f64;
    score += (mean_residual - res).abs() * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the current fit is very loose
    // (large post_residual) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64) * 2.0;
        // Discourage opening a new bin when this item would fit snugly somewhere.
        if item_size as f64 / bin_capacity as f64 > 0.5 {
            score += 80.0;
        }
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residual that no future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits in the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
        } else {
            // next item won't fit here; penalize more if post_residual is wasted-ish
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        // baseline for new bin: compare against mean residual waste
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
        if fit_ratio.is_nan() || fit_ratio < 0.999 {
            // some bin could fit; open new bin only if existing residuals are tight
            if mean_residual < item_size as f64 + 5.0 {
                score -= 10.0;
            }
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins: discourage opening more
        score += 0.8 * open_bins_count as f64;
    }

    // Mild penalty for using bins with residual far from mean (keep pool homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling larger-residual bins slightly (best-fit is baseline; this nudges first-fit-decreasing-like balance)
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste penalty on post residual
    let mut score = norm_post * norm_post * 60.0 + norm_post * 20.0;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer tight packing (low post residual); late, tolerate residuals
    let coupling = 40.0 * (1.0 - progress) * norm_post * norm_post
                 - 25.0 * progress * norm_post;
    score += coupling;

    // Penalize residuals that are dead space (too small for the smallest plausible item)
    let dead = (10.0 - norm_post * 100.0).max(0.0) / 10.0;
    score += dead * dead * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - (nxt / post.max(1.0)) * 0.5);
        } else {
            score += 10.0 * ((nxt - post) / cap);
        }
    }

    // Mild preference for using existing bins over opening new ones,
    // scaled by how many bins are open
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }

    // Slight tie-breaker toward bins below mean residual (tighter bins)
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Leftovers in "half" and "third" classes are
    // reusable; tiny slivers are dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries via integer division on post_residual
    let quarter_class = post_residual / (bin_capacity / 4);      // 0..4
    let eighth_class = post_residual % (bin_capacity / 4);       // fine structure

    // Reward residuals that fall in reusable harmonic classes (near half, third)
    let half = cap / 2.0;
    let third = cap / 3.0;
    let dist_half = (post - half).abs();
    let dist_third = (post - third).abs();
    let dist_quarter = (post - cap / 4.0).abs();

    score -= 6.0 * (-dist_half / 10.0).exp();
    score -= 4.0 * (-dist_third / 10.0).exp();
    score -= 2.5 * (-dist_quarter / 10.0).exp();

    // Penalize dead-space slivers (post_residual small but nonzero)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 18.0 * (1.0 - post as f64 / (bin_capacity / 10) as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-arithmetic coupling between item and next item on capacity grid:
    // if item + next_item packs into a harmonic fraction of capacity, favor bins
    // that leave room aligned with the next item's class.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let pair_sum = item_size + next_item_size;
        let pair_class = pair_sum / (bin_capacity / 2);          // 0,1,2
        if pair_class >= 1 {
            score -= 5.0 * pair_class as f64;
        }
        // next item fits exactly into this bin's post residual (chained fit)
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (-((post - next_item_size as f64).abs()) / 12.0).exp();
        }
    } else if next_item_size > 0 {
        // next item won't fit here regardless; slight penalty for wasting alignment
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when the fit here is terrible (large post residual unused)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_here = (cap - post) / cap; // fraction of this bin's space consumed
        // reward opening a new bin when current fit is bad and many bins open
        score = 55.0 - 30.0 * (1.0 - waste_here) + 20.0 * progress + 2.0 * open_bins_count as f64;
        // if next item is large, a fresh bin gives flexibility
        if next_item_size as f64 >= cap * 0.6 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.15 * open_bins_count as f64 * (1.0 - post / cap);

    // Fine residual texture: prefer residuals congruent to common item sizes (mod 10)
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 3.0;
    } else if mod_class >= 5 {
        score += 1.0;
    }

    score += eighth_class as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps in the "awkward" band (10..20) are risky: many items won't fit.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Slight preference to spread load when few bins are open.
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Lookahead: if the next item fits the post-residual, this placement
    // sets up a good chain; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item is large and post_residual can't hold it, mild penalty.
    if next_item_size > post_residual && next_item_size > 50 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fits)
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Strong reward for near-perfect fit
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 18.0;
        score -= 0.5 * leftover_after_next as f64;
        // bonus if next item then nearly fills the bin
        if leftover_after_next <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to the next item: penalize proportionally
        let gap = next_item_size - post_residual;
        score += 0.6 * gap as f64;
        if gap > 20 {
            score += 15.0;
        }
    }

    // Relative to mean residual: bins with residual far below mean are "tighter",
    // prefer packing into them to consolidate
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let waste_of_open = bin_capacity - item_size;
        score += 30.0 + 0.8 * waste_of_open as f64;
        // but if no other bin could fit anyway, mild penalty
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // late in stream, consolidating is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize bins whose residual is barely above item (awkward fit) unless it's near-perfect.
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 && slack < 10.0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    }
    // If next item almost fits (small miss), slight penalty for leaving tempting dead space.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 6.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0 * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, be more willing to open new bins (score new bins lower);
    // later, discourage new bins to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 - 45.0 * progress;
    }

    // Prefer bins with below-mean residual (they are "emptier" candidates to fill);
    // slight reward for placing into bins below mean residual to balance.
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Large items: prefer bins with large residual so big items don't fragment small bins.
    if item_size > 50 && bin_residual < item_size + 10 && bin_residual != bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: favor tight fits (small post residual)
    let mut score = pr as f64;

    // Smooth non-linear coupling: waste penalty grows super-linearly as residual shrinks
    score += cap * (x * x * (1.0 - x)) * 0.5;

    // Dead-space penalty for residual too small to fit typical future items
    let dead = (1.0 - x).powi(6);
    score += 12.0 * dead;

    // Lookahead: if next item fits in post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64) / pr).tanh();
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    // Stream-progress polynomial coupling: mildly prefer compacting early
    score *= 1.0 + 0.3 * progress * (1.0 - progress);

    // Mean residual interaction: avoid bins far from fleet mean
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact division classes of capacity
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => -60.0, // perfect fill
        1..=5 => -35.0,
        6..=10 => -20.0,
        11..=20 => -8.0,
        21..=30 => 0.0,
        31..=50 => 6.0,
        _ => 12.0, // large dead space
    };
    score += class_bonus;

    // Reward tight fit relative to item size
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Harmonic class of item size (integer division thresholds)
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;
    if next_item_size > 0 {
        // Strong reward if next item fits exactly in post_residual
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 12.0;
            // bonus for class-adjacent pairing (harmonic coupling)
            let cd = (item_class as i32 - next_class as i32).abs();
            score -= (4.0 / (1.0 + cd as f64));
        } else {
            // next item cannot fit here: penalize wasting large residual
            score += 8.0;
        }
        // exact complement pairing of small items
        if item_size + next_item_size == bin_capacity {
            score -= 25.0;
        }
    } else {
        // last item: prefer minimal post residual strongly
        score += 0.5 * pr as f64;
    }

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 45.0;
        // open a new bin only for very large items or near stream end with many bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 {
            score -= 20.0;
        }
        if open_bins_count > 8 && progress < 0.5 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading residual far above mean (keeps bins balanced)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score += 0.02 * dev; // slight reward for below-mean residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // since leftover slivers below the minimum item size (1) waste capacity forever.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit bonus: reward when post_residual is small relative to typical item mass.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness);

    // Last-chance bin: strongly favor using the only bin that fits, to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few open,
    // allow opening new bins to keep future flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open or mean residual is large.
        score += 20.0 + pressure + mean_residual * 0.5;
    } else {
        // Existing bin: mild reward for consolidating when many bins are open.
        score -= pressure * 0.15;
    }

    // Lookahead: if the next item fits snugly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 {
        score -= 20.0;
    }
    // If next item would be stranded by this placement's leftover, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize post residual
    score -= 0.5 * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish -> strong reward scaled by closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does not fit: penalize wasted post residual
            score += 0.15 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 4.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0; // fresh bin still useful for lookahead pairing
        }
        if fitting_bins_count > 2 {
            score += 5.0; // plenty of alternatives, avoid spreading
        }
    }

    // Penalize leaving tiny dead space (< next typical small item) unless exact
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let waste = post_residual as f64;

    // Reward tight fits: penalize residual quadratically (dead space is worse the larger it is)
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Reward high fill ratio
    score -= 40.0 * fill * fill;

    // Perfect fit is excellent
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // mild reward if next item still fits here afterwards
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; small penalty proportional to leftover awkwardness
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize spreading across too many open bins when mean residual is already small
    if bin_residual != bin_capacity {
        let closeness = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * closeness;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // no good existing option exists (few fitting bins) or item is large.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let large_item = item_size as f64 / bin_capacity as f64;
        let base_penalty = 60.0 + 50.0 * (1.0 - pressure);
        score += base_penalty;
        // Late in stream, prefer consolidating into existing bins
        score += 40.0 * progress;
        // Large items leaving tiny residue are okay in a fresh bin
        score -= 30.0 * large_item;
        // If next item is large too, a fresh bin gives flexibility
        if next_item_size >= 50 {
            score -= 25.0;
        }
        // Many open bins already: discourage opening more
        score += 2.0 * open_bins_count as f64;
    }

    // Early stream: slight preference for keeping bins balanced (future flexibility)
    if progress < 0.3 && bin_residual != bin_capacity {
        score -= 10.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post_residual, modulated by stream progress.
    // Later in the stream, tight fits (small post_residual) are rewarded more.
    let mut score = pr * (1.0 + 0.8 * progress) - 0.9 * norm_pr * norm_pr * cap * progress;

    // Smooth coupling: penalize residuals that are too small to be useful,
    // via a smooth saturating term on normalized post_residual.
    let dead_space = (norm_pr - 0.15).tanh();
    score += 6.0 * (1.0 - dead_space * dead_space) * norm_pr * cap * (1.0 - progress);

    // Reward filling bins tightly when the item is large relative to capacity.
    let fill_ratio = item_size as f64 / cap;
    score -= 12.0 * fill_ratio * fill_ratio * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins compete, prefer consolidation.
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 3.0 * (gap / cap).tanh() * (1.0 - progress);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Mean residual coupling: prefer bins deviating from the mean when mean is low
    // (consolidate into emptier bins), mildly when mean is high.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1 - 1.5 * dev * (1.0 - progress);

    // New-bin candidate handling: only attractive late in the stream or when
    // existing bins would leave very tight post residuals.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let tightness = if post_residual == cap { 1.0 } else { 0.0 };
        score += 5.0 * (1.0 - progress) + 10.0 * tightness;
        if fitting_bins_count >= 1 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues modulo 10 and 25
    let pr = post_residual;
    let residue10 = (pr % 10) as f64;
    let residue25 = (pr % 25) as f64;

    // Penalize residuals that are small-but-nonzero (dead space) via harmonic classes
    if pr > 0 {
        if pr < 10 {
            score += 60.0; // tiny unusable sliver
        } else {
            // quantization penalty: how far pr is from the nearest multiple of 25 or 10
            let dist25 = residue25.min((25.0 - residue25)) as f64;
            let dist10 = residue10.min((10.0 - residue10));
            score += 0.8 * dist25.min(dist10);
        }
    } else {
        score -= 40.0; // perfect closure strongly rewarded
    }

    // Integer-division thresholds on post_residual / next_item_size coupling
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            // lookahead fits: reward, especially if post_residual classes align
            let slack = (pr - nxt) as f64;
            score -= 25.0;
            // penalize leftover after lookahead if it lands in a bad harmonic class
            let lft = (pr - nxt) % 10;
            if slack > 0.0 && lft > 0 && (pr - nxt) < 10 {
                score += 35.0;
            }
            score += 0.3 * slack;
        } else {
            // lookahead cannot fit: penalize more if this bin was the only option
            score += 15.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // open a new bin when existing residuals are low / item is large
        score += 10.0 - 40.0 * fragmentation - 0.2 * item_size as f64 + 20.0 * progress;
    }

    // Mild preference for tighter bins (small residual before placement)
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 range,
    // small items ~<=10) are likely unusable dead space -> strong penalty.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (perfect fill gets a large bonus).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing bins
    // when the bin count grows.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity; make it attractive
    // only when the fit in this bin would be poor (large dead space relative to capacity).
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.5 {
            score -= 25.0 * waste_ratio; // prefer fresh bin for poor fits
        } else {
            score += 40.0; // discourage opening bins when fit is decent
        }
    }

    // Lookahead: if the next item fits perfectly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Slight preference for bins whose residual is below the mean (consolidate emptier space).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward perfect chaining
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // item+next fills bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover dead space
            score += 0.5 * post_residual as f64;
            score += 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasteful near-empty placements when many bins are open
    if post_residual > 60 && bin_residual != bin_capacity {
        score += 15.0;
    }

    // Mild progress-based conservatism: early on, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it moderately attractive but not dominant
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use leftover space; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // When many bins fit the item, prefer the one with the least residual waste.
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - item_size as f64) * 0.15;
    }

    // Global pressure: if mean residual is low, conserve space (penalize large bins less).
    let mean_gap = bin_residual as f64 - mean_residual;
    score += mean_gap * 0.1;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 8.0;
    score -= progress * 6.0;

    // Many open bins: discourage spreading; few open bins: encourage consolidation.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += open_pressure * 3.0;

    // New-bin candidate: make it attractive only when current bins are poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        score -= 20.0 - poor_fit * 0.1;
        if next_item_size > 0 && next_item_size >= bin_residual - item_size && next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, favor tight fills (low post_residual) mildly;
    // late in the stream, penalize large residuals strongly.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * prn * prn * cap;

    // Smooth interaction: post_residual vs mean residual deviation.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap - 1.5 * dev * cap;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_frac * fit_frac;

    // Last-chance bonus (smooth sigmoid-like on fitting_bins_count).
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 4.0 * last_chance;

    // Lookahead: penalize if post_residual cannot fit next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 3.0 * gap * gap * cap;
        // Reward if next item fits exactly into the residual.
        let next_fit = 1.0 - (nxt - pr).abs() / cap;
        score -= 2.0 * next_fit.max(0.0) * next_fit.max(0.0);
    }

    // Mild penalty for spreading across many bins as stream progresses.
    score += progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact power-of-two-like divisions
    // (100/2=50, 100/4=25, etc.) are "good" dead space; odd tiny slivers are bad.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is best
    } else if pr >= 25 && pr <= 50 {
        score -= 12.0; // residual in the "reusable" band (fits half of item sizes)
    } else if pr < 10 {
        score += 25.0; // unusable sliver for small items
    }

    // Modulo logic on residual: residuals divisible by 10 align with the
    // coarse item grid, making future packing easier.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Penalize residuals that are odd and small (dead space for even items)
    if pr % 2 == 1 && pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > pr {
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 18.0 + crowd * 5.0 - progress * 8.0;
        // If item leaves a harmonically nice residual (e.g. 50), new bin is more attractive
        let new_post = bin_capacity - item_size;
        if new_post % 25 == 0 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins slightly: closeness of item to residual (good fit)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Mean residual divergence: placing into a bin far from the mean balances residuals
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Gaps below the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual <= 25 {
        // Small gaps are hard to fill: superlinear penalty.
        let gap = post_residual as f64;
        score += 1.5 * (25.0 - gap) * (25.0 - gap) / 10.0;
    }

    // Reward large post_residual only mildly (it stays usable),
    // but reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: penalize using bins when many are already open,
    // encouraging consolidation; but penalize opening new bins when few are open.
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure from open bin count.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // If no open bin fits well (post_residual of this item in new bin is
        // small gap risk), new bin is fine; if item is tiny relative to capacity,
        // discourage wasting a fresh bin.
        if item_size <= 30 && open_bins_count > 0 {
            score += 20.0;
        }
        // Lookahead: if next item could share this new bin, slight bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    } else {
        // Using an existing bin: reward when open bin count is high (consolidate).
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to mean (avoid fragmenting outliers)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
