pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalizes wasteful placements harder.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap <= 10 {
            score -= 8.0;
        }
    }

    // Lookahead danger: if next item cannot fit here anyway but could fit
    // if we left more room, penalize creating tiny unusable slivers.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists (large post-residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, prefer consolidating into open bins.
        score += 30.0 + 40.0 * progress;
        // If this bin is the last chance, opening a new bin is bad.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
        // If the item leaves a lot of dead space in any bin, new bin is fine.
        if post_residual > 40 {
            score -= 20.0;
        }
    }

    // Slightly prefer bins with larger residuals among equals (best-fit tie-break
    // toward leaving small bins for small future items).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Mild preference to fill bins with many open bins (reduce bin count pressure).
    if open_bins_count > 8 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let p2 = norm_pr * norm_pr;
    let p3 = p2 * norm_pr;
    let coupling = pr * (0.9 + 0.6 * progress) - 25.0 * p2 * (0.5 + progress) + 8.0 * p3;

    let mut score = coupling;

    // Reward tight fits (small post residual), more aggressively later in the stream.
    score -= (cap - pr) * (0.15 + 0.35 * progress * progress);

    // Penalize dead space that cannot plausibly fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            // Smooth reward when next item could still fit here.
            score -= 4.0 * (1.0 - ((pr - nxt) / cap).min(1.0));
        }
    } else {
        // Last item: strongly prefer exact fits.
        score += pr * 0.8;
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
        if pr <= 10.0 {
            score -= 20.0;
        }
    }

    // New-bin candidate: attractive early, increasingly discouraged as stream progresses
    // unless the fit into existing bins would be very poor.
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress) * (1.0 - progress);
        score += 20.0 * progress * progress;
        if next_item_size > 0 && (cap - item_size as f64) >= next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild penalty for proliferating bins relative to mean residual spread.
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * residual_frac * residual_frac;

    // Harmonic classes: post_residual bucketed by integer division thresholds
    let class = post_residual / 10; // class 0..10
    match class {
        0 => score -= 20.0,             // near-perfect fit
        1 => score -= 8.0,              // good
        2 | 3 => score -= 2.0,          // medium usable
        4 | 5 | 6 => score += 4.0,      // awkward dead zone
        7 | 8 | 9 => score += 1.0,      // large residual may still be usable
        _ => {}
    }

    // Modulo arithmetic on post_residual: values divisible by small integers are
    // more likely reusable by typical item sizes
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 2 == 0 { score -= 1.0; }
    }

    // Lookahead: reward if the next item fits exactly or well into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 15.0 - (gap as f64).min(15.0);
        if gap == 0 { score -= 10.0; } // perfect chain fit
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: penalize small stranded residuals
        if post_residual < 20 { score += 10.0; }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are bad
    if bin_residual == bin_capacity {
        let avg_dead = (mean_residual - item_size as f64).max(0.0);
        score += 30.0;
        if avg_dead < 15.0 { score += 25.0; } // open bins are already tight, new bin ok
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Slight pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * residual_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap that nothing (min size 1..10) can use well
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but this must not override dead-space penalties.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving it;
    // if next item is large and would not fit, penalize wasting this bin's space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when no open bin offers a decent fit
    // (i.e., best post-residual would be large dead space).
    if bin_residual == bin_capacity {
        // neutral-ish baseline: slightly above a good existing fit,
        // below a bad one (post_residual > ~40 on open bins).
        score = 45.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Late in the stream, be slightly more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post == 0 {
        score -= 60.0;
    } else if post <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // next item fits in this bin after current placement
            score -= 15.0 + 20.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 30.0; // perfect chain fill
            }
        } else {
            // next item won't fit: penalize leaving a gap that matches nothing
            score += 6.0 + 4.0 * (gap / cap);
        }
        // compare post_residual against mean residual: prefer bins that become tight
        let tightness = (post - mean_residual) / cap;
        score += 5.0 * tightness;
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize placing into a brand-new bin when decent alternatives may exist,
    // unless current bins are mostly full.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap);
        score += 20.0 - 25.0 * mean_fill;
    }

    // Late in the stream, prefer tighter packing (less tolerance for waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 + 0.3 * slack_after_next as f64;
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += 0.25 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with residual already below mean (consolidate fragmentation).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Penalize opening new bins as stream progresses / when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.1 * next_item_size as f64;
        }
    }

    // Mild penalty for very small unusable leftovers (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with a convex penalty
    // on large leftovers (wasted space) that grows super-linearly.
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth non-linear coupling with stream progress: early in the stream,
    // tolerate slack (bins may still receive more items); late in the stream,
    // aggressively minimize post_residual.
    let progress_coupling = 0.5 * (1.0 - progress) * (1.0 - progress);
    score += progress_coupling * pr * norm_pr;

    // Dead-space trap: penalize residuals that are too small to ever be
    // useful, using a smooth sigmoid-like term centered on the next item.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 6.0 * (gap * 12.0).tanh();
    } else {
        score += 3.0 * norm_pr;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * (1.0 - norm_pr);
    }

    // Mean-residual coupling: when average slack across bins is high,
    // be pickier about tight fits (smooth interaction).
    score += 0.05 * mean_residual * norm_pr / (1.0 + open_bins_count as f64);

    // New-bin candidate: an empty bin has maximum residual; the convex waste
    // penalty plus a mild opening cost naturally pushes selection toward
    // open bins unless all fits are poor.
    if bin_residual == bin_capacity {
        score += 2.0 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead space penalty grows superlinearly for small, hard-to-fill residuals.
    if post_residual > 0 {
        let frac = pr / cap; // fraction of capacity left
        // Harmonic class via integer division thresholds: classes of size 10
        let class = post_residual / 10; // 0..=10
        match class {
            0 => score += 28.0,                 // 1..9: nearly dead
            1 => score += 12.0,                 // 10..19
            2 => score += 4.0,                  // 20..29
            3 => score -= 2.0,                  // 30..39: usable
            4 => score -= 5.0,                  // 40..49
            5 => score -= 6.0,                  // 50..59
            _ => {}                             // large residual: neutral
        }
        // Continuous coupling: penalize fractional waste quadratically for tiny slacks
        score += 10.0 * (1.0 - frac) * (1.0 - frac) * frac;
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual relative to typical small item sizes
    // If post_residual is exactly a plausible next-item size, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_slack = post_residual - next_item_size;
        score -= 14.0;
        // Reward if the lookahead item leaves another harmonically good class
        let ls_class = lookahead_slack / 10;
        if ls_class <= 1 && lookahead_slack > 0 {
            score += 6.0; // would create dead space for the next item
        } else if lookahead_slack == 0 {
            score -= 20.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // This bin becomes dead after this placement if next item can't use it
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless residual would be well-used
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how well the item fills it
        score += 55.0;
        let fill = item_size as f64 / cap;
        score -= 45.0 * fill;
        // Opening new bin attractive if item is large (hard to place later)
        if item_size >= 60 {
            score -= 8.0;
        }
        // If many open bins with high mean residual, prefer consolidating
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 12.0;
        }
    }

    // Prefer bins tighter than the mean (good fits get rewarded)
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Slight preference to use older/more-filled bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Dead-space penalty scales with how "unusable" the gap is relative to typical item sizes.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or cannot help the next item.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual < 10 {
            score -= 0.0; // empty bin has post_residual == capacity anyway
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving a gap that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that almost-but-does-not fit the next item (dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Progress-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mean residual context: if this bin is far below mean residual, it's already tight; prefer it.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly accommodates the next item (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leftover after that pair matters.
            let two_step_left = post_residual - next_item_size;
            score -= 20.0 - (two_step_left as f64) * 0.15;
        } else {
            // Next item cannot use the residual: penalize dead space,
            // scaled by how large the unusable gap is relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Penalize residuals too small to ever fit typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Tightness reward: bins that are nearly full are good targets.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (fill the emptiest-usable bins first, keep big gaps for big items).
    score += (mean_residual - post_residual as f64) * 0.10;

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin (penalize new-bin candidate in that case).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when item is large or
    // no open bin fits well; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Early in the stream, allow more bins to spread large items;
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Slight penalty for too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Encourage consolidation when many bins are open: prefer bins below mean residual.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more willing to open new bins (penalize
    // cramming into partially filled bins less); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // New-bin candidate: acceptable early or when this bin would be a bad fit.
    if bin_residual == bin_capacity {
        let early_bonus = 18.0 * (1.0 - progress);
        score = score - early_bonus + 5.0 * progress;
    }

    // Mild penalty for opening bins when many are already open.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with mild non-linear penalty growth
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes increasingly costly (quadratic ramp)
    let dead_space_penalty = norm_pr * norm_pr * cap * (0.5 + 2.5 * progress);
    score += dead_space_penalty;

    // Coupling with mean residual: penalize bins far below mean residual (wasteful placement)
    let mr = mean_residual / cap;
    score += 30.0 * (norm_pr - mr) * (norm_pr - mr) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0 + 100.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting residual
    if next_item_size > 0 {
        let fits_next = (pr as u32 >= next_item_size) as i32 as f64;
        let snug = 1.0 - ((pr as u32 - next_item_size.min(pr as u32)) as f64 / cap);
        score -= 40.0 * fits_next * snug * snug;
    }

    // Slight preference for filling existing bins over opening new ones as stream progresses
    if bin_residual < bin_capacity {
        score -= 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows super-linearly for small, awkward leftovers
    if pr > 0 {
        let dead = (bin_capacity as f64 / pr as f64).ln().max(0.0);
        score += (10 - class.min(&9)) as f64 * 0.35 * dead;
    }
    // Perfect fit reward
    if pr == 0 { score -= 60.0; }

    // Class of post_residual relative to next_item_size: does the leftover
    // form a harmonic pair with the lookahead item?
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        // reward exact or near-exact pairing with next item
        let gap_class = gap % 10;
        score -= 25.0 - (gap_class as f64) * 1.2;
        if gap == 0 { score -= 30.0; }
    } else if next_item_size > 0 {
        // leftover too small for next item: penalize proportional to wasted fraction
        score += 12.0 * (1.0 - pr as f64 / next_item_size.max(1) as f64);
    }

    // Integer-division thresholds on post_residual
    let q = pr / 25; // quarter classes
    score -= match q { 0 => 8.0, 1 => 4.0, 2 => 2.0, _ => 0.0 };

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.25 && fitting_bins_count > 0 {
            score -= 15.0; // open fresh bin when existing ones are tight
        } else {
            score += 30.0; // discourage wasting a fresh bin
        }
    }

    // Mild penalty for scattering across many open bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // Prefer bins tighter than the mean (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are already dead; residuals that cannot hold
    // typical small items are nearly dead. Penalize the "unusable gap" band.
    let dead_threshold: f64 = 12.0;
    if post_residual as f64 <= dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward a perfect or near-perfect fit (post_residual very small but
    // still above the dead band is wasted; exactly 0 is ideal).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual >= 1 && post_residual <= 3 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins (the new-bin candidate has residual == capacity, so this only
    // affects real bins... but we can also penalize the new-bin candidate
    // when open_bins_count is high by adding a term proportional to it).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // Opening a new bin early in the stream is cheap, later is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    } else {
        // Using existing bins reduces open-bin pressure slightly.
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 18.0;
        } else if slack as f64 <= dead_threshold {
            score += slack as f64 * 4.0; // next item would leave dead space
        } else {
            score -= 4.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) relative
    // to the mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Aggressive 2-step lookahead: reward when the NEXT item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack that can host the next item is valuable -> subtract reward
            // proportional to how well the next item fills the leftover space.
            let fill_after = (post_residual - next_item_size) as f64;
            let next_fit_quality = 1.0 - fill_after / bin_capacity as f64;
            score -= 25.0 * next_fit_quality;
        } else {
            // Leftover space too small for the next item: potential dead space.
            // Penalize more when the leftover is small but nonzero (worst dead zones).
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 12.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Context coupling: compare post_residual against mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Fewer fitting bins -> more pressure to use this one.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling already-open bins over opening new ones, especially early/mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless residual would be very usable later.
        score += 18.0 + 10.0 * (1.0 - progress);
    } else {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose leftover can host the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }
    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance urgency: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // New-bin candidate: base post_residual already large; add dynamic guard.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is discouraged more when many bins are already open
        // and the item fits comfortably elsewhere; encouraged when item is big.
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 6.0 * openness - 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is safer.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 18.0;
        }
        // If next item is also large, reserving fresh capacity helps.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild global pressure: prefer bins with residual near the mean (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in stream, dead space matters more (fewer future chances to fill it)
    let dead_penalty = norm_post * norm_post * (1.0 + progress * 3.0) * cap * 0.5;
    score += dead_penalty;

    // Cubic term: extreme fragmentation punished more as stream advances
    score += norm_post.powi(3) * cap * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize slightly, more when good fits exist or late
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - pr / cap) * (n / cap + 0.3);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (n - pr) * 0.15 * (0.5 + progress);
        }
    }

    // Prefer bins below mean residual (concentrate waste in few bins)
    score += 0.1 * (pr - mean_residual).abs().signum() * (pr - mean_residual);

    // Mild preference for tighter bins overall
    score -= 0.05 * item_size as f64 * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item sizes (or near-capacity-friendly classes) are more reusable.
    let cap_frac = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: tiny leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Reward residuals that fall in "harmonic" classes: multiples of 5 or 10
    // align with typical item granularity, making future fits likely.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly prefer this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving slack in harmonic classes for the next-next item.
            if slack <= 10.0 {
                score -= 15.0 - slack;
            } else {
                score += (slack / cap_frac) * 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover at all: dead space risk.
            score += (post / cap_frac) * 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or many bins exist.
    if bin_residual == bin_capacity {
        // Baseline competitiveness: new bin starts with full residual.
        // Penalize it when open bins offer decent fits, reward it when the
        // item is huge relative to typical residual or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let residual_pressure = (mean_residual / cap_frac - item_size as f64 / cap_frac).max(0.0);
        score += residual_pressure * 30.0;
        score -= (1.0 - progress) * 5.0;
        if item_size >= 50 {
            score += 10.0; // big items prefer fresh bins
        }
        if open_bins_count > 8 {
            score += 6.0; // too many open bins: consolidate elsewhere
        }
    } else {
        // Prefer bins whose residual is close to the item (tight packing)
        // beyond the raw post_residual already accounted for.
        let tightness = (bin_residual - item_size) as f64 / cap_frac;
        score += (1.0 - tightness) * 5.0;
    }

    // Mild preference for bins below the mean residual (use up emptier bins).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are unusable
    // and represent pure waste. Penalize them heavily, scaled by how close to
    // zero they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 30.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 200.0;
    }

    // Reward tight fits (post_residual small but still usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 40.0;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins; a new empty bin candidate should be penalized when many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        score += 60.0 + open_bins_count as f64 * 8.0 + progress * 40.0;
    } else {
        score -= open_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving
    // exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaving a gap the next item cannot use: penalize.
        score += (next_item_size - post_residual) as f64 * 4.0;
    }

    // Prefer bins whose residual is already below average (they are "used up"),
    // keeping fresher bins for future items.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.5;
    } else {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a tight fit (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left over that could host the next item: mild penalty for wasted space
            // but bonus when next item fits snugly.
            let next_slack = post_residual - next_item_size;
            score -= 12.0;
            score += 0.25 * next_slack as f64;
            if next_slack == 0 {
                score -= 25.0; // perfect chain: this bin hosts both items
            }
        } else {
            // Next item cannot use the leftover: dead space risk.
            score += 10.0 + 0.15 * (next_item_size.saturating_sub(post_residual)) as f64;
        }
    }

    // Penalize bins far from the mean residual (avoid leaving outliers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the stream
    // or when the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 / bin_capacity as f64; // large when item is small
        // Favor new bin when many bins are open (dispersion is cheap) or fit is bad.
        score = score - 5.0 + 20.0 * (1.0 - progress) + 45.0 * (1.0 - poor_fit);
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when an existing bin is the only option
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize very small dead space only if it is truly unusable: if post_residual
    // cannot accommodate the smallest plausible item (<= 10), it's wasted space.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual <= 20 {
        // Small post residual is good: near-perfect packing, mild bonus.
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let next_fit_ratio = next_item_size as f64 / post_residual as f64;
            if next_fit_ratio > 0.6 {
                score -= 12.0 * next_fit_ratio;
            } else {
                score += 5.0 * (1.0 - next_fit_ratio);
            }
        } else {
            // Next item won't fit here: penalize leaving space the lookahead can't use,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin when existing bins fit well.
        score += 30.0;
        // As the stream progresses, opening new bins is more acceptable
        // (future demand is uncertain, spreading residual can help).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If many bins are open with high mean residual, opening a new bin is cheap.
        score -= 0.05 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Large items fragment bins; prefer a fresh bin for large items when
        // existing residuals are moderate.
        if item_size > 60 {
            score -= 8.0;
        }
    }

    // Mild penalty for using a nearly-full bin when many alternatives exist
    // (keep flexibility), unless it's an exact-ish fit (already rewarded).
    if open_bins_count > 3 && post_residual > 30 && post_residual < 45 {
        score += 3.0;
    }

    // Slight global balance: prefer bins whose residual deviates beneficially
    // from the mean (placing into below-mean-residual bins consolidates waste).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) - norm_pr * (1.0 - progress);

    // Tight fit reward (low post residual) amplified late in stream
    let tight = -1.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = 0.8 * (norm_pr - mean_residual / cap) * (norm_pr - mean_residual / cap);

    // Lookahead: reward if next item could fit the post residual (smooth sigmoid-ish)
    let nx = next_item_size as f64 / cap;
    let look = if next_item_size > 0 {
        -1.0 * (1.0 / (1.0 + (norm_pr - nx) * 20.0)) * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bin bonus: strongly favor when only one bin fits
    let last = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Mild penalty for opening new bins when many bins already fit
    let new_bin_penalty = if bin_residual as f64 == cap {
        0.6 + 0.4 * (open_bins_count as f64 / (1.0 + open_bins_count as f64)) - 2.0 * norm_item
    } else {
        0.0
    };

    score = pr + 10.0 * poly + 10.0 * tight + 5.0 * dead + 5.0 * look + last + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction band does the
    // post-placement residual fall into?
    let quarter = bin_capacity / 4;      // 25
    let eighth = bin_capacity / 8;       // 12
    let sixteenth = bin_capacity / 16;   // 6

    // Penalize residuals that are "dead" — too small to be useful but nonzero.
    if post_residual > 0 && post_residual < sixteenth {
        score += 40.0;
    }

    // Reward residuals that sit in the most reusable harmonic class
    // (multiples of the smallest item quantum band).
    let class = post_residual / eighth;
    match class {
        0 => score += 12.0,                    // tiny leftover: nearly full bin, good
        1 => score -= 6.0,                     // 12..24: fits small items
        2 => score -= 10.0,                    // 24..50: fits mid items, very reusable
        3 => score -= 4.0,
        _ => {}                                // large residual: new-ish bin, neutral
    }

    // Exact harmonic alignment: residual divisible into clean quarters is great.
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or cleanly,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < eighth {
                score -= 14.0; // near-perfect chain
            } else {
                score -= (slack as f64).sqrt(); // mild preference for tight fits
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance logic: only fitting bin -> strong pull to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / 8.0;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - crowded * 10.0 - big_item * 40.0;
        if next_item_size > 0 && next_item_size <= quarter {
            score -= 10.0; // new bin leaves room for small follow-ups
        }
    }

    // Stream progression: early on, prefer compacting into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's post residual is far below the mean,
    // we are compacting well.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // are wasted. Penalize gaps in [1, 10] heavily (unusable zone).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect-fit bonus when the leftover could host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leftover can still host next item: mildly good
        score -= 10.0;
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, tolerate opening new bins less.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0;

    // New-bin candidate handling: empty bin gets a moderate default score so
    // it is chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + pressure * 4.0;
        // if no open bin fits at all, new bin must win
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight nudge toward bins tighter than average (best-fit flavor).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit but avoid dead space that nothing else can use.
    // Perfect-fill reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize very small unusable leftovers (dead space).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 15.0;
        }
    }

    // 2-step lookahead: strongly reward a residual that exactly (or nearly)
    // matches the next item's size — this bin becomes a two-item perfect chain.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits: reward closeness to an exact follow-up match.
            score -= 120.0 * (1.0 - diff / (nxt + 1.0));
            // Exact chain: post_residual == next_item_size => both items fill bin.
            if diff == 0.0 {
                score -= 500.0;
            }
        } else {
            // Next item cannot follow: mild penalty scaled by the gap.
            score += (nxt - pr) * 0.8;
        }
    }

    // Compare against mean residual: placing into a bin whose residual is far
    // below average concentrates packing and keeps other bins flexible.
    let mr = mean_residual;
    let pr = post_residual as f64;
    if pr < mr {
        score -= (mr - pr) * 0.5;
    } else {
        score += (pr - mr) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity). Prefer
    // opening a new bin only when the item is huge relative to typical
    // residuals or no good fit exists; otherwise penalize slightly to keep
    // packing into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream, opening bins is cheap; later, consolidate.
        let new_bin_bias = 60.0 * (1.0 - progress);
        score += 40.0 + new_bin_bias;
        // But if the item barely fits anywhere (huge item), opening fresh is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 150.0;
        }
    }

    // Slight preference for fuller bins overall (lower residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Late-stream consolidation: as stream ends, avoid leaving many open bins.
    if next_item_size == 0 {
        score += 200.0; // never open a bin for the last item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Penalize dead space that the next item cannot use (stronger early, weaker late).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (1.5 - 0.5 * t);
    }

    // Reward a perfect hand-off to the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; grows with average slack in open bins.
        score += 20.0 + 0.1 * mean_residual;
        // If no open bin fits, opening a new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild preference for bins whose residual is close to the fleet mean (balance).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        // Penalize leaving very large residuals if we are late in the stream.
        if post_residual > bin_capacity / 2 && t > 0.7 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr.powf(1.0 + 0.5 * progress);

    // Penalize dead space quadratically, stronger late in the stream
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth saturating term
    score -= 15.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (consolidating waste) via smooth interaction
    score += 5.0 * (pr - mean_residual) / cap;

    // Lookahead: smooth reward if next item can fit into post residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let smooth = (post_residual as f64 - next_item_size as f64 + 1.0).max(0.0) / cap;
        score -= 12.0 * fits_next * smooth - 8.0 * (1.0 - fits_next) * norm_pr;
    }

    // Mild preference for keeping bin count low early, smoothing over stream
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Slight bias against opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on "useful"
    // divisor classes of capacity (multiples of 10, 20, 25) are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 20 == 0 || pr % 25 == 0 {
        -4.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward dead space
    };
    score += harmonic_bonus;

    // Lookahead coupling: reward residual that can host next item exactly,
    // penalize residual that almost fits it (wasted potential).
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 12.0;
        } else if pr >= next_item_size {
            score -= 4.0;
            // harmonic match: residual class equals next item class
            if pr % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot fit here; residual smaller than next item is
            // dead space unless tiny
            if pr < 10 {
                score += 6.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would create severe dead space or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_residual - item_size) as f64;
        score += 18.0 - 10.0 * progress;
        // a fresh bin is attractive if it keeps a highly divisible residual
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 8.0;
        }
        if waste > 60.0 {
            score -= 5.0;
        }
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    // Mild penalty when many bins are open, encouraging consolidation.
    score += 0.15 * open_bins_count as f64;

    // Integer-division threshold on post_residual: residuals < 10 are dead.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item (1..100 stream) become permanent waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Non-linear penalty for mid-range dead space (fits nothing useful later).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Perfect-fill lookahead: if the next item exactly consumes post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item can also land here (chained packing).
        score -= (post_residual - next_item_size) as f64 * 0.15;
    }

    // Last-chance bin before opening a new one: strong preference to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // the emptier a bin is relative to the mean, the less we want to
    // fragment it further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 8.0; // penalize dumping into unusually empty bins
    }

    // New-bin candidate: allow opening a fresh bin only when current item
    // is large and would leave a clean, usable residual, or when the only
    // alternative is a very poor fit.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55; // default: prefer existing bins
        let poor_fit = (post_residual as f64) < 15.0 && post_residual > 0;
        if poor_fit || item_size >= 70 {
            score = base - 18.0; // open new bin for clean placement
        } else {
            score = base + 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits (near-)perfectly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post_residual as f64 - nxt;
        if slack >= 0.0 {
            // Next item fits: reward tightness of the follow-up fit.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to how close it was.
            score += 0.5 * (-slack);
        }
    }

    // Penalize post_residual deviating from the mean residual (avoid fragmentation outliers).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild pressure to fill bins tightly as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space (< next small item) is bad.
    if post_residual > 0 {
        // penalize residuals too small to ever be useful again
        let useless = if post_residual < 10 { 40.0 } else { 0.0 };
        score += useless;
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer perfect closure
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // penalize opening new bins generally, less when many bins open / late stream
        score += 25.0 + 30.0 * (1.0 - progress) - 15.0 * item_frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Prefer fuller bins relative to global mean residual (balance pressure).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for bins whose residual is a multiple-friendly chunk
    // (residuals near common item sizes are reusable).
    let r = post_residual;
    let reusable = (10..=80).map(|s| (r as i32 - s).abs()).min().unwrap_or(100);
    score += 0.08 * reusable as f64;

    // Time horizon coupling: as stream progresses, be greedier (minimize waste now).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = post + 40.0 * post_norm * post_norm;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space increasingly penalized)
    let coupling = post_norm * (1.0 - post_norm) * 4.0; // in [0,1], peak at post_norm=0.5
    score -= 25.0 * coupling * progress;
    score += 30.0 * post_norm * progress * progress;

    // Penalize last-chance bins slightly less if post residual is small
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm) * (1.0 - post_norm);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fit_gap = (post - next).abs();
        if post >= next {
            score -= 12.0 * (1.0 - fit_gap / cap);
        } else {
            score += 8.0 * (next - post) / cap;
        }
    }

    // Mild penalty when this bin's residual deviates from mean (keep residuals uniform)
    score += 0.05 * (post - mean_residual).abs();

    // Encourage consolidation when many bins are open
    score += 0.5 * open_bins_count as f64 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are "reusable" classes -> reward them.
    let r = post_residual;
    let class_bonus: f64 = if r == 0 {
        -30.0 // perfect closure
    } else if r % 50 == 0 {
        -22.0
    } else if r % 25 == 0 {
        -16.0
    } else if r % 20 == 0 {
        -14.0
    } else if r % 10 == 0 {
        -10.0
    } else if r % 5 == 0 {
        -5.0
    } else {
        6.0 // awkward residual class
    };
    score += class_bonus;

    // Dead-space penalty: small awkward residuals that no typical item (>=10) can use
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Integer-division threshold: residual bucket relative to capacity quarters
    let quarter = bin_capacity / 4;
    if r <= quarter {
        score += 8.0; // nearly-full bin, low future utility
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0;
        } else if r >= next_item_size && (r - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if next_item_size > r {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: only one fitting bin -> avoid opening a new bin if fit is decent
    if fitting_bins_count == 1 && r <= quarter * 2 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big item arriving, fresh capacity useful
        }
    }

    // Stream progression: early on, prefer tight packing; late, prefer closing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (r as f64 / bin_capacity as f64);

    // Spread control: bins far below mean residual are less attractive
    score += ((mean_residual - r as f64) * 0.05).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below minimum item size ~1..12)
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate must not look too attractive
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item exactly fills remaining space, reward even more
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: avoid bins far below mean residual (fragmented)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 150.0 * next_fit_quality;
    } else if next_item_size > 0 {
        // next item won't fit here after placement: penalize leaving large unusable gap
        score += 0.5 * (post_residual as f64).min(next_item_size as f64);
    }

    // Compare residual against mean residual across open bins
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: penalize opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual penalizes wasteful fits more.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * (bin_capacity as f64);

    // Exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward chains where the next item also fits this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 - 0.12 * next_item_size as f64;
    }
    // Lookahead: penalize leaving residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // New-bin candidate: penalize opening a new bin when decent alternatives exist,
    // unless the item is large and fits poorly everywhere (post_residual is high anyway).
    if bin_residual == bin_capacity {
        let open_pressure = fitting_bins_count as f64;
        score += 22.0 / open_pressure.max(1.0);
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * t;
    }

    // Prefer filling bins that deviate below the mean residual (balance toward fuller bins).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with more remaining usable structure when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping (favor tight fits)
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward bins whose post-residual matches the lookahead item (k=2 coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 25.0 * (-40.0 * diff * diff).exp();
    } else {
        score -= 10.0 * norm_pr;
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_pr);
    }

    // Smooth pressure from crowding and mean residual
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 15.0 * crowd * fit_ratio * (mean_residual / cap);

    // Late-stream consolidation: penalize leaving large dead space as stream ends
    score += 20.0 * progress * norm_pr * fit_ratio;

    // New-bin candidate penalty unless residual is huge (keep tight bins in play)
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - fit_ratio) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual (but not zero-dead-space obsession).
    if post_residual <= 10 {
        score -= 60.0; // excellent fill
    } else if post_residual <= 20 {
        score -= 35.0;
    } else if post_residual <= 35 {
        score -= 15.0;
    }

    // Harmonic class penalty: dead space in (0,10) that can never host
    // typical items is worse than a chunky residual. Penalize awkward
    // modulo classes of post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    if post_residual > 0 && class < 10 {
        score += 12.0; // awkward sliver class
    }

    // Lookahead: if the next item fits into post_residual, this bin is
    // doubly valuable (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Perfect chain: post_residual exactly equals next item -> zero waste after next
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // dead space that even the lookahead cannot use
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual, so
    // base score is high; but early in the stream, opening bins is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bins early / when few bins are open; penalize later.
        score -= 30.0 * (1.0 - progress);
        score += 20.0 * progress;
        if open_bins_count > 8 {
            score += 25.0; // too many open bins already
        }
    } else {
        // Slight preference for bins tighter than average (best-fit flavor).
        if (post_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Prefer filling already-open bins when many are open (avoid bin sprawl).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 12.0;
    }
    if dead == 0.0 {
        score -= 25.0; // perfect fit reward
    }

    // Favor tight fits: reward small post_residual relative to residual.
    let tightness = post_residual as f64 / bin_residual.max(1) as f64;
    score += tightness * 20.0;

    // Last-chance bin pressure: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0 + progress * 30.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: keep room for the next item if it would fit in post_residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if (bin_residual as u32) >= next_item_size && post_residual > 0 {
            score += 8.0; // this placement destroys room for next item
        }
    }

    // Slight preference for bins below mean residual (consolidate slack).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: huge reward.
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: moderate reward proportional to tightness.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            // Penalize leaving a large gap that next item only partially fills.
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit: penalize, worse when gap is small (wasted dead space).
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Penalize bins far below mean residual (already tight) less; penalize bins far above
    // mean residual (large holes) more.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // or open bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 40.0 + 60.0 * mean_fill;
        }
    }

    // Mild preference to fill existing bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}
